#!/usr/bin/env bash
# ===================================================================
# Demodaten, zweiter Satz: dreissig weitere Projekte.
#
# EIN Aufruf, aus dem Wurzelverzeichnis des Repos, bei laufendem
# Dev-Stack:
#
#     bash demo-daten-30-projekte.sh
#
# Setzt demo-daten-komplett.sh voraus, genauer gesagt dessen sieben
# Konten auf @demo.invalid. Es legt selbst KEINE Konten an: die
# dreissig Beitraege verteilen sich auf die sieben vorhandenen
# studentischen Konten, vier bis fuenf je Person.
#
# Danach stehen zusaetzlich in der Entwicklungsdatenbank:
#
#  30 Projekte      20 PUBLISHED, 4 APPROVED, 3 SUBMITTED, 2 DRAFT,
#                   1 REVISION, verteilt ueber alle elf Studiengaenge
#                   und alle fuenf Fakultaeten
# ~467 Bloecke
# 119 Dateien   echte Bytes im Objektspeicher
#     dazu Mitglieder, Redaktionszuweisung, Schlagworte, Statusverlauf,
#     Kommentare, Reaktionen, Nominierungen und die Top-10-Plaetze 4
#     bis 10.
#
# WIEDERHOLBAR ueber feste ID-Praefixe (d0d00021 bis d0d0002a). Den
# ersten Satz (d0d00011 bis d0d0001a) fasst es nicht an.
#
# ERZEUGT, NICHT VON HAND GESCHRIEBEN. Die Vorlage steht in
# p30/huelle.sh, der Inhalt entsteht aus p30/aus/*.json durch
# p30/bau.py. Aenderungen hier ueberlebt der naechste Lauf nicht.
# ===================================================================
set -euo pipefail

BACKEND="${BACKEND_CONTAINER:-eportfolio-dev-backend-1}"
DB="${DB_CONTAINER:-eportfolio-dev-db-1}"
DB_USER="${POSTGRES_USER:-eportfolio}"
DB_NAME="${POSTGRES_DB:-eportfolio}"
ROOT=/app/var/storage

# Zur Begruendung von "sh -lc" steht der ausfuehrliche Absatz in
# demo-daten-komplett.sh: MSYS schreibt unter Git Bash jedes Argument
# um, das wie ein Unix-Pfad aussieht, sobald es an ein Windows-Programm
# geht. In einer Zeichenkette fasst es den Pfad nicht an.
im_container() { docker exec "$BACKEND" sh -lc "$1"; }

sql() { docker exec -i -e PGCLIENTENCODING=UTF8 "$DB" \
	psql -v ON_ERROR_STOP=1 -q -U "$DB_USER" -d "$DB_NAME" "$@"; }

abbruch() { echo; echo "ABBRUCH: $1" >&2; exit 1; }

# -------------------------------------------------------------------
# 0) Vorbedingungen.
# -------------------------------------------------------------------
echo "== Vorbedingungen =="

command -v docker >/dev/null 2>&1 || abbruch "docker nicht gefunden."
command -v curl   >/dev/null 2>&1 || abbruch "curl nicht gefunden."
command -v tar    >/dev/null 2>&1 || abbruch "tar nicht gefunden."

for c in "$DB" "$BACKEND"; do
	if [ "$(docker inspect -f '{{.State.Running}}' "$c" 2>/dev/null)" != "true" ]; then
		abbruch "Container $c laeuft nicht. Dev-Stack starten:
         docker compose -f compose.base.yml -f compose.dev.yml up -d"
	fi
done
echo "  Container laufen: $DB, $BACKEND"

docker exec "$DB" pg_isready -U "$DB_USER" -d "$DB_NAME" >/dev/null 2>&1 \
	|| abbruch "Die Datenbank $DB_NAME antwortet nicht."

# Die sieben Autor:innen und die drei Redaktions- und Verwaltungskonten
# werden hier nicht angelegt, sondern benutzt. Fehlt eines, faende der
# join nichts und es entstuenden schweigend weniger Projekte, weniger
# Kommentare oder gar keine Pruefspur, ohne dass irgendwo ein Fehler
# sichtbar wuerde.
fehlend=$(sql -tAc "
select string_agg(v.email, ', ')
from (values
  ('lena.brinkmann@demo.invalid'), ('jonas.petersen@demo.invalid'),
  ('aylin.demir@demo.invalid'),    ('malte.focke@demo.invalid'),
  ('sofia.kowalski@demo.invalid'), ('timo.ahrens@demo.invalid'),
  ('claudia.vogt@demo.invalid'),   ('dev-studi@dev.invalid'),
  ('dev-redakteur@dev.invalid'),   ('dev-admin@dev.invalid')
) as v(email)
where not exists (select 1 from app_user u where u.email = v.email);" | tr -d '[:space:]')
[ -z "$fehlend" ] || abbruch "Konten fehlen: $fehlend.
         Erst demo-daten-komplett.sh laufen lassen, das legt die sieben
         Konten auf @demo.invalid an. Die drei dev-Konten entstehen beim
         Start des Backends im Profil dev."

# Stammdaten. Die Projekte greifen Fakultaet, Studiengang, Modul,
# Kategorie und Semester ueber Kuerzel und Namen ab, nicht ueber
# einkopierte UUIDs: die sind auf jedem Rechner andere.
fehlend=$(sql -tAc "
select string_agg(x.was, ', ')
from (
  select 'Fakultaeten'   as was where (select count(*) from faculty)         < 5
  union all select 'Studiengaenge' where (select count(*) from study_program) < 11
  union all select 'Module'        where (select count(*) from module)        < 33
  union all select 'Kategorien'    where (select count(*) from category)      < 8
  union all select 'Semester'      where (select count(*) from semester)      < 4
) x;" | tr -d '[:space:]')
[ -z "$fehlend" ] || abbruch "Stammdaten unvollstaendig: $fehlend.
         Die Datenbank ist nicht vollstaendig migriert."

echo "  Konten und Stammdaten vollstaendig"
echo

# -------------------------------------------------------------------
# 1) Projekte, Bloecke und alles, was am Projekt haengt.
# -------------------------------------------------------------------
echo "== 1/3  Projekte, Bloecke, Kommentare, Reaktionen, Top-10 =="
sql -f - <<'ENDE_SQL_DREISSIG'
-- ===================================================================
-- Demodaten, zweiter Satz: dreissig weitere Projekte.
--
-- Maschinell erzeugt aus den JSON-Dateien unter p30/aus/ durch bau.py.
-- Von Hand geaendert wird hier nichts: der naechste Lauf ueberschreibt es.
--
-- Feste Praefixe, damit sich der Satz wiederfinden und in einem Zug
-- entfernen laesst, ohne den ersten Satz (d0d0001x) zu beruehren:
--   d0d00021 Projekte, d0d00022 Dateizeilen, d0d00024 Kommentare,
--   d0d00025 Reaktionen, d0d00026 Top-10, d0d00027 Nominierungen,
--   d0d00028 Statusverlauf, d0d00029 Mitglieder, d0d0002a Pruefspur.
--
-- Es entstehen KEINE neuen Konten. Die dreissig Beitraege verteilen sich
-- auf die sieben vorhandenen studentischen Konten.
-- ===================================================================

