-- Projekt 11: Abbiegen per Vibration: 21 Hinweise blieben unbemerkt
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000011'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '200 days', now() - interval '140 days'
from (values
(0, 'TABLE_OF_CONTENTS', '{"type":"tableOfContents","attrs":{"entries":[{"text":"Abbiegen, ohne hinzusehen","index":0,"level":1},{"text":"Der Aufbau","index":1,"level":2},{"text":"Der Nutzertest","index":2,"level":2},{"text":"Was ich ändern würde","index":3,"level":2}]}}'),
(1, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"text":"Abbiegen, ohne hinzusehen","type":"text"}]}'),
(2, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Wer in Bremen mit dem Rad einer Route folgt, schaut auf ein Display am Lenker und in dieser Sekunde nicht auf die Straße. In der Fahrradwerkstatt der Hochschule habe ich deshalb zwei Lenkergriffe aufgeschnitten und in jeden einen Vibrationsmotor geklebt: Die Navigation meldet die nächste Abbiegung als Muster in der linken oder rechten Hand. Der Entwurf stand nach zwei Wochen. Der Nutzertest hat ihn danach zur Hälfte wieder eingerissen.","type":"text"}]}'),
(3, 'IMAGE', '{"type":"imageBlock","attrs":{"alt":"Geöffneter Schaumstoffgriff mit eingeklebtem Münzmotor und dünnem Kabel","width":75,"fileId":"d0d00022-0000-4000-8000-110000000001","caption":"Der Motor sitzt unter dem Handballen. Zwei Zentimeter weiter vorn, unter den Fingern, war er kaum noch zu spüren."}}'),
(4, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Der Aufbau","type":"text"}]}'),
(5, 'LIST', '{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Je ein Münzvibrationsmotor mit 10 Millimetern Durchmesser, unter dem Handballen in den Schaumstoffgriff eingelassen","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"ESP32 in einer Dose am Gepäckträger, Verbindung zum Telefon über Bluetooth Low Energy","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Zwei Treiberstufen mit kleinen MOSFETs zwischen Mikrocontroller und Motoren. Der erste Aufbau hing direkt am Pin und hat den ersten ESP32 gekostet.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Routing und Abbiegehinweise auf dem Telefon, Kartendaten aus ","type":"text"},{"text":"OpenStreetMap","type":"text","marks":[{"type":"link","attrs":{"href":"https://www.openstreetmap.org","target":"_blank","rel":"noopener noreferrer"}}]},{"text":". Eine Powerbank hält den Aufbau gut neun Stunden am Laufen.","type":"text"}]}]}]}'),
(6, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Das Signal war zuerst ein einzelner langer Puls von 600 Millisekunden, im Code ","type":"text"},{"text":"pattern_long","type":"text","marks":[{"type":"code"}]},{"text":". Am Schreibtisch war das eindeutig. Auf der Straße nicht: Ein langer Puls ist genau das, was ein Rad ohnehin dauernd tut. ","type":"text"},{"text":"Erst der Wechsel auf drei kurze Pulse mit Pause dazwischen hat das Signal überhaupt von der Fahrbahn unterscheidbar gemacht","type":"text","marks":[{"type":"bold"}]},{"text":", und auch das nur zum Teil, wie der Test dann zeigte.","type":"text"}]}'),
(7, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Der Nutzertest","type":"text"}]}'),
(8, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Elf Personen sind eine feste Strecke von 4,2 Kilometern gefahren, vom Campus Neustadtswall über die Neustadt zum Werdersee. Jede Person fuhr zweimal: einmal mit den Griffen, einmal mit dem Telefon in der Halterung als Vergleich. Das ergibt 22 Fahrten. Ausgewertet sind hier die 11 Fahrten mit Vibration. Die Strecke hat 12 Abbiegungen, davon sechs auf glattem Asphalt, drei auf Kopfsteinpflaster, zwei unmittelbar nach einem Halt und eine im Stand vor einer Ampel. Macht 132 Hinweise. Neben jeder Testperson bin ich mitgefahren und habe jeden Hinweis protokolliert.","type":"text"}]}'),
(9, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Situation","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Hinweise","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"nicht bemerkt","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Seite verwechselt","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Glatter Asphalt, freie Fahrt","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"66","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"1","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Kopfsteinpflaster","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"33","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"14","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"3","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Anfahren nach einem Halt","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"22","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"5","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Stand an der Ampel","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"11","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"0","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"1","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Summe","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"132","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"21","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"7","type":"text","marks":[{"type":"bold"}]}]}]}]}]}'),
(10, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"21 von 132 Hinweisen kamen nicht an, das sind knapp 16 Prozent. Der Ausreißer steht in einer Zeile: Auf Kopfsteinpflaster wurden 14 von 33 Hinweisen nicht bemerkt, also mehr als vier von zehn. Auf glattem Asphalt waren es 2 von 66. Dazu kommen 7 Fälle, in denen die Seite verwechselt wurde; drei davon ebenfalls auf Pflaster, wo beide Hände gleichzeitig durchgeschüttelt werden. Im Stand vor der Ampel hat jede Person jeden Hinweis gespürt, eine Person hat ihn trotzdem der falschen Hand zugeordnet, weil sie sich zur Seite abgestützt hatte.","type":"text"}]}'),
(11, 'GALLERY', '{"type":"galleryBlock","attrs":{"items":[{"alt":"Werkbank mit Lötstation, aufgeschnittenem Lenkergriff und Kleinteilen","fileId":"d0d00022-0000-4000-8000-110000000002"},{"alt":"Fahrrad auf einer Straße mit Kopfsteinpflaster","fileId":"d0d00022-0000-4000-8000-110000000003"}],"caption":"Links die Werkbank, an der die Griffe entstanden sind, rechts der Abschnitt, an dem der Entwurf gescheitert ist","columns":2}}'),
(12, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Auf dem Pflaster vibriert doch sowieso alles. Ich habe zweimal gebremst, weil ich dachte, hinten ist etwas locker.","type":"text"}]},{"type":"paragraph","content":[{"text":"Teilnehmerin 07, Fahrt vom 12. Februar, aus dem Fahrtprotokoll","type":"text","marks":[{"type":"italic"}]}]}]}'),
(13, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Was ich ändern würde","type":"text"}]}'),
(14, 'LIST', '{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Das Muster stärker vom Untergrund abheben: drei Pulse zu je 200 Millisekunden mit 150 Millisekunden Pause, statt einer gleichmäßigen Vibration. Der Kontrast entsteht über die Pausen, nicht über die Stärke.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Den Motor aus dem weichen Griff an die Schelle des Bremshebels setzen. Der Schaumstoff schluckt einen Teil der Amplitude, und genau dort liegt die Hand am festesten auf.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jeden Hinweis zweimal geben, 60 Meter vor der Kreuzung und noch einmal 15 Meter davor. In den Protokollen steht neunmal der Satz, die Person habe den Hinweis erst nach der Kreuzung eingeordnet.","type":"text"}]}]}]}'),
(15, 'DOCUMENT', '{"type":"documentBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-110000000004","fileName":"testprotokoll-lenkernavigation.pdf","size":248320,"caption":"Alle 22 Fahrten mit Zeitstempel je Hinweis, Untergrund und Reaktion, anonymisiert"}}')
) as v(order_index, type, content);

-- Projekt 12: Barrierefreiheit der Hochschul-Webauftritte nach WCAG 2.2
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000012'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '320 days', now() - interval '260 days'
from (values
(0, 'TABLE_OF_CONTENTS', '{"type":"tableOfContents","attrs":{"entries":[{"text":"Was die Startseite dem Screenreader sagt","index":0,"level":1},{"text":"Wie geprüft wurde","index":1,"level":2},{"text":"Was die Befunde zeigen","index":2,"level":2},{"text":"Woran die erste Fassung scheiterte","index":3,"level":2}]}}'),
(1, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"text":"Was die Startseite dem Screenreader sagt","type":"text"}]}'),
(2, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Die Studienangebote der Hochschule stehen auf sechs verschiedenen Webauftritten, gepflegt von vier Redaktionen und zwei Fakultätssekretariaten. Wer sie mit der Tastatur durchgeht, merkt nach zwei Minuten, dass das lange niemand getan hat: Der Fokus verschwindet hinter der klebenden Kopfzeile, und das Aufklappmenü lässt sich öffnen, aber nicht wieder verlassen. Im Modul Webtechnologien haben wir 42 Seitenvorlagen gegen WCAG 2.2 geprüft und die Befunde so aufgeschrieben, dass die Redaktionen damit arbeiten können.","type":"text"}]}'),
(3, 'GALLERY', '{"type":"galleryBlock","attrs":{"items":[{"alt":"Rechnerarbeitsplatz mit zwei Bildschirmen und ausgedrucktem Prüfbogen in einem Bibliotheksraum","fileId":"d0d00022-0000-4000-8000-120000000001"},{"alt":"Fünf Personen an einem Tisch, in der Mitte ein Laptop mit geöffneter Hochschulseite","fileId":"d0d00022-0000-4000-8000-120000000002"}],"caption":"Links der Prüfplatz in der Bibliothek am Neustadtswall, an dem jede Vorlage dreimal durchgegangen wurde. Rechts der gemeinsame Termin am 3. Juli, an dem drei Screenreader-Nutzende die strittigen Befunde entschieden haben.","columns":2}}'),
(4, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Wie geprüft wurde","type":"text"}]}'),
(5, 'LIST', '{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Geprüft wurde gegen WCAG 2.2, Stufe A und AA. Stufe AAA blieb außen vor, weil die Hochschule sie in ihrer Erklärung zur Barrierefreiheit nicht zusagt.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ausgewählt haben wir 42 Seitenvorlagen aus sechs Auftritten: zentrale Website, drei Fakultätsbereiche, Studierendenportal und Veranstaltungskalender.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ein Befund ist eine Stelle in einer Vorlage, nicht auf jeder einzelnen Seite. Eine fehlende Beschriftung in der Kopfzeile zählt einmal und nicht 42 mal.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jede Vorlage lief dreimal durch: mit der Tastatur allein, mit NVDA unter Firefox und mit VoiceOver auf einem iPhone. Zwei Personen füllten den Prüfbogen unabhängig aus, strittige Fälle kamen in den gemeinsamen Termin.","type":"text"}]}]}]}'),
(6, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Was die Befunde zeigen","type":"text"}]}'),
(7, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Erfolgskriterium (WCAG 2.2)","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Stufe","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Befunde","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"nachgearbeitet","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"offen","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"1.1.1 Nicht-Text-Inhalte","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"A","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"31","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"27","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"4","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"1.4.3 Kontrast (Minimum)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"AA","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"24","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"18","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"6","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2.4.7 Fokus sichtbar","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"AA","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"17","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"17","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"0","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"4.1.2 Name, Rolle, Wert","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"A","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"14","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"5","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"9","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"3.3.2 Beschriftungen und Anweisungen","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"A","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"12","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"6","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"6","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2.4.11 Fokus nicht verdeckt","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"AA","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"9","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"3","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"6","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Alle Kriterien","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"A und AA","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"107","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"76","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"31","type":"text","marks":[{"type":"bold"}]}]}]}]}]}'),
(8, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Zwei Kriterien tragen mehr als die Hälfte. ","type":"text"},{"text":"55 der 107 Befunde sind fehlende Alternativtexte und zu schwache Kontraste, und beides entsteht nicht im Code, sondern beim Einpflegen.","type":"text","marks":[{"type":"bold"}]},{"text":" Alternativtexte fehlen dort, wo die Redaktion ein Bild ohne Pflichtfeld hochladen kann; die Kontraste reißen dort, wo ein Fakultätsbereich seine eigene Akzentfarbe über die Vorlage gelegt hat. Am schnellsten erledigt war 2.4.7: Der Fokusrahmen war in der gemeinsamen CSS-Datei abgeschaltet, ein Wiedereinschalten hat alle 17 Befunde auf einmal geräumt.","type":"text"}]}'),
(9, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Woran die erste Fassung scheiterte","type":"text"}]}'),
(10, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Die erste Fassung der Prüfung war ein Skript: axe-core über die Sitemap, Ergebnis als CSV, fertig in elf Minuten. Es lief gegen das ausgelieferte HTML, also gegen geschlossene Menüs, leere Suchfelder und Karussells im ersten Bild. Es meldete 44 Stellen, 9 davon waren Fehlalarme an schmückenden Bildern, und die Tastaturfalle im Aufklappmenü stand in keiner Zeile. Die übrigen 72 Befunde hat erst die Prüfung von Hand gefunden. Automatisch blieb deshalb nur, was sich wirklich rechnen lässt, vor allem der Kontrast:","type":"text"}]}'),
(11, 'CODE', '{"type":"codeBlock","attrs":{"language":"javascript"},"content":[{"text":"const kanaele = (hex) =>\n  [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255);\n\nfunction leuchtdichte(hex) {\n  const [r, g, b] = kanaele(hex).map((c) =>\n    c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4\n  );\n  return 0.2126 * r + 0.7152 * g + 0.0722 * b;\n}\n\nexport function kontrast(vorne, hinten) {\n  const a = leuchtdichte(vorne);\n  const b = leuchtdichte(hinten);\n  const [hell, dunkel] = a > b ? [a, b] : [b, a];\n  return (hell + 0.05) / (dunkel + 0.05);\n}\n\n// Linkblau auf hellem Grau: 3.8 statt der geforderten 4.5\nkontrast(\"#1b7fbf\", \"#eceff1\").toFixed(1);","type":"text"}]}'),
(12, 'EMBED', '{"type":"embedBlock","attrs":{"provider":"codepen","embedUrl":"https://codepen.io/codepen/embed/PNaGbb","height":460}}'),
(13, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Ich höre auf eurer Startseite erst 38 Links, bevor irgendwo Inhalt kommt. Mit der Sprungmarke, die ihr eingebaut habt, bin ich in zwei Tastendrücken beim Text. Das ist der Unterschied zwischen Abbrechen und Weiterlesen.","type":"text"}]},{"type":"paragraph","content":[{"text":"Rückmeldung einer blinden Mitarbeiterin der Zentralen Studienberatung nach dem zweiten Prüftermin","type":"text","marks":[{"type":"italic"}]}]}]}'),
(14, 'DOCUMENT', '{"type":"documentBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-120000000003","fileName":"befundliste-wcag.pdf","size":198400,"caption":"Alle 107 Befunde einzeln, mit Vorlage, Erfolgskriterium, Schweregrad und dem Stand der Nacharbeit vom 11. Juli 2025."}}'),
(15, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Prüfbogen und Kontrastwerkzeug liegen im ","type":"text"},{"text":"GitLab der Hochschule","type":"text","marks":[{"type":"link","attrs":{"href":"https://gitlab.hs-bremen.de/webtechnologien/wcag-pruefung","rel":"noopener noreferrer","target":"_blank"}}]},{"text":", die Befundliste oben nennt jede Stelle einzeln. ","type":"text"},{"text":"31 Befunde stehen weiterhin offen, 22 davon in zwei Vorlagen des Redaktionssystems, an denen wir keinen Schreibzugriff haben.","type":"text","marks":[{"type":"textStyle","attrs":{"color":"amber"}}]},{"text":" Bis eine Redaktion sie übernimmt, bleibt es dabei. Und ohne jemanden, der neue Vorlagen vor der Freischaltung durchgeht, sammeln sich die nächsten hundert Befunde von selbst wieder an.","type":"text"}]}')
) as v(order_index, type, content);

-- Projekt 13: Rüttelkarte der Radwege: 134 Schäden aus 213 Verdachtsstellen
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000013'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '70 days', now() - interval '20 days'
from (values
(0, 'TABLE_OF_CONTENTS', '{"type":"tableOfContents","attrs":{"entries":[{"text":"84 Kilometer mit dem Sensorrad","index":0,"level":1},{"text":"Der Aufbau am Gepäckträger","index":1,"level":2},{"text":"Woran die erste Fassung scheiterte","index":2,"level":2},{"text":"Was aus den 213 Verdachtsstellen wurde","index":3,"level":2}]}}'),
(1, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"text":"84 Kilometer mit dem Sensorrad","type":"text"}]}'),
(2, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Dass ein Radweg holprig ist, merkt jede Person nach zehn Metern. In einer Zustandsliste steht davon nichts, weil die Erfassung am Fahrbahnrand endet. Für diese Lehrveranstaltung haben wir ein ausgemustertes Stadtrad aus der Hochschulwerkstatt mit einem Beschleunigungssensor bestückt und damit acht Routen zwischen Neustadtswall, Werdersee und Überseestadt abgefahren, jede Route dreimal, zusammen ","type":"text"},{"text":"84 Kilometer in 24 Messfahrten","type":"text","marks":[{"type":"bold"}]},{"text":", alle bei trockener Fahrbahn und mit derselben Person im Sattel.","type":"text"}]}'),
(3, 'IMAGE', '{"type":"imageBlock","attrs":{"alt":"Stadtrad in einer Werkstatt, am Gepäckträger eine kleine graue Box mit Kabel","width":75,"fileId":"d0d00022-0000-4000-8000-130000000000","caption":"Das Messrad steht sonst in der Fahrradwerkstatt der Hochschule und wird zwischen den Fahrten nicht umgebaut"}}'),
(4, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Der Aufbau am Gepäckträger","type":"text"}]}'),
(5, 'LIST', '{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Beschleunigungssensor starr an die Strebe des Gepäckträgers geschraubt, ohne Gummi dazwischen, weil jede Dämpfung genau das wegnimmt, was gemessen werden soll","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Abtastung mit 200 Hertz auf einen Mikrocontroller mit SD-Karte, eine Datei je Fahrt","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"GPS-Empfänger mit einer Position pro Sekunde; der gemeinsame Zeitstempel verbindet Ort und Erschütterung","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Reifendruck vor jeder Fahrt auf 3,5 bar geprüft. Bei 2,5 bar verschwindet die Hälfte der Kanten im Reifen, und die Fahrt ist unbrauchbar","type":"text"}]}]}]}'),
(6, 'GALLERY', '{"type":"galleryBlock","attrs":{"items":[{"alt":"Geöffnete Sensorbox mit Platine, Kabelbindern und SD-Karte auf einem Gepäckträger","fileId":"d0d00022-0000-4000-8000-130000000001"},{"alt":"Radweg mit aufgewölbtem Asphalt über einer Baumwurzel, daneben ein Zollstock","fileId":"d0d00022-0000-4000-8000-130000000002"}],"caption":"Links die zweite Fassung der Halterung, rechts eine der 57 Wurzelstellen; der Zollstock liegt auf jedem Begehungsfoto mit im Bild","columns":2}}'),
(7, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Woran die erste Fassung scheiterte","type":"text"}]}'),
(8, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Zuerst hing das Ganze am Lenker, weil dort die Halterung schon vorhanden war. Das Ergebnis war eine Messung der Gabel und nicht der Fahrbahn: In den Aufzeichnungen dominierte ein Ausschlag um 18 Hertz, der auch auf frisch asphaltiertem Belag auftrat. Der zweite Fehler blieb länger unentdeckt. Schnelle Fahrten erzeugten mehr Meldungen als langsame, obwohl es dieselbe Strecke war, und der Vergleich zweier Routen sagte am Ende mehr über die Ampelphasen als über den Belag. Auch die Verortung stimmte nicht: Unter den Pappeln am Werdersee lag die GPS-Position bis zu 12 Meter daneben, sodass Stellen auf der falschen Wegseite landeten. Seit der zweiten Fassung sitzt der Sensor am Gepäckträger, die Position wird auf die gefahrene Spur eingerastet, und der Kennwert wird durch die Geschwindigkeit geteilt:","type":"text"}]}'),
(9, 'FORMULA', '{"type":"mathBlock","attrs":{"latex":"R = \\frac{1}{v}\\sqrt{\\frac{1}{N}\\sum_{i=1}^{N} a_{z,i}^{2}}, \\quad v > 3\\,\\frac{\\mathrm{m}}{\\mathrm{s}}"}}'),
(10, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Was aus den 213 Verdachtsstellen wurde","type":"text"}]}'),
(11, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Art der Stelle","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Anzahl","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Befund bei der Begehung","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Wurzelaufbruch im Belag","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"57","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Pappeln und Linden, 41 davon auf der Route am Werdersee","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Loch oder ausgebrochene Kante","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"41","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"meist an Flickstellen früherer Aufgrabungen","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Absenkung an einer Zufahrt","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"36","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Stufe an der Bordsteinkante über zwei Zentimeter","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Kopfsteinpflaster, kein Schaden","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"62","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"durchgehender Belag, kein einzelner Defekt","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Fehlmeldung","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"17","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"drei Bahnübergänge, elf Bremsmanöver, drei Fahrten mit lockerer Schraube","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Summe","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"213","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"jede Stelle einmal zu Fuß aufgesucht und fotografiert","type":"text"}]}]}]}]}'),
(12, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Nach der Begehung bleiben ","type":"text"},{"text":"134 echte Schäden","type":"text","marks":[{"type":"textStyle","attrs":{"color":"amber"}}]},{"text":". Die 62 Kopfsteinpflasterstellen sind kein Fehler des Verfahrens, sondern eine Frage der Definition: Der Kennwert misst, wie unangenehm eine Strecke ist, und das historische Pflaster in der Überseestadt ist unangenehm, ohne kaputt zu sein. Wir führen es deshalb als eigene Klasse und nicht als Treffer. Bei den 17 Fehlmeldungen war die Ursache jedes Mal am Zeitstempel zu erkennen; elf davon waren Bremsmanöver, und zwar immer an denselben vier Kreuzungen.","type":"text"}]}'),
(13, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Die Karte zeigt uns wenig Neues. Neu ist, dass wir jetzt begründen können, welche der 57 Wurzelstellen zuerst drankommt.","type":"text"}]},{"type":"paragraph","content":[{"text":"Rückmeldung aus der Abschlussbesprechung der Lehrveranstaltung","type":"text","marks":[{"type":"italic"}]}]}]}'),
(14, 'DOCUMENT', '{"type":"documentBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-130000000003","fileName":"ruettelkarte-auswertung.pdf","size":486000,"caption":"Auswertung mit Kartenauszug je Route und der vollständigen Liste der 213 Stellen samt Foto-Nummer"}}'),
(15, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Die Veranstaltung hing an keinem festen Modul, sondern war ein offenes Angebot des Studiengangs, und das hat gutgetan: In der Gruppe saßen Leute, die mit Karten arbeiten, und Leute, die löten. Die Rohdaten liegen als CSV je Fahrt in der Werkstatt, ","type":"text"},{"text":"fahrt-07.csv","type":"text","marks":[{"type":"code"}]},{"text":" ist die Runde über die Wilhelm-Kaisen-Brücke und eignet sich zum Nachrechnen, weil dort alle fünf Klassen auf drei Kilometern vorkommen. Wer die Messung wiederholt, sollte den Reifendruck mitschreiben; ohne diese Zeile sind die Kennwerte zweier Fahrten nicht vergleichbar.","type":"text"}]}')
) as v(order_index, type, content);

-- Projekt 14: Vorlesungsaufzeichnungen untertiteln, in drei Entwurfsfassungen
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000014'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '460 days', now() - interval '380 days'
from (values
(0, 'TABLE_OF_CONTENTS', '{"type":"tableOfContents","attrs":{"entries":[{"text":"Warum die automatische Untertitelspur nicht reicht","index":0,"level":1},{"text":"Drei Fassungen der Untertitelspur","index":1,"level":2},{"text":"Was korrigiert werden musste","index":2,"level":2}]}}'),
(1, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"type":"text","text":"Warum die automatische Untertitelspur nicht reicht"}]}'),
(2, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Die Aufzeichnungsanlage im Hörsaal AB-201 legt zu jedem Video eine automatische Untertitelspur an. Wer sie einmal mit ausgeschaltetem Ton benutzt, merkt in der ersten Minute, dass sie zum Mitkommen nicht reicht: Fachbegriffe stehen falsch da, Sätze laufen ohne Punkt ineinander, und wer gerade spricht, steht nirgends. Zwei hörbeeinträchtigte Studierende des Moduls haben sich im Wintersemester 2024/25 deshalb auf Mitschriften von Kommilitonen verlassen. Dieses Forschungsprojekt ist eine Werkstattarbeit: Wir haben neun Aufzeichnungen des Moduls von Hand aufbereitet und in drei Entwurfsfassungen festgehalten, woran eine brauchbare Spur hängt."}]}'),
(3, 'IMAGE', '{"type":"imageBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-140000000001","alt":"Arbeitstisch mit ausgedruckten Bildschirmentwürfen einer Untertitelspur und beschrifteten Karteikarten","caption":"Die Entwürfe hingen ausgedruckt an der Wand, weil am Bildschirm niemand zwei Fassungen nebeneinander hält. Die Karten links sind der erste Stand des Fachglossars.","width":75}}'),
(4, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Drei Fassungen der Untertitelspur"}]}'),
(5, 'LIST', '{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fassung 1: drei Zeilen zu 42 Zeichen, mittig unter dem Videobild. Auf einem 14-Zoll-Bildschirm verdeckte der Block das untere Drittel der Tafel, also genau die Stelle, an der gerechnet wird"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fassung 2: zwei Zeilen zu 37 Zeichen, an den unteren Rand gerückt und auf halbdurchsichtigem Grund. Die Tafel blieb frei, die Fachbegriffe standen weiter falsch da"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fassung 3: ein Glossar mit 214 Begriffen aus den Modulunterlagen, ein Regelsatz für Satzgrenzen und Zeilenumbruch, dazu ein Namenskürzel vor jedem Sprecherwechsel"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Der Ablauf je Aufzeichnung: Rohspur aus der Spracherkennung, Glossarlauf, Handkorrektur, Gegenlesen durch eine zweite Person"}]}]}]}'),
(6, 'AUDIO', '{"type":"audioBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-140000000002","caption":"Vierzig Sekunden aus dem Hörsaal AB-201, aufgenommen vom Deckenmikrofon. Der Nachhall zieht die Silben ineinander; aus dem Fitts-Gesetz machte die Spracherkennung in sieben von neun Aufzeichnungen ein Fits-Gesetz."}}'),
(7, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Das Material sind neun Aufzeichnungen aus dem Wintersemester 2024/25, zusammen 11 Stunden 20 Minuten. Als Korrektur gezählt ist jede Stelle, an der die ausgelieferte Spur von der Rohspur der Spracherkennung abweicht; reine Zeitverschiebungen unter 200 Millisekunden bleiben draußen. So kommen wir auf "},{"type":"text","text":"1.472 Stellen","marks":[{"type":"bold"}]},{"type":"text","text":". Jede Aufzeichnung hat eine zweite Person gegengelesen und dabei 41 weitere Stellen gefunden, die in der Zählung stecken. Die fertige Spur haben wir anschließend mit der Beratungsstelle Barrierefreies Studium gesichtet, Aufzeichnung für Aufzeichnung, ohne Vergleichsgruppe und ohne Stoppuhr."}]}'),
(8, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Die erste Fassung ist an der Tafel gescheitert. Gebaut war sie nach der Vorgabe für Fernsehuntertitel, drei Zeilen zu 42 Zeichen, und auf dem großen Bildschirm im Labor sah das gut aus. Auf den 14-Zoll-Geräten, mit denen die Aufzeichnungen tatsächlich angesehen werden, stand der Block über der unteren Tafelhälfte. Der zweite Fehler war teurer: Das Glossar ersetzte anfangs auf Wortstämmen und machte in 63 Fällen aus einem Modell ein mentales Modell, auch dort, wo vom Datenmodell die Rede war. Seit der dritten Fassung greift die Ersetzung nur bei ganzen Wörtern und nur außerhalb von Zitaten; die 63 Stellen haben wir von Hand zurückgedreht."}]}'),
(9, 'IMAGE', '{"type":"imageBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-140000000003","alt":"Studentin mit Kopfhörern vor einem Laptop an einem Bibliothekstisch","caption":"Angesehen wird am eigenen Gerät, nicht im Labor. Auf 14 Zoll bleibt neben dem Videobild rund ein Drittel der Fläche für alles andere, und darum ist die Spur seit Fassung 2 zweizeilig.","width":100}}'),
(10, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Was korrigiert werden musste"}]}'),
(11, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Art der Korrektur"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Stellen"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Vom Glossar erledigt"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Handarbeit"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Fachbegriff falsch geschrieben"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"613"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"486"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"127"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Satzgrenze und Zeichensetzung"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"402"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"231"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"171"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sprecherwechsel nicht markiert"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"178"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"0"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"178"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Tafelanschrift fehlt im Ton"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"164"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"0"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"164"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Englischer Begriff eingedeutscht"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"115"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"88"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"27"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Summe"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"1.472"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"805"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"667"}]}]}]}]}'),
(12, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Das Glossar nimmt gut die Hälfte der Arbeit ab, 805 von 1.472 Stellen, aber es nimmt die leichtere Hälfte. Übrig bleiben die Stellen, an denen jemand zuhören und mitdenken muss: Sprecherwechsel und Tafelanschriften stehen in keiner Liste und machen zusammen 342 Stellen aus. Für 11 Stunden 20 Minuten Material sind "},{"type":"text","text":"21 Stunden Handarbeit","marks":[{"type":"bold"}]},{"type":"text","text":" angefallen, knapp das Doppelte der Spielzeit. Eine ganze Vorlesungsreihe nebenher aufzubereiten ist damit nicht zu schaffen."}]}'),
(13, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Was mir am meisten hilft, ist das Kürzel vor dem Sprecherwechsel. Ohne das lese ich eine Frage aus dem Saal als Teil des Vortrags und wundere mich zwei Minuten lang."}]},{"type":"paragraph","content":[{"type":"text","text":"Teilnehmerin der Sichtungsrunde, Beratungsstelle Barrierefreies Studium, 12. Dezember 2024","marks":[{"type":"italic"}]}]}]}'),
(14, 'DOCUMENT', '{"type":"documentBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-140000000004","fileName":"untertitelregeln-und-glossar.pdf","size":268000,"caption":"Der Regelsatz für Zeilenumbruch, Zeichensetzung und Sprecherkürzel, dazu das Fachglossar mit 214 Begriffen und der Liste der 63 zurückgedrehten Ersetzungen"}}'),
(15, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Die drei Fassungen liegen als Vorlage bei der "},{"type":"text","text":"Beratungsstelle Barrierefreies Studium","marks":[{"type":"link","attrs":{"href":"https://www.hs-bremen.de/","target":"_blank","rel":"noopener noreferrer"}}]},{"type":"text","text":"; wer die nächste Aufzeichnung aufbereitet, fängt nicht bei null an. Der teure Teil bleibt offen: Sprecherwechsel und Tafelanschrift kommen weiter von Hand dazu. Im nächsten Schritt wertet der Regelsatz die Saalmikrofone getrennt aus und soll einen Sprecherwechsel wenigstens vorschlagen; ob das die 178 Stellen nennenswert drückt, zeigt der Durchlauf mit den Aufzeichnungen des Sommersemesters."}]}')
) as v(order_index, type, content);

-- Projekt 15: Brettsperrholz im Feuchtewechsel: weicher, nicht schwächer
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000015'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '190 days', now() - interval '130 days'
from (values
(0, 'TABLE_OF_CONTENTS', '{"type":"tableOfContents","attrs":{"entries":[{"text":"Trocken gerechnet, feucht eingebaut","index":0,"level":1},{"text":"Der Prüfstand","index":1,"level":2},{"text":"Was die 90 Versuche ergeben","index":2,"level":2},{"text":"Woran die erste Serie gescheitert ist","index":3,"level":2}]}}'),
(1, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"text":"Trocken gerechnet, feucht eingebaut","type":"text"}]}'),
(2, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Brettsperrholz wird im Werk bei 20 Grad und 65 Prozent Luftfeuchte verleimt und auf der Baustelle in den Novemberregen gestellt. Bemessen wird es trotzdem für Nutzungsklasse 1, weil die Platte nach dem Schließen der Gebäudehülle wieder austrocknet. Was dieses Hin und Her mit den Schrauben macht, die zwei Platten verbinden, steht in keiner Zulassung. Für dieses Praxisprojekt haben wir aus dem Verschnitt einer Baustelle in der Überseestadt Prüfkörper gebaut, sie zwölf Wochen lang in zwei Klimaten gelagert und einzeln im Scherversuch bis zum Bruch gefahren. Gewertet sind 90 Versuche, 54 davon aus dem Feuchtewechsel.","type":"text"}]}'),
(3, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Der Prüfstand","type":"text"}]}'),
(4, 'LIST', '{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Universalprüfmaschine mit 100-kN-Kraftmessdose, weggesteuert mit 2 Millimeter pro Minute bis zum Bruch der Verbindung","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Prüfkörper aus zwei Streifen fünfschichtigem Brettsperrholz, 140 Millimeter dick, einschnittig überlappend und mit einer Vollgewindeschraube 8 mal 160 Millimeter verbunden; jede Serie über alle sechs Platten verteilt, damit keine einzelne Platte eine Serie trägt","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Schraube entweder senkrecht zur Plattenebene oder um 45 Grad geneigt eingedreht, in beiden Fällen mit 5 Millimeter vorgebohrt und drehmomentgeregelt gesetzt","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Feuchtewechsel in der Klimakammer: drei Zyklen aus je zwei Wochen bei 85 Prozent und zwei Wochen bei 40 Prozent relativer Luftfeuchte, immer bei 20 Grad; die Vergleichsserien standen zwölf Wochen durchgehend bei 65 Prozent","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Verschiebung an zwei induktiven Wegaufnehmern unmittelbar an der Fuge, Rohdichte je Prüfkörper im Mittel 448 kg/m³, Holzfeuchte im Darrverfahren: 11,8 Prozent in den Vergleichsserien, 8,3 Prozent nach dem letzten trockenen Halbzyklus","type":"text"}]}]}]}'),
(5, 'GALLERY', '{"type":"galleryBlock","attrs":{"items":[{"alt":"Gestapelte Streifen aus Brettsperrholz mit sichtbaren Längsfugen in der Decklage","fileId":"d0d00022-0000-4000-8000-150000000001"},{"alt":"Prüfkörper aus zwei überlappenden Holzstreifen mit schräg eingedrehter Schraube, daneben der Wegaufnehmer","fileId":"d0d00022-0000-4000-8000-150000000002"}],"caption":"Links die Streifen vor der Einlagerung, rechts ein fertiger Prüfkörper. Die Fuge zwischen zwei Brettern der Decklage ist im Werk nicht verklebt und auf der geschliffenen Fläche kaum zu sehen.","columns":2}}'),
(6, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Gemessen haben wir zwei Größen: die Höchstkraft und den Verschiebungsmodul K","type":"text"},{"text":"ser","type":"text","marks":[{"type":"subscript"}]},{"text":", also die Steigung der Kraft-Weg-Kurve zwischen 10 und 40 Prozent der Höchstlast. Die Norm schätzt ihn allein aus Rohdichte und Schraubendurchmesser; für 448 kg/m³ und 8 Millimeter stehen dort 3,3 kN/mm, und eine Holzfeuchte kommt in dieser Gleichung nicht vor. Genau das war die Frage des Projekts: Wie lange gilt ein Wert, der vom Klima nichts weiß?","type":"text"}]}'),
(7, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Was die 90 Versuche ergeben","type":"text"}]}'),
(8, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Serie","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Prüfkörper und Klima","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Versuche","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Mittlere Höchstkraft","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Verschiebungsmodul","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"A","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Normklima 20/65, Schraube 90 Grad","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"18","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"6,8 kN","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"3,4 kN/mm","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"B","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Normklima 20/65, Schraube 45 Grad","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"18","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"11,4 kN","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"12,6 kN/mm","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"C","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Feuchtewechsel, Schraube 90 Grad","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"18","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"6,4 kN","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2,2 kN/mm","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"D","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Feuchtewechsel, Schraube 45 Grad","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"18","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"10,6 kN","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"8,1 kN/mm","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"E","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Feuchtewechsel, 45 Grad in der Schmalseitenfuge","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"18","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"6,9 kN","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"4,9 kN/mm","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"alle","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Serien A bis E zusammen","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"90","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"8,4 kN","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"6,2 kN/mm","type":"text"}]}]}]}]}'),
(9, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Der Vergleich, auf den es ankommt, ist C gegen A: gleiche Schraube, gleicher Winkel, nur ein anderes Klima. Die Höchstkraft fällt um knapp sechs Prozent und bleibt damit im Rahmen der Streuung. Der Verschiebungsmodul fällt ","type":"text"},{"text":"um gut ein Drittel","type":"text","marks":[{"type":"bold"}]},{"text":", bei den geneigten Schrauben ebenso, dort von 12,6 auf 8,1 kN/mm. Dabei waren die Prüfkörper der Wechselserien am Prüftag mit 8,3 Prozent Holzfeuchte trockener als die Vergleichsserien und hätten danach steifer sein müssen. Der harte Befund steckt in Serie E. Trifft die geneigte Schraube die unverklebte Fuge zwischen zwei Brettern der Decklage, bleiben von 10,6 kN noch ","type":"text"},{"text":"6,9 kN","type":"text","marks":[{"type":"highlight","attrs":{"color":"amber"}}]},{"text":". In vier dieser Versuche klaffte die Fuge auf, bevor die Schraube überhaupt nennenswert nachgab.","type":"text"}]}'),
(10, 'DOCUMENT', '{"type":"documentBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-150000000003","fileName":"pruefprotokoll-scherversuche.pdf","size":2456780,"caption":"Kraft-Weg-Kurven aller 90 Versuche, je Serie ein Blatt, dazu Rohdichte und Holzfeuchte jedes Prüfkörpers"}}'),
(11, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Woran die erste Serie gescheitert ist","type":"text"}]}'),
(12, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"In der Tabelle stehen 90 Versuche, gemacht haben wir 104. Bei den ersten sechs saß der Wegaufnehmer an der Traverse, sodass die Nachgiebigkeit der Maschine im Verschiebungsmodul mitgemessen wurde; seitdem sitzen zwei Aufnehmer unmittelbar an der Fuge. Die nächsten acht kamen aus der Klimakammer und lagen drei Tage offen im Labor, bevor wir sie geprüft haben. Das reichte: die Randzone hatte sich auf 10,6 Prozent zurückgestellt, die Werte lagen zwischen den beiden Klimaten und streuten mit 38 Prozent. Alle 90 gewerteten Prüfkörper sind seitdem in Folie eingeschweißt aus der Kammer geholt und binnen zwei Stunden geprüft worden.","type":"text"}]}'),
(13, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Wenn die Streuung größer ist als der Unterschied, den Sie zeigen wollen, haben Sie noch keinen Versuch, sondern eine Sammlung von Zahlen.","type":"text"}]},{"type":"paragraph","content":[{"text":"Anmerkung des Laboringenieurs, nachdem wir ihm die ersten acht Kurven gezeigt hatten","type":"text","marks":[{"type":"italic"}]}]}]}'),
(14, 'DIVIDER', '{"type":"horizontalRule"}'),
(15, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Bleibt die Frage, was davon auf die Baustelle geht. Für die Tragfähigkeit ändert der Feuchtewechsel wenig, für alles, was über Verformung nachgewiesen wird, ändert er viel: eine Fuge, die mit 3,4 kN/mm gerechnet und mit 2,2 kN/mm gebaut ist, verschiebt sich unter derselben Last um gut die Hälfte mehr. Unser Vorschlag an das Ingenieurbüro, das die Platten geplant hat: Die Schmalseitenfugen der Decklage sind auf der rohen Platte gut zu sehen, solange nichts verspachtelt ist. Wer sie vor dem Setzen der Schrauben anzeichnet und das Schraubenbild um drei Zentimeter versetzt, braucht dafür fünf Minuten je Platte und keine Klimakammer.","type":"text"}]}')
) as v(order_index, type, content);

-- Projekt 16: Kolk an der Kleinen Wümme nur hinter dem steilsten Raubaum
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000016'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '300 days', now() - interval '250 days'
from (values
(0, 'TABLE_OF_CONTENTS', '{"type":"tableOfContents","attrs":{"entries":[{"text":"Raubäume in der Kleinen Wümme","index":0,"level":1},{"text":"Der Aufbau am Ufer","index":1,"level":2},{"text":"Die Juni-Reihe war unbrauchbar","index":2,"level":2},{"text":"104 Einzelmessungen an acht Stellen","index":3,"level":2}]}}'),
(1, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"text":"Raubäume in der Kleinen Wümme","type":"text"}]}'),
(2, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Ein Raubaum ist ein gefällter Baum, der mit dem Stammfuß am Ufer verankert wird und mit der Krone in die Strömung ragt. Der Unterhaltungsverband hat im Winter 2023/24 sechs davon auf 380 Metern der Kleinen Wümme eingebaut, um die Sohle wieder in Bewegung zu bringen. Aus der Zimmererlehre kenne ich Holz als Bauteil, das Lasten abträgt; hier ist es ein Bauteil, das Wasser umlenkt. Was es mit der Sohle macht, stand für diese Strecke nirgends in Zahlen, also haben wir ","type":"text"},{"text":"104 Einzelmessungen an drei Terminen","type":"text","marks":[{"type":"bold"}]},{"text":" aufgenommen.","type":"text"}]}'),
(3, 'IMAGE', '{"type":"imageBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-160000000001","alt":"Ein quer im Bach liegender Baumstamm mit Ästen im Wasser, davor eine senkrecht eingestellte Messlatte","caption":"Raubaum R4 am Messtag im August. Der Stamm steht rund 40 Grad zum Ufer, das ist der größte Einbauwinkel der Strecke.","width":100}}'),
(4, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Der Aufbau am Ufer","type":"text"}]}'),
(5, 'LIST', '{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Zwei Festpunkte je Messstelle im Ufer: Eichenpflöcke mit einem Zimmermannsnagel im Kopf, mit dem Nivelliergerät an den Pegel Borgfeld angeschlossen","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Über die Pflöcke eine gespannte Schnur als Profillinie, daran die Lotrechten in festem Abstand abgetragen","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Selbst gebaute Messlatte für Wassertiefe und Sohlhöhe, Teilung eingefräst statt aufgeklebt","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Magnetisch-induktive Sonde für die Geschwindigkeit, je Lotrechte zwei Punkte, 30 Sekunden Mittelungszeit","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nullpunktkontrolle der Sonde im Eimer vor und nach jeder Messstelle, Wert direkt ins Protokoll","type":"text"}]}]}]}'),
(6, 'IMAGE', '{"type":"imageBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-160000000002","alt":"Werkbank mit einem gehobelten Lärchenbrett, in das eine Zentimeterteilung eingefräst ist","caption":"Die Latte ist aus einem Rest Lärche vom Dachstuhl der Lehre. Lärche arbeitet im Wechsel von nass und trocken weniger als Fichte, und eine gefräste Teilung schwimmt nicht ab.","width":75}}'),
(7, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Die Juni-Reihe war unbrauchbar","type":"text"}]}'),
(8, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Der erste Termin am 17. Juni ist vollständig in den Papierkorb gegangen, aus zwei Gründen. Erstens waren wir mit einem hydrometrischen Messflügel im Wasser: Im Krautbestand blieb er entweder stehen oder zählte Umdrehungen, die von Pflanzenteilen kamen. Von 22 Lotrechten waren am Ende 5 plausibel. Zweitens hatten wir die Messlatte am Raubaum selbst angelehnt, weil das bequem war. ","type":"text"},{"text":"Der Stamm bewegt sich im Wasser, die Sohlhöhen lagen bei der Kontrolle um bis zu 7 Zentimeter daneben.","type":"text","marks":[{"type":"bold"}]},{"text":" Seitdem hängt die Latte an der Schnur zwischen den Uferpflöcken, und gemessen wird mit der Sonde. Die 104 Einzelmessungen in der Tabelle stammen deshalb ausschließlich aus Juli, August und September.","type":"text"}]}'),
(9, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"104 Einzelmessungen an acht Stellen","type":"text"}]}'),
(10, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Gemessen wurde am 8. Juli, am 12. August und am 9. September 2025, jeweils vormittags. Der Pegel Borgfeld stand an diesen Tagen bei 0,52 m, 0,41 m und 0,47 m, in den 48 Stunden davor fiel jeweils kein Niederschlag. Ohne diesen Bezug sind die Geschwindigkeiten nicht vergleichbar, deshalb steht er hier und nicht im Anhang. Eine Einzelmessung ist eine Lotrechte an einem Termin, gemessen in 0,2 und 0,8 der Wassertiefe; daraus entsteht das Tiefenmittel und mit den Teilflächen der Abfluss.","type":"text"}]}'),
(11, 'FORMULA', '{"type":"mathBlock","attrs":{"latex":"\\bar{v} = \\frac{v_{0{,}2h} + v_{0{,}8h}}{2}, \\qquad Q = \\sum_{i=1}^{n} \\bar{v}_i \\cdot b_i \\cdot h_i"}}'),
