(13, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Die Zahl der Lotrechten schwankt, weil die Strecke unterschiedlich breit ist und weil an R4 ab August eine sechste dazukam: Der Kolk hatte sich über den bisherigen Profilrand hinaus verbreitert. Deutlich ist der Zusammenhang mit dem Einbauwinkel, nicht mit der Größe des Baums. R4 steht mit 40 Grad am steilsten in der Strömung, ist dort ","type":"text"},{"text":"zweieinhalbmal so schnell wie die freie Strecke und hat 26 Zentimeter Kolk","type":"text","marks":[{"type":"highlight","attrs":{"color":"amber"}}]},{"text":". R3 und R5 liegen mit 12 und 15 Grad fast parallel am Ufer, dort tut sich mit 4 und 2 Zentimetern so gut wie nichts, obwohl beide Stämme die dicksten der Strecke sind. Nebenbefund aus dem Zimmererblick: An R2 hatten sich zwei Seilklemmen der Verankerung gelöst, der Stamm war um etwa 20 Zentimeter flussab gewandert. Das haben wir dem Verband gemeldet.","type":"text"}]}'),
(14, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Den Winkel haben wir bisher nach Gefühl gewählt und danach, was der Bagger vom Ufer aus erreichte. Dass die beiden flach liegenden Bäume fast nichts bewirken, sehen wir hier zum ersten Mal in Zahlen.","type":"text"}]},{"type":"paragraph","content":[{"text":"Gewässerwart des Unterhaltungsverbands bei der gemeinsamen Begehung am 9. September 2025","type":"text","marks":[{"type":"italic"}]}]}]}'),
(15, 'DOCUMENT', '{"type":"documentBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-160000000003","fileName":"messprotokolle-sose-2025.pdf","size":486000,"caption":"Alle Protokolle mit Nullpunktkontrollen, Pegelständen und Profilskizzen. Die verworfenen Juni-Werte stehen als eigener Anhang darin, damit nachvollziehbar bleibt, warum sie nicht in die Auswertung eingegangen sind."}}')
) as v(order_index, type, content);

-- Projekt 17: 214 Dachbalken aus Abbruchhäusern, sortiert nach DIN 4074-1
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000017'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '240 days', now() - interval '60 days'
from (values
(0, 'TABLE_OF_CONTENTS', '{"type":"tableOfContents","attrs":{"entries":[{"text":"214 Dachbalken aus Abbruchhäusern, sortiert nach DIN 4074-1","index":0,"level":1},{"text":"Aufmaß und Vorgehen","index":1,"level":2},{"text":"Sortierung nach Augenschein","index":2,"level":2},{"text":"Woran die erste Sortierung scheiterte","index":3,"level":2}]}}'),
(1, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"text":"214 Dachbalken aus Abbruchhäusern, sortiert nach DIN 4074-1","type":"text"}]}'),
(2, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Wenn in Bremen ein Altbau fällt, geht der Dachstuhl in die Hackschnitzelanlage. Dabei liegt dort Holz, das hundert Jahre trocken unter den Ziegeln gelegen hat und enger gewachsen ist als das meiste, was heute aus dem Sägewerk kommt. Vor dem Studium habe ich eine Zimmererlehre gemacht; auf der Baustelle lernt man früh, einem Balken anzusehen, was er noch trägt. Für diese Arbeit habe ich vier Abbruchobjekte begleitet und jeden ausgebauten Balken aufgemessen, gereinigt und sortiert, ","type":"text"},{"text":"214 Stück zwischen Februar und Juni","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}'),
(3, 'IMAGE', '{"type":"imageBlock","attrs":{"alt":"Gestapelte Holzbalken auf Böcken in einer Werkhalle","width":75,"fileId":"d0d00022-0000-4000-8000-170000000001","caption":"Sortierplatz in Walle. Jeder Balken bekommt mit Kreide eine Nummer, bevor er auf den Bock kommt, sonst ist nach dem dritten Stapel nicht mehr klar, welcher Balken aus welchem Sparrenfeld stammt."}}'),
(4, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Aufmaß und Vorgehen","type":"text"}]}'),
(5, 'LIST', '{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Aufmaß am ausgebauten Balken: Länge, Querschnitt, Lage im Dachstuhl, dazu jede Kerve und jedes Zapfenloch mit Tiefe","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Reinigen mit der Drahtbürste, weil Staub, Ruß und alter Anstrich genau die Äste verdecken, auf die es ankommt","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Visuelle Sortierung nach DIN 4074-1 in S10, S7 oder Ausschuss, von mir und dem Zimmerermeister des Abbruchbetriebs unabhängig voneinander","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bohrwiderstandsmessung an jedem Balken mit Verdacht auf Fäule, fast immer im Auflagerbereich über der Mauerlatte","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Holzfeuchte an drei Stellen je Balken mit dem Widerstandsmessgerät, gemessen am selben Tag wie die Sortierung","type":"text"}]}]}]}'),
(6, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Sortierung nach Augenschein","type":"text"}]}'),
(7, 'FORMULA', '{"type":"mathBlock","attrs":{"latex":"A = \\frac{\\sum d_{a}}{h}, \\quad A \\leq \\frac{1}{3} \\;\\Rightarrow\\; \\mathrm{S10}"}}'),
(8, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Die visuelle Sortierung nach DIN 4074-1 entscheidet vor allem über den Astquotienten: die Summe der Astdurchmesser an der ungünstigsten Stelle, geteilt durch die Höhe des Querschnitts. Bleibt sie unter einem Drittel, ist der Balken S10 und damit rechnerisch C24; bis zur Hälfte bleibt S7, darüber ist Schluss. Dazu kommen Risse, Baumkante, Drehwuchs und die Jahrringbreite. Alte Dachbalken schneiden dabei häufig gut ab, weil sie aus langsam gewachsenen Stämmen stammen: ","type":"text"},{"text":"im Mittel 1,8 Millimeter Jahrringbreite gegenüber 3,4 Millimetern bei frischem Fichtenholz aus dem Handel","type":"text","marks":[{"type":"bold"}]},{"text":". Was sie aus der Klasse wirft, ist selten der Wuchs, sondern das, was Handwerk und Zeit hinterlassen haben.","type":"text"}]}'),
(9, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Objekt","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Baujahr","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Balken","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"S10","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"S7","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"aussortiert","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Findorff, Doppelhaus","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"1907","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"62","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"34","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"16","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"12","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Walle, Speichergebäude","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"1924","type":"text"}]