(10, 'DOCUMENT', '{"type":"documentBlock","attrs":{"size":486000,"caption":"Das vollständige Protokoll für Objekt B in Walle: 71 Balken einzeln, mit Astquotient, Rissbild, Holzfeuchte und dem Ergebnis beider Sortierdurchgänge nebeneinander.","fileId":"d0d00022-0000-4000-8000-170000000003","fileName":"sortierprotokoll-objekt-b.pdf"}}'),
(11, 'GALLERY', '{"type":"galleryBlock","attrs":{"items":[{"alt":"Dachstuhl von innen mit Sparren und Kehlbalken vor dem Ausbau","fileId":"d0d00022-0000-4000-8000-170000000002"},{"alt":"Nahaufnahme eines Balkenendes mit rechteckigem Zapfenloch, ausgerissenen Kanten und dicht stehenden Jahrringen","fileId":"d0d00022-0000-4000-8000-170000000004"}],"caption":"Links der Dachstuhl in Hemelingen kurz vor dem Ausbau, rechts ein ausgeschlagenes Zapfenloch. Solche Löcher kosten am Ende mehr Balken als Fäule, weil die nutzbare Höhe des Querschnitts an dieser Stelle auf 14 Zentimeter zusammenschrumpft.","columns":2}}'),
(12, 'DIVIDER', '{"type":"horizontalRule"}'),
(13, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Woran die erste Sortierung scheiterte","type":"text"}]}'),
(14, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Objekt A habe ich im Februar auf dem Hof sortiert, direkt neben dem Container, weil die Halle noch belegt war. Das war der Fehler der Arbeit: ","type":"text"},{"text":"nasses, staubiges Holz zeigt seine Äste nicht","type":"text","marks":[{"type":"bold"}]},{"text":", und bei zwei Grad schreibt niemand sorgfältig auf. Von den 62 Balken aus Findorff musste ich nach dem Bürsten und zwei Tagen im Trockenen 23 neu einstufen, 9 nach oben und 14 nach unten. Ab Objekt B lief alles in der Halle: Balken hereinfahren, reinigen, stehen lassen, dann sortieren. Danach stimmten die beiden unabhängigen Sortierungen bei 58 von 71 Balken in der Klasse überein, vorher waren es 39 von 62 gewesen. Die Tabelle oben zeigt für alle vier Objekte den Stand nach der zweiten Durchsicht. Von den 39 aussortierten Balken hatten 11 Fäule im Auflagerbereich, bei 19 lagen Äste oder Risse über der Grenze für S7, und 9 blieben nach dem Abbund der alten Kerven unter dem Querschnitt, den eine neue Verwendung braucht. Die Protokolle aller vier Objekte liegen beim ","type":"text"},{"text":"Studiengang Bauingenieurwesen","type":"text","marks":[{"type":"link","attrs":{"href":"https://www.hs-bremen.de","rel":"noopener noreferrer","target":"_blank"}}]},{"text":". Wer damit weiterrechnet, misst die Holzfeuchte am Einbautag noch einmal nach: die Werte im Protokoll sind Lagerwerte aus einer ungeheizten Halle und keine Einbaufeuchte.","type":"text"}]}'),
(15, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Was hundert Jahre unter dem Ziegeldach gelegen hat, ist trockener als alles, was du heute kaufst. Nachweisen musst du es trotzdem selber, und das ist die Arbeit.","type":"text"}]},{"type":"paragraph","content":[{"text":"Zimmerermeister des Abbruchbetriebs in Walle, beim zweiten Ortstermin","type":"text","marks":[{"type":"italic"}]}]}]}')
) as v(order_index, type, content);

-- Projekt 18: Neun Lamellendächer in Bremen: vier stehen noch
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000018'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '110 days', now() - interval '14 days'
from (values
(0, 'TABLE_OF_CONTENTS', '{"type":"tableOfContents","attrs":{"entries":[{"text":"Vom Bauaktenkeller zurück an die Halle","index":0,"level":1},{"text":"Was im Staatsarchiv lag","index":1,"level":2},{"text":"Aufmaß in Walle: 38 Zentimeter flacher als gezeichnet","index":2,"level":2},{"text":"Was von den vier Hallen übrig ist","index":3,"level":2}]}}'),
(1, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"text":"Vom Bauaktenkeller zurück an die Halle","type":"text"}]}'),
(2, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Bevor ich angefangen habe zu studieren, habe ich drei Jahre lang Dachstühle abgebunden. Aus dieser Zeit ist mir ein Bauteil im Kopf geblieben, das aussieht wie ein Korbgeflecht und aus lauter kurzen Brettern besteht: das Lamellendach nach Friedrich Zollinger, patentiert 1921 und gebaut, als Bauholz knapp und Geld noch knapper war. Wie viele davon in Bremen wirklich gebaut wurden, stand nirgends. Also haben wir im Staatsarchiv angefangen und sind von dort aus zu den Hallen gefahren, die es noch gibt. Der zweite Teil war der mühsamere: zwei der neun Adressen ließen sich erst über alte Flurstücksnummern wiederfinden.","type":"text"}]}'),
(3, 'IMAGE', '{"type":"imageBlock","attrs":{"alt":"Blick von unten in ein rautenförmiges Dachtragwerk aus kurzen Holzbrettern","width":100,"fileId":"d0d00022-0000-4000-8000-180000000000","caption":"Die aufgemessene Halle in Walle, heute eine Werkstatt: 19,6 Meter Spannweite ohne einen einzigen Binder"}}'),
(4, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Was im Staatsarchiv lag","type":"text"}]}'),
(5, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Im ","type":"text"},{"text":"Staatsarchiv Bremen","type":"text","marks":[{"type":"link","attrs":{"href":"https://www.staatsarchiv.bremen.de/","rel":"noopener noreferrer","target":"_blank"}}]},{"text":" haben wir 34 Bauakten aus den Jahren 1920 bis 1932 durchgesehen, gefunden über die Stichworte Lamellendach, Zollinger und Bohlendach. Neun Akten enthalten ein Lamellendach, als Konstruktionszeichnung, als Statik oder als beides. Zwei weitere nennen die Bauweise nur im Schriftverkehr; ohne Zeichnung haben wir sie nicht mitgezählt. Auffällig ist, wie kurz die Statiken sind: zwei Seiten, ein Bogenschub, ein Nachweis für den Ringanker. Der Knoten selbst wird in keiner einzigen Akte gerechnet.","type":"text"}]}'),
(6, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Zustand","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Anzahl","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Anmerkung","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Steht, von innen zugänglich","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"3","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Zwei Hallen in Walle, eine in Hemelingen","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Steht, nur von außen zu sehen","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"1","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Privatgrundstück, keine Begehung möglich","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Abgebrochen, Zeichnung erhalten","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"4","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Drei davon zwischen 1962 und 1979","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Beantragt, nie gebaut","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"1","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Bauantrag von 1924 mit dem Vermerk zurückgezogen","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Summe","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"9","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"aus 34 durchgesehenen Bauakten","type":"text"}]}]}]}]}'),
(7, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Das Dach wird ohne Lehrgerüst errichtet. Die Bretter sind von zwei Mann zu heben und werden auf dem Ringanker zu Rauten zusammengesetzt, so dass Rüstholz und Kran entbehrlich sind.","type":"text"}]},{"type":"paragraph","content":[{"text":"Erläuterungsbericht zum Bauantrag einer Fuhrparkhalle in Walle, 1923, Staatsarchiv Bremen","type":"text","marks":[{"type":"italic"}]}]}]}'),
(8, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Aufmaß in Walle: 38 Zentimeter flacher als gezeichnet","type":"text"}]}'),
(9, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"An einer der drei begehbaren Hallen, heute eine Werkstatt in Walle, haben wir 40 Lamellen aufgemessen. Die Zeichnung von 1923 gibt 1,30 Meter Lamellenlänge an, gemessen haben wir im Mittel 1,34 Meter bei einer Streuung von elf Millimetern. Der Bogen ist ","type":"text"},{"text":"38 Zentimeter flacher als gezeichnet","type":"text","marks":[{"type":"bold"}]},{"text":", also 4,32 statt 4,70 Meter Stich bei 19,6 Metern Spannweite. Ob am Bau gespart wurde oder ob sich das Dach in hundert Jahren gesetzt hat, konnten wir nicht klären; der Aktenbestand gibt dazu nichts her. Für das Tragwerk macht der flachere Bogen einen Unterschied: gerechnet mit 3,6 Kilonewton je Meter Bogenstreifen aus Eigengewicht und Schnee steigt der Horizontalschub am Fußpunkt um knapp neun Prozent, und er landet in einem Ringanker, den die Statik von 1923 mit genau einer Zeile nachweist.","type":"text"}]}'),
(10, 'FORMULA', '{"type":"mathBlock","attrs":{"latex":"H = \\frac{q\\,l^{2}}{8\\,f}: \\qquad \\frac{3{,}6 \\cdot 19{,}6^{2}}{8 \\cdot 4{,}32} = 40{,}0\\ \\mathrm{kN} \\quad \\mathrm{statt} \\quad \\frac{3{,}6 \\cdot 19{,}6^{2}}{8 \\cdot 4{,}70} = 36{,}8\\ \\mathrm{kN}"}}'),
(11, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Was von den vier Hallen übrig ist","type":"text"}]}'),
(12, 'LIST', '{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Walle, Fuhrparkhalle von 1923, heute eine Tischlerwerkstatt: 19,6 Meter Spannweite, die Dachhaut 1978 erneuert. Am südlichen Auflager sind zwei Lamellen ausgewechselt, der Rest ist trocken und ohne sichtbare Verformung.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Walle, Lagerhalle von 1926, heute Lager einer Spedition: 14,2 Meter Spannweite. Über der Toreinfahrt sind acht Lamellen von Feuchte gezeichnet, die Bolzen daneben rosten. Der Eigentümer wusste nicht, was für ein Dach über seinem Lager liegt.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Hemelingen, Turnhalle von 1928, weiter als Sporthalle genutzt: 17,4 Meter Spannweite. 1994 kam eine abgehängte Decke darunter, seither ist das Tragwerk nur noch vom Dachraum aus zu sehen.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Oslebshausen, Halle von 1925: nur von der Straße aus zu sehen, das Grundstück ist privat und eine Begehung kam nicht zustande. Ob unter dem Trapezblech von 2004 noch das Lamellendach liegt, konnten wir nicht klären.","type":"text"}]}]}]}'),
(13, 'IMAGE', '{"type":"imageBlock","attrs":{"alt":"Feuchtespuren und ausgewechselte Bretter an der Auflagerreihe eines Lamellendachs","width":75,"fileId":"d0d00022-0000-4000-8000-180000000001","caption":"Lagerhalle in Walle über der Toreinfahrt: acht gezeichnete Lamellen, darunter ein Bolzen, der seit Jahrzehnten rostet"}}'),
(14, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Am Ende steht ein Katalog: neun Dächer, jedes mit Aktensignatur, Adresse, Spannweite, Bauzustand und dem, was offen blieb. Zwei Lücken bleiben groß. Die vier abgebrochenen Dächer sind nur über die Zeichnung belegt; ob sie so gebaut wurden, wie sie beantragt waren, sagt keine Akte. Und für die Halle in Oslebshausen fehlt die Erlaubnis hineinzugehen, ohne die der Zustand eine Vermutung bleibt. Den Katalog haben wir dem Landesamt für Denkmalpflege übergeben, das bisher keines der vier stehenden Dächer geführt hat.","type":"text"}]}'),
(15, 'DOCUMENT', '{"type":"documentBlock","attrs":{"size":1840000,"caption":"Der Katalog der neun Dächer: Aktensignatur, Adresse, Spannweite, Aufmaßblatt und Zustandsnotiz je Dach","fileId":"d0d00022-0000-4000-8000-180000000002","fileName":"katalog-lamellendaecher.pdf"}}')
) as v(order_index, type, content);

-- Projekt 19: Galerie in der Schlosserei: 9 von 12 Ankern rissen aus dem Ziegel
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000019'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '330 days', now() - interval '270 days'
from (values
(0, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"type":"text","text":"Eine Galerie, die die alte Wand nicht anfasst"}]}'),
(1, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Die Schlosserei in Hemelingen steht seit 2019 leer: eine Halle von 14 auf 9 Metern, Ziegel, 5,20 Meter bis zur Unterkante der Binder. Im Modul Entwerfen und Konstruieren sollte daraus ein Arbeitsraum für zwei Werkgruppen werden, ohne die Halle zu teilen. Also eine zweite Ebene auf halber Höhe. Im Entwurf hing sie an den Wänden, gebaut ist sie "},{"type":"text","text":"freistehend","marks":[{"type":"bold"}]},{"type":"text","text":", und dazwischen liegen zwölf Auszugsversuche. Gebaut haben wir im Juli 2025, in neun Tagen, zu viert. Ich komme von der Zimmerei, das ist meine erste eigene Statik, die auch jemand betreten darf."}]}'),
(2, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Warum die Wand nicht trägt"}]}'),
(3, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Der Bestand ist ein 24 Zentimeter starkes Vollziegelmauerwerk in Kalkmörtel, gebaut um 1928. An der Ostwand, unter dem alten Oberlicht, sind die Fugen auf halber Höhe ausgewaschen; dort lief jahrzehntelang Wasser an der Wand herunter. Der erste Entwurf hängte die Galerieträger in zwölf Injektionsanker M12 mit Siebhülse, Setztiefe 110 Millimeter. Aus dem Nachweis kam ein Bedarf von 3,9 kN je Anker, wir haben 4,0 kN als Messlatte genommen. Bevor irgendetwas gebaut wurde, haben wir alle zwölf Anker gesetzt und mit einem geliehenen hydraulischen Zugprüfgerät bis zum Versagen gezogen."}]}'),
(4, 'IMAGE', '{"type":"imageBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-190000000002","alt":"Hydraulisches Zugprüfgerät auf einem Dreibein vor einer alten Ziegelwand, daran ein gesetzter Anker mit Gewindestange","caption":"Versuch 7 an der Ostwand: Der Anker hielt 2,4 kN, dann kam ein Kegel aus Mörtel und Ziegelscherben mit heraus.","width":75}}'),
(5, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Wandbereich"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Versuche"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Versagen unter 4,0 kN"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Höchstlast im Mittel (kN)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Nordwand, Fugen voll"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"4"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"1"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"6,8"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ostwand unter dem Oberlicht"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"5"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"5"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"2,9"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Pfeiler neben dem Hallentor"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"3"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"3"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"3,4"}]}]}]},{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Summe"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"12"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"9"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"4,3 im Mittel"}]}]}]}]}'),
(6, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Neun der zwölf Anker rissen unter 4,0 kN aus, an der Ostwand alle fünf. Versagt hat dabei "},{"type":"text","text":"nie der Anker, sondern der Ziegel","marks":[{"type":"bold"}]},{"type":"text","text":": Es kam jedes Mal ein Kegel aus Mörtel und Scherben mit heraus. Damit war der Entwurf erledigt, drei Wochen vor dem ersten Bautag. Eine Vernadelung der Ostwand hätte länger gedauert als die ganze Bauzeit und wäre in einem Bestand, der später vielleicht abgerissen wird, auch schwer zu begründen. Also haben wir die Galerie vom Bestand gelöst."}]}'),
(7, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Sechs Stützen statt zwölf Anker"}]}'),
(8, 'LIST', '{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sechs Stützen 140/140 aus Brettschichtholz, zwei Reihen zu dritt: 6,00 Meter Achsabstand in der Länge, 3,50 Meter in der Tiefe. Das ergibt 42 Quadratmeter Galeriefläche in zwei Feldern."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Längsträger 140/320 aus GL24h, je 6,00 Meter, über der Mittelstütze gestoßen statt durchlaufend. Ein Stück von zwölf Metern kommt nicht durch das Hallentor."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deckenbalken 80/200 im Abstand von 62,5 Zentimetern, darauf 27 Millimeter Dreischichtplatte, verschraubt im Raster von 15 Zentimetern."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kopfbänder in beiden Richtungen, angeschlossen mit je vier Vollgewindeschrauben 8 x 200. Ich wollte sie zapfen, wie ich es in der Lehre gelernt habe; im Nachweis nach Eurocode 5 trägt der Zapfen weniger als die Hälfte der vier Schrauben."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fußpunkte auf Stahlplatten 300 auf 300 Millimeter, weil die Bodenplatte nur 8 Zentimeter dick ist und auf Schlacke liegt."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Zur Bestandswand bleiben mindestens 2 Zentimeter Fuge, keine einzige Bohrung im Mauerwerk. Der Boden fällt über die zwölf Meter um 4,2 Zentimeter zum alten Ablauf hin, deshalb ist jeder Stützenfuß einzeln eingemessen und untergossen. Das hat einen ganzen Bautag gekostet, den wir nicht eingeplant hatten."}]}]}]}'),
(9, 'IMAGE', '{"type":"imageBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-190000000001","alt":"Vier Personen richten einen langen Holzträger zwischen zwei Stützen aus, im Hintergrund eine Ziegelwand mit Oberlicht","caption":"Zweiter Bautag: Die 6-Meter-Träger gehen zu viert von Hand hoch. Das Einmessen der Fußpunkte hat länger gedauert als das Aufrichten.","width":100}}'),
(10, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Die Probebelastung"}]}'),
(11, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Am 24. Juli haben wir das südliche Feld belastet, 6,00 auf 3,50 Meter: 21 Fässer mit je 200 Litern, oben mit dem Schlauch gefüllt, weil 4,2 Tonnen niemand die Leiter hochträgt. Über 21 Quadratmetern sind das knapp 2,0 kN je Quadratmeter, genau die Nutzlast, mit der gerechnet ist. Auf einen Längsträger entfällt die halbe Deckenbreite, also 1,75 Meter Lasteinzug und damit 3,5 kN je Meter. Gerechnet haben wir mit dem Mittelwert des Elastizitätsmoduls für GL24h, 11.500 N/mm², und dem Trägheitsmoment des reinen Trägers; zulässig waren 20 Millimeter, also L durch 300."}]}'),
(12, 'FORMULA', '{"type":"mathBlock","attrs":{"latex":"w = \\frac{5\\,q\\,L^{4}}{384\\,E\\,I} = \\frac{5 \\cdot 3{,}5\\,\\mathrm{kN/m} \\cdot (6{,}00\\,\\mathrm{m})^{4}}{384 \\cdot 11500\\,\\mathrm{N/mm^{2}} \\cdot 3{,}82 \\cdot 10^{8}\\,\\mathrm{mm^{4}}} = 13{,}4\\,\\mathrm{mm}"}}'),
(13, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Drei Messuhren hingen unter dem Träger, eine in Feldmitte und je eine über den Stützen. In Feldmitte standen nach fünf Minuten 11,6 Millimeter, also 13 Prozent unter der Rechnung. Nach einer Stunde waren es 12,0 Millimeter. Der Unterschied kommt nicht daher, dass der Träger besser wäre als gerechnet: Die verschraubte Dreischichtplatte trägt als Scheibe mit, wir haben sie im Nachweis aber gar nicht angesetzt. Nach dem Entlasten blieben 0,9 Millimeter stehen, am nächsten Morgen noch 0,3. Das ist das Setzen der Schraubenverbindungen und war der Teil, über den wir am längsten diskutiert haben."}]}'),
(14, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Eine Messung unter der Rechnung ist kein Grund zur Freude, sondern ein Hinweis darauf, dass Ihr Modell nicht das ist, was Sie gebaut haben. Rechnen Sie es mit der Scheibe noch einmal."}]},{"type":"paragraph","content":[{"type":"text","text":"Rückmeldung aus der Zwischenkritik im Modul Entwerfen und Konstruieren, 29. Juli 2025","marks":[{"type":"italic"}]}]}]}'),
(15, 'DOCUMENT', '{"type":"documentBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-190000000003","fileName":"messprotokoll-probebelastung.pdf","size":214000,"caption":"Messprotokoll der Probebelastung: alle Ablesungen der drei Messuhren, dazu Holzfeuchte (13,2 Prozent), Hallentemperatur und die Reihenfolge, in der die 21 Fässer gefüllt wurden."}}')
) as v(order_index, type, content);

-- Projekt 20: Freilandwaage verliert 16 Prozent gegen den Grubensammler
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000020'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '175 days', now() - interval '105 days'
from (values
(0, 'TABLE_OF_CONTENTS', '{"type":"tableOfContents","attrs":{"entries":[{"text":"Zwei Aufstellungen für denselben Regen","index":0,"level":1},{"text":"Der Aufbau auf dem Messfeld","index":1,"level":2},{"text":"Woran die erste Fassung gescheitert ist","index":2,"level":2},{"text":"62 Ereignisse, nach Art getrennt","index":3,"level":2}]}}'),
(1, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"text":"Zwei Aufstellungen für denselben Regen","type":"text"}]}'),
(2, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Eine Niederschlagswaage im Freiland misst weniger, als vom Himmel kommt, und das aus zwei Gründen gleichzeitig. Der Wind wird über dem Trichterrand beschleunigt und trägt leichte Tropfen und Flocken daran vorbei; was hineinfällt, bleibt zum Teil als Film an Trichter und Ringheizung hängen und verdunstet, bevor es die Wägezelle erreicht. Wie groß beide Anteile am Neustadtswall sind, sollte eine Vergleichsmessung zeigen: vom 12. November bis zum 28. Januar, also ","type":"text"},{"text":"77 Tage lang","type":"text","marks":[{"type":"bold"}]},{"text":", stand die beheizte Waage in der üblichen Freilandaufstellung 30 Meter neben einem Grubensammler, dessen Trichterrand bündig mit dem Boden liegt und der deshalb fast keinen Windfehler hat.","type":"text"}]}'),
(3, 'IMAGE', '{"type":"imageBlock","attrs":{"alt":"Zwei Niederschlagssammler auf einer Freifläche bei Regen, dahinter ein Zaun","width":100,"fileId":"d0d00022-0000-4000-8000-200000000000","caption":"Links die Freilandaufstellung, rechts der Grubensammler mit dem Rost auf Bodenniveau. Näher als 30 Meter dürfen die beiden nicht stehen, sonst nimmt die eine Aufstellung der anderen den Wind."}}'),
(4, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Der Aufbau auf dem Messfeld","type":"text"}]}'),
(5, 'LIST', '{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Zwei Sammler mit derselben Auffangfläche von 200 Quadratzentimetern und derselben Wägezelle; verschieden ist allein die Aufstellung, einmal frei im Wind, einmal in der Grube mit einem Rost auf Bodenniveau","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ein Ultraschall-Anemometer in 10 Metern Höhe zwischen beiden Aufstellungen, damit jedem Ereignis ein Windmittel zugeordnet werden kann","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ein PT1000 zwei Millimeter unter dem Trichterrand, der mitschreibt, wann die 48-W-Ringheizung anliegt: ohne diesen Wert lässt sich der Benetzungsverlust später nicht von der Verdunstung am geheizten Rand trennen","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Eine Laborreihe zum Benetzungsverlust: 40-mal 50 Milliliter aus einer Bürette in den trockenen Trichter, jedes Mal gewogen, was unten ankommt","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Messwerte im Sekundentakt auf eine SD-Karte, weil die Funkstrecke zum Labor im Dezember zweimal tagelang tot war","type":"text"}]}]}]}'),
(6, 'GALLERY', '{"type":"galleryBlock","attrs":{"items":[{"alt":"Lötstelle an einem dünnen Fühlerkabel unter einer Lupenleuchte","fileId":"d0d00022-0000-4000-8000-200000000001"},{"alt":"Geöffneter Schaltkasten mit Platine, Klemmen und beschrifteten Adern","fileId":"d0d00022-0000-4000-8000-200000000002"}],"caption":"Links der PT1000 vor dem Einkleben, rechts der Schaltkasten der Freilandwaage. Die Lötstelle sitzt bewusst außerhalb des geheizten Rings, sonst misst der Fühler seine eigene Zuleitung mit.","columns":2}}'),
(7, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Woran die erste Fassung gescheitert ist","type":"text"}]}'),
(8, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Die erste Fassung des Aufbaus hatte den Grubensammler acht Meter neben die Hecke am Feldrand gesetzt, weil dort schon ein Kabelschacht lag. Bei Westwind stand er damit im Windschatten und fing bei denselben Ereignissen bis zu 9 Prozent mehr auf als nach dem Umsetzen: statt einer Referenz hatten wir eine zweite, nur anders verfälschte Messung. Die drei Wochen bis zum Umsetzen zählen deshalb nicht mit, die 77 Tage der Auswertung beginnen erst danach. Auch die Laborreihe war zuerst falsch angelegt, weil der Trichter zwischen zwei Dosierungen nur ausgeschüttelt statt getrocknet wurde; so kam der Benetzungsverlust auf 0,02 Millimeter. Mit trockenem Trichter und 40 Wiederholungen sind es ","type":"text"},{"text":"0,06 Millimeter je Ereignis","type":"text","marks":[{"type":"bold"}]},{"text":", bei 62 Ereignissen also 3,7 Millimeter. Der Windbeiwert ","type":"text"},{"text":"a","type":"text","marks":[{"type":"code"}]},{"text":" ist mit 0,021 Sekunden je Meter allein aus den 46 Regenereignissen angepasst. Für Schnee passt kein einziger Beiwert: dort liegt der Fehlbetrag um ein Vielfaches über dem, was diese Anpassung hergibt.","type":"text"}]}'),
(9, 'VIDEO', '{"type":"videoBlock","attrs":{"width":75,"provider":"youtube","videoId":"aqz-KE-bpKQ","caption":"Mitschnitt eines Vortrags über die Feldvergleiche der WMO an Niederschlagsmessern. Ab Minute 12 zeigen Strömungsaufnahmen aus dem Windkanal, wie sich über einem unverkleideten Trichterrand ein Wirbel bildet, der leichte Flocken über die Öffnung hinwegträgt. Genau dieser Effekt steckt in unseren Schneezeilen."}}'),
(10, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"62 Ereignisse, nach Art getrennt","type":"text"}]}'),
(11, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Ereignisart","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Anzahl","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Freilandwaage (mm)","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Grubensammler (mm)","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"davon verloren","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Regen über 2 °C","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"34","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2,25","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2,40","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"0","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Regen unter 2 °C","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"12","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"1,55","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"1,80","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"0","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Nassschnee","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"9","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"1,35","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2,30","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"3","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Schnee unter 0 °C","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"7","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"1,25","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2,00","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"0","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Summe","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"62","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"116,00","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"137,90","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"3","type":"text"}]}]}]}]}'),
(12, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Die beiden Millimeterspalten sind Mittelwerte je Ereignis, nur die letzte Zeile summiert über alle 62 Ereignisse. Die drei bei Nassschnee verlorenen Ereignisse zählen in der Anzahl mit, und ihre Werte stecken auch in den Mitteln; deshalb liegt das Nassschnee-Mittel der Freilandwaage so tief. Über den ganzen Zeitraum fehlen ihr 21,90 Millimeter oder 16 Prozent, davon 3,7 Millimeter aus der Benetzung des Trichters und 18,2 Millimeter aus dem Wind. Wie groß der Fehlbetrag ausfällt, hängt fast nur an der Niederschlagsart: bei Regen über 2 °C sind es gut 6 Prozent, bei Schnee unter 0 °C 37,5 Prozent. Bei Nassschnee kommt ein zweiter Effekt dazu. Dreimal im Januar reichten die 48 Watt bei 8 Metern pro Sekunde nicht, der Trichterrand wuchs zu, und der Niederschlag erreichte die Waage erst beim Auftauen am nächsten Vormittag. Für die Ereignisauswertung sind diese drei Fälle verloren.","type":"text"}]}'),
(13, 'VIDEO', '{"type":"videoBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-200000000004","width":75,"caption":"Zeitraffer vom 17. Januar, ein Bild alle zehn Sekunden: Der Nassschnee legt sich trotz laufender Ringheizung auf den Trichterrand der Freilandwaage und bleibt liegen."}}'),
(14, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Ein Sammler, der 16 Prozent zu wenig auffängt, ist deswegen nicht kaputt. Er misst, was an seinem Standort in ihn hineinfällt. Alles Weitere ist eine Frage der Aufstellung, und die gehört in den Messbericht.","type":"text"}]},{"type":"paragraph","content":[{"text":"Anmerkung aus dem Zwischenkolloquium im Modul Messtechnik am 5. Februar","type":"text","marks":[{"type":"italic"}]}]}]}'),
(15, 'DOCUMENT', '{"type":"documentBlock","attrs":{"size":246800,"caption":"Alle 62 Ereignisse mit Beginn, Dauer, Windmittel, beiden Auffangmengen und der Differenz. Wer damit weiterrechnet, sollte die Laborreihe im Anhang beachten: ohne den Benetzungswert lässt sich der Windanteil nicht abtrennen.","fileId":"d0d00022-0000-4000-8000-200000000003","fileName":"auswertungsprotokoll-winter.pdf"}}')
) as v(order_index, type, content);

-- Projekt 21: 37 Ausfälle in 28 Tagen: Feinstaubknoten bei hoher Luftfeuchte
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000021'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '45 days', now() - interval '3 days'
from (values
(0, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"type":"text","text":"Zwischenstand nach vier Wochen am Mast"}]}'),
(1, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Das hier ist ein Arbeitsstand und kein fertiger Bericht. Sechs Knoten mit je einem optischen Feinstaubsensor "},{"type":"text","text":"SPS30","marks":[{"type":"code"}]},{"type":"text","text":" und einem Feuchtefühler hängen seit dem 2. Juni an drei Masten an der Neuenlander Straße, gut zwei Kilometer von der nächsten Referenzstation entfernt. In den ersten 28 Tagen habe ich "},{"type":"text","text":"37 Ausfälle","marks":[{"type":"bold"}]},{"type":"text","text":" protokolliert. Ich schreibe sie auf, solange ich bei jedem einzelnen noch weiß, woran er lag."}]}'),
(2, 'IMAGE', '{"type":"imageBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-210000000001","alt":"Geöffnetes Kunststoffgehäuse auf einer Werkbank, daneben Lötkolben, Litze und Prüfspitzen","caption":"Die zweite Gehäusefassung am Lötplatz. Der Lufteinlass sitzt jetzt oben, das Prallblech davor fehlt auf dem Bild noch.","width":75}}'),
(3, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Die 37 Ausfälle nach Ursache"}]}'),
(4, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ursache"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ausfälle"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Notiz aus dem Protokoll"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Feuchte im Sensoreingang"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"19"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"alle an Regen- oder Nebeltagen, 14 davon an den beiden Knoten ohne Prallblech"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Spannungseinbruch am Akku"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"8"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"drei bedeckte Tage hintereinander reichen dem 5-Watt-Panel nicht"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Funkpaket verloren"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"6"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"fünf davon an Knoten 5, der hinter einem Blechvordach sitzt"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Dateisystem der SD-Karte"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"3"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Abbruch mitten im Schreiben, die Karte lief erst nach dem Formatieren wieder"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"ohne erkennbare Ursache"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"1"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Knoten 2, Nacht auf den 19. Juni, Neustart um 03:12 Uhr ohne Eintrag davor"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Summe","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"37","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"sechs Knoten, 28 Tage, 2. bis 29. Juni"}]}]}]}]}'),
(5, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Die 19 Feuchteausfälle sind kein Zufall. Der Sensor misst Streulicht, und oberhalb von etwa 85 Prozent relativer Feuchte lagern die Partikel Wasser an und werden optisch größer. An zwei Regentagen stieg der Rohwert auf das Zweieinhalbfache der Referenz, obwohl die Luft an diesen Tagen sauberer war als im Mittel. Die übliche Korrektur teilt den Rohwert durch 1 + k · RH / (100 - RH). Mit dem Literaturwert k = 0,42 lag ich noch 31 Prozent über der Referenzstation, mit einem eigenen k von 0,54 sind es neun Prozent. Zwei Regentage sind zu wenig, um daraus einen Kalibrierwert zu machen, das ist mir bewusst. Der erste Gehäuseentwurf hat die Sache zusätzlich verschlimmert: Einlass nach unten, ein 3 mm breiter Schlitz, und nach dem ersten Schauer stand Wasser auf der Optik."}]}'),
(6, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Was bis zur Abgabe noch fehlt"}]}'),
(7, 'LIST', '{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Die Einlassheizung regeln, statt sie mit festen 1,2 Watt durchlaufen zu lassen. Geregelt wird auf die Feuchte im Einlass und nicht auf die Heizleistung: unter 60 Prozent halten, ohne den Staub am Rohr festzubacken."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mindestens 14 Regentage gegen die Referenzstation stellen, bevor ich ein eigenes k aufschreibe."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Knoten 5 umhängen. Fünf der sechs verlorenen Pakete gehen auf ihn, und jede Wiederholsendung kostet wiederum den Akku."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Energiebilanz nachrechnen: entweder ein 10-Watt-Panel oder nachts von einer Minute auf fünf Minuten Abtastung."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Das Kalibrierprotokoll aus meinem Notizbuch in eine Tabelle bringen, die auch jemand anderes lesen kann."}]}]}]}'),
(8, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Solange der Einlass ungeregelt ist, messen Sie das Wetter und nicht den Staub. Fangen Sie mit der Heizung an, dann ist die Kalibrierung danach eine halbe Sache weniger."}]},{"type":"paragraph","content":[{"type":"text","text":"Anmerkung aus der Zwischenbesprechung im Modul Eingebettete Systeme am 9. Juli","marks":[{"type":"italic"}]}]}]}')
) as v(order_index, type, content);

-- Projekt 22: Energiezähler an einer Werkstattfräse im Vergleich
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000022'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '500 days', now() - interval '420 days'
from (values
(0, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"text":"Zwei Zähler, eine Fräse, fünf Wochen","type":"text"}]}'),
(1, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Eine Werkstatt weiß, was sie im Monat verbraucht, aber nicht, was ein einzelner Auftrag an Strom kostet. Wer den Verbrauch der Maschine zuordnen will, muss an der Maschine messen, und zwar auch dann, wenn sie nur eingeschaltet dasteht. Für dieses Semesterprojekt habe ich in der Metallwerkstatt am Neustadtswall zwei Zähler nebeneinander an die Fräse gehängt, einen geeichten und einen selbst gebauten, und fünf Wochen lang mitgeschrieben. Dass beide dasselbe zählen, hat sich nur bei laufender Spindel bestätigt.","type":"text"}]}'),
(2, 'GALLERY', '{"type":"galleryBlock","attrs":{"items":[{"alt":"Geöffneter Unterverteiler mit Hutschiene, links der geeichte Zähler, rechts der graue Kasten des Loggers","fileId":"d0d00022-0000-4000-8000-220000000001"},{"alt":"Drei aufklappbare Stromwandler um die Adern eines Abgangs, die Messleitungen laufen nach unten weg","fileId":"d0d00022-0000-4000-8000-220000000002"}],"caption":"Links der Unterverteiler nach dem Umbau, rechts der Abgang zur Fräse. Der Spannungsabgriff sitzt an der abgesicherten Klemme oben rechts im Bild.","columns":2}}'),
(3, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Die Messkette","type":"text"}]}'),
(4, 'LIST', '{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Geeichter Wirkenergiezähler nach MID, Klasse B, direktmessend auf der Hutschiene im Unterverteiler, Impulsausgang mit 1000 Impulsen je Kilowattstunde","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Drei aufklappbare Stromwandler der Klasse 1 mit 50 Ampere Nennstrom, an den Abgängen der Fräse aufgesetzt","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Spannungsabgriff über eine abgesicherte Klemme, Teiler auf 3,3 Volt, alle drei Außenleiter gegen den Neutralleiter","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Logger mit 3,2 Kilohertz Abtastrate je Kanal, Wirkleistung aus den Momentanwerten, gemittelt über 200 Millisekunden","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Speicherung jede Sekunde auf SD-Karte, die Uhr wird stündlich gegen einen Zeitserver im Hochschulnetz nachgezogen","type":"text"}]}]}]}'),
(5, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Die erste Fassung hat zweimal danebengelegen. Zuerst beim Ansatz: sie rechnete die Wirkleistung aus Effektivwert mal Effektivwert mal dem Leistungsfaktor vom Typenschild, also 0,85. Der Frequenzumrichter zieht aber keinen sinusförmigen Strom, und über einen ganzen Lauf kamen so bis zu 19 Prozent zu viel heraus. Seitdem läuft die Rechnung über die Momentanwerte. Der zweite Fehler saß in der Montage: ein Wandler hing verkehrt herum an der Ader, die Leistung dieser Phase zählte negativ, und das fiel erst nach zwei Wochen auf, ","type":"text"},{"text":"weil die Summe über alle drei Phasen trotzdem plausibel aussah","type":"text","marks":[{"type":"bold"}]},{"text":". Beides ist in der Vorserie passiert, die fünf Wochen der Messreihe liefen danach.","type":"text"}]}'),
(6, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Von den Momentanwerten zur Kilowattstunde","type":"text"}]}'),
(7, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Aus Spannung und Strom wird die Wirkleistung, aus der Wirkleistung über die Zeit die Energie. Einmal haben wir die Kette gegen etwas Drittes gehalten: ein Heizlüfter mit 2000 Watt an einer Phase, eine Stunde lang, ohne Umrichter und ohne Oberschwingungen. Der geeichte Zähler zählte 1,98 Kilowattstunden, der Logger 1,96. Die Differenz von 1 Prozent passt zu dem, was die Rechnung darunter zulässt, und in dieser Rechnung steht der größte Beitrag ","type":"text"},{"text":"nicht bei der Abtastung, sondern beim Phasenfehler der Stromwandler","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}'),
(8, 'FORMULA', '{"type":"mathBlock","attrs":{"latex":"P = \\frac{1}{T}\\int_{0}^{T} \\sum_{k=1}^{3} u_{k}(t)\\, i_{k}(t)\\; \\mathrm{d}t, \\quad T = 200\\,\\mathrm{ms}, \\quad f_{s} = 3{,}2\\,\\mathrm{kHz}"}}'),
(9, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Beitrag zur Wirkenergie","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"u in Prozent","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Woher die Zahl kommt","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Amplitudenfehler der Stromwandler","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"0,8","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Klasse 1, spezifiziert erst ab 10 Prozent des Nennstroms","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Phasenfehler der Stromwandler","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"0,9","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"0,5 Grad laut Datenblatt, bei einem Leistungsfaktor von 0,7","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Spannungsteiler und Referenz","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"0,4","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Widerstände mit 0,1 Prozent, Referenzspannung über die Gehäusetemperatur nachgemessen","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Nicht erfasste Oberschwingungen","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"0,5","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Anteil oberhalb 1,6 Kilohertz, aus einer Vergleichsmessung mit dem Laborgerät geschätzt","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Zeitbasis und Mittelung","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"0,2","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Quarz mit 20 ppm, dazu der Restfehler der Mittelung über 200 Millisekunden","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"kombiniert","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"1,4","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"quadratisch summiert, gültig für Läufe mit laufender Spindel","type":"text"}]}]}]}]}'),
(10, 'FORMULA', '{"type":"mathBlock","attrs":{"latex":"\\frac{u(E)}{E} = \\sqrt{0{,}8^{2} + 0{,}9^{2} + 0{,}4^{2} + 0{,}5^{2} + 0{,}2^{2}}\\;\\% = 1{,}4\\,\\%, \\quad U = 2\\,u(E) \\;\\widehat{=}\\; 2{,}8\\,\\%"}}'),
(11, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Was in den 34 Läufen passiert ist","type":"text"}]}'),
(12, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Woche","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Läufe","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Logger über 5 Prozent daneben","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"ausgewertet","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"4. bis 8. November","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"6","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"1","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"6","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"11. bis 15. November","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"8","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"3","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"8","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"18. bis 22. November","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"7","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"6","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"25. bis 29. November","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"7","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"7","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2. bis 6. Dezember","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"6","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"1","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"5","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Summe","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"34","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"9","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"32","type":"text"}]}]}]}]}'),
(13, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Als Lauf zählt jedes NC-Programm vom Start bis zum Programmende, ausgewertet heißt: beide Zähler lückenlos, Leerlauf getrennt gebucht, Energie je Auftrag gerechnet. Die neun Ausreißer haben keinen Lauf gekostet, weil der geeichte Zähler weiterlief; sie hatten alle einen hohen Leerlaufanteil, und dort fließen je Phase nur 1,1 Ampere, also gut 2 Prozent des Wandlernennstroms. In diesem Bereich ist der Phasenfehler nicht mehr spezifiziert, der Logger zählte bis zu 34 Prozent zu wenig. Zwei Läufe fehlen ganz: am 20. November war ein Wandler beim Aufräumen vom Abgang gerutscht, am 3. Dezember war die SD-Karte voll, weil der Logger zusätzlich die Rohdaten mitschrieb. Über die 32 gerechneten Läufe zählte der geeichte Zähler 214,6 Kilowattstunden, der Logger 211,1, das sind 1,6 Prozent Unterschied und damit weniger als die 2,8 Prozent erweiterte Unsicherheit aus dem Budget. Auf den Leerlauf entfielen in denselben fünf Wochen 63 Kilowattstunden, also 29 Prozent.","type":"text"}]}'),
(14, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Für die Nachkalkulation reicht uns die Energie je Auftrag mit 3 Prozent. Was uns wirklich gefehlt hat, ist der Leerlauf, und der steht hier drin.","type":"text"}]},{"type":"paragraph","content":[{"text":"Rückmeldung der Werkstattleitung bei der Besprechung am 12. Dezember 2024","type":"text","marks":[{"type":"italic"}]}]}]}'),
(15, 'DOCUMENT', '{"type":"documentBlock","attrs":{"size":486000,"fileId":"d0d00022-0000-4000-8000-220000000003","caption":"Alle 34 Läufe mit Leistungsgang, Energie je Lauf und Leerlaufanteil. Die neun Läufe mit mehr als 5 Prozent Abweichung sind grau hinterlegt.","fileName":"messprotokoll-fraese-november-2024.pdf"}}')
) as v(order_index, type, content);

-- Projekt 23: Drossel Huckelriede: bis 10 Millimeter Regen genau, darüber nicht
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000023'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '290 days', now() - interval '200 days'
from (values
(0, 'TABLE_OF_CONTENTS', '{"type":"tableOfContents","attrs":{"entries":[{"text":"Drosselregelung im Stauraumkanal Huckelriede","index":0,"level":1},{"text":"Die Messkette im Schacht","index":1,"level":2},{"text":"Das Modell und die nachgemessene Drossel","index":2,"level":2},{"text":"41 Regenereignisse im Vergleich","index":3,"level":2}]}}'),
(1, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"text":"Drosselregelung im Stauraumkanal Huckelriede","type":"text"}]}'),
(2, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Der Stauraumkanal in Huckelriede hält bei Regen Mischwasser zurück, damit die Entlastung in den Werdersee selten anspringt. Wie viel er zurückhält, entscheidet die Drossel am Auslauf: bisher eine feste Blende, in dieser Arbeit ein geregelter Schieber mit Wasserstandsrückführung. Die Frage war nicht, ob sich so etwas simulieren lässt, sondern ob das Modell dem Betrieb standhält. Deshalb stehen hier 41 gemessene Regenereignisse neben 41 gerechneten.","type":"text"}]}'),
(3, 'IMAGE', '{"type":"imageBlock","attrs":{"alt":"Betonschacht eines Drosselbauwerks von oben, Steigleiter an der Wand, dunkle Wasseroberfläche am Grund","width":100,"fileId":"d0d00022-0000-4000-8000-230000000000","caption":"Der Schacht ist 4,20 Meter tief. Der Schieber sitzt hinter der Trennwand rechts, die Sonden hängen an der Leiterschiene."}}'),
(4, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Die Messkette im Schacht","type":"text"}]}'),
(5, 'LIST', '{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Zwei Drucksonden, 0 bis 4 Meter Wassersäule, 4 bis 20 mA, mit Kapillarschlauch für den Luftdruckausgleich. Die zweite hängt 60 Zentimeter versetzt und dient nur dem Vergleich.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Kippwaagen-Regenmesser auf dem Dach der Pumpstation, 0,1 Millimeter je Kippung, abgeglichen mit den ","type":"text"},{"text":"Stundenwerten der DWD-Station Bremen","type":"text","marks":[{"type":"link","attrs":{"href":"https://opendata.dwd.de/","target":"_blank","rel":"noopener noreferrer"}}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Logger mit 10-Sekunden-Takt und Pufferbatterie für 72 Stunden, weil die Steckdose im Schacht an derselben Sicherung hängt wie die Pumpe.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wegaufnehmer am Schieber, damit die gefahrene Stellung in die Auswertung geht und nicht die befohlene.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wöchentlicher Nullpunktabgleich von Hand, mit Lichtlot und Protokollzettel im Schaltschrank.","type":"text"}]}]}]}'),
(6, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Die erste Fassung hing an einem Ultraschallsensor über der Wasseroberfläche. Bei starkem Regen misst der nicht das Wasser, sondern den Schaum und die Tropfen darüber: an drei Terminen im Oktober fehlen die ersten 20 Minuten, also genau der Teil des Ereignisses, auf den es ankommt. Diese drei Termine sind nicht in der Auswertung, von 44 aufgezeichneten Ereignissen bleiben deshalb 41. Seit dem Umbau auf die Drucksonden gibt es keine Lücke mehr, dafür eine Drift von 3 Zentimetern über die 14 Monate, die der wöchentliche Abgleich herausrechnet.","type":"text"}]}'),
(7, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Das Modell und die nachgemessene Drossel","type":"text"}]}'),
(8, 'FORMULA', '{"type":"mathBlock","attrs":{"latex":"Q(h) = \\mu \\cdot A \\cdot \\sqrt{2\\,g\\,h}, \\quad \\mu_{\\mathrm{Datenblatt}} = 0{,}70, \\quad \\mu_{\\mathrm{gemessen}} = 0{,}62"}}'),
(9, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Das Streckenmodell besteht aus dem Speicherinhalt des Kanals und dieser Drosselgleichung. Mit dem Datenblattwert lag der simulierte Wasserstand im Mittel 21 Zentimeter zu niedrig. Nachgemessen im Labor, 32 Punkte über den ganzen Hubbereich, kommt ein Abflussbeiwert von 0,62 heraus, also ","type":"text"},{"text":"gut 11 Prozent weniger Durchfluss bei gleichem Wasserstand","type":"text","marks":[{"type":"bold"}]},{"text":". Mit der gemessenen Kennlinie verschwindet der größte Teil des Fehlers. Was übrig blieb, ließ sich nicht auf die Drossel schieben, sondern auf den Zufluss.","type":"text"}]}'),
(10, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"41 Regenereignisse im Vergleich","type":"text"}]}'),
(11, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Niederschlag","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Ereignisse","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Median der Abweichung im Wasserstand","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Überläufe gemessen / simuliert","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"unter 5 mm","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"22","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2 cm","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"0 / 0","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"5 bis 10 mm","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"12","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"4 cm","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"1 / 2","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"10 bis 20 mm","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"5","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"9 cm","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"3 / 3","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"über 20 mm","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"17 cm","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2 / 2","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Alle Ereignisse","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"41","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"3 cm","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"6 / 7","type":"text"}]}]}]}]}'),
(12, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Bis 10 Millimeter Niederschlag ist das Modell brauchbar, der Median der Abweichung liegt bei höchstens 4 Zentimetern. Darüber wird es unangenehm: bei den beiden Ereignissen über 20 Millimeter setzt der Überlauf in der Simulation ","type":"text"},{"text":"19 Minuten zu früh","type":"text","marks":[{"type":"bold"}]},{"text":" ein, weil das Modell den Zufluss aus dem östlichen Teilgebiet zu schnell ankommen lässt. Gemessen wurden sechs Überläufe, gerechnet sieben. Der siebte stammt aus einem Ereignis mit 7 Millimetern, bei dem die Simulation 6 Zentimeter über der Entlastungsschwelle lag und die Messung 3 Zentimeter darunter. Für eine Regelung, die im Zweifel den Schieber schließt, ist das die harmlose Richtung des Fehlers; für eine Aussage über die Gewässerbelastung ist es die falsche.","type":"text"}]}'),
(13, 'GALLERY', '{"type":"galleryBlock","attrs":{"items":[{"alt":"Geöffneter Klemmkasten mit Datenlogger, Reihenklemmen und zwei angeschlossenen Sondenkabeln","fileId":"d0d00022-0000-4000-8000-230000000001"},{"alt":"Betonauslauf am Ufer eines Gewässers, Wasserlinie mit Algensaum","fileId":"d0d00022-0000-4000-8000-230000000002"},{"alt":"Laboraufbau mit Blende, Standrohr und Messbecken auf einer Werkbank","fileId":"d0d00022-0000-4000-8000-230000000003"}],"caption":"Links der Klemmkasten im Schacht, in der Mitte der Entlastungsauslauf am Werdersee, rechts der Aufbau, mit dem die Kennlinie nachgemessen wurde","columns":3}}'),
(14, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Das Bauwerk läuft seit zwanzig Jahren mit fester Drossel. Wenn Ihre Regelung ausfällt, muss der Schieber in die feste Stellung zurückfallen. Sonst steht das Wasser in Huckelriede in den Kellern, und dann fragt niemand mehr nach dem Modell.","type":"text"}]},{"type":"paragraph","content":[{"text":"Aus dem Gespräch mit der Schichtleitung, Klärwerk Seehausen, März 2025","type":"text","marks":[{"type":"italic"}]}]}]}'),
(15, 'DOCUMENT', '{"type":"documentBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-230000000004","fileName":"kalibrierprotokoll-drossel.pdf","size":412000,"caption":"Kennlinie der Drossel, 32 Messpunkte über den Hubbereich, jeweils mit der Abweichung zum Datenblattwert"}}')
) as v(order_index, type, content);

-- Projekt 24: Brackwatt der Unterweser mit 3.098 gezählten Tieren
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000024'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '310 days', now() - interval '230 days'
from (values
(0, 'TABLE_OF_CONTENTS', '{"type":"tableOfContents","attrs":{"entries":[{"text":"Eine Saison im Brackwatt der Unterweser","index":0,"level":1},{"text":"Wo und wie gezählt wurde","index":1,"level":2},{"text":"Was in den Rahmen lag","index":2,"level":2},{"text":"Was nicht funktioniert hat","index":3,"level":2}]}}'),
(1, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"type":"text","text":"Eine Saison im Brackwatt der Unterweser"}]}'),
(2, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Zwischen Sandstedt und der Strohauser Plate liegen keine 20 Flusskilometer, und trotzdem steigt der Salzgehalt im Uferwatt von rund 2 auf knapp 8 PSU. Mit ihm wechselt, was im Schlick lebt. Von April bis September 2025 haben wir drei Uferabschnitte an zehn Terminen kartiert, jedes Mal etwa 90 Minuten vor Niedrigwasser, damit die Flächen zum selben Wasserstand trockenfallen und die Zahlen vergleichbar bleiben."}]}'),
(3, 'IMAGE', '{"type":"imageBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-240000000001","alt":"Quadratischer Zählrahmen aus Aluminium auf feuchtem Schlick, daneben ein Spaten und ein Eimer","caption":"Fläche A bei Sandstedt, dritter Rahmen des Termins. Der Rahmen misst 25 mal 25 Zentimeter, ausgestochen wird 15 Zentimeter tief.","width":100}}'),
(4, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Wo und wie gezählt wurde"}]}'),
(5, 'LIST', '{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fünf Zählrahmen je Fläche und Termin, 25 mal 25 Zentimeter, also 0,0625 Quadratmeter Grundfläche"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ausstich 15 Zentimeter tief, gesiebt mit 0,5 Millimeter Maschenweite, gespült mit Flusswasser statt mit Süßwasser"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sortiert wird am selben Tag, bestimmt bis zur Art, wo das lebend möglich war, sonst bis zur Gattung"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Salzgehalt und Wassertemperatur bei jedem Termin am Ufer gemessen, in der Tabelle steht der Median über die acht Termine"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Die Termine hängen an den Niedrigwasserzeiten für Brake aus dem "},{"type":"text","text":"Gezeitenkalender des BSH","marks":[{"type":"link","attrs":{"href":"https://www.bsh.de","target":"_blank","rel":"noopener noreferrer"}}]},{"type":"text","text":", nicht an unserem Stundenplan"}]}]}]}'),
(6, 'VIDEO', '{"type":"videoBlock","attrs":{"provider":"vimeo","videoId":"76979871","width":100,"caption":"Ein Rahmen auf Fläche B, vom Setzen bis zum gespülten Sieb. Der Rahmen sackt dabei rund einen Zentimeter ein, deshalb stechen wir ab Oberkante Schlick aus und nicht ab Rahmenoberkante."}}'),
