(10, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Die Verteilung ist schief: Schlickkrebs und Wattschnecke stellen zusammen 2.039 der 3.098 Tiere, also 66 Prozent. Der Shannon-Index über alle Flächen liegt bei 1,44, das Maximum bei sechs Taxa wäre ln 6, also 1,79. Getrennt gerechnet steigt der Wert mit dem Salzgehalt: 1,02 bei Sandstedt, 1,31 bei Rechtenfleth, 1,38 an der Strohauser Plate. Auf der salzärmsten Fläche fanden wir zugleich nur "},{"type":"text","text":"43 Prozent","marks":[{"type":"bold"}]},{"type":"text","text":" der Individuenzahl der salzreichsten, und zwei Drittel davon waren Wenigborster. Wer nur die Individuenzahl betrachtet, hält Fläche A für arm; sie ist vor allem einseitig besiedelt."}]}'),
(11, 'GALLERY', '{"type":"galleryBlock","attrs":{"items":[{"fileId":"d0d00022-0000-4000-8000-240000000002","alt":"Sortierschalen mit Siebrückstand auf einem Labortisch, daneben Pinzette und Bestimmungsschlüssel"},{"fileId":"d0d00022-0000-4000-8000-240000000004","alt":"Hölzerner Anleger am Flussufer bei ablaufendem Wasser"}],"columns":2,"caption":"Links die Sortierstation, an der jede Probe noch am selben Abend durchgesehen wurde. Rechts der Anleger in Sandstedt, von dort sind wir zu Fläche A gelaufen."}}'),
(12, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Was nicht funktioniert hat"}]}'),
(13, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Zehn Termine sind wir gefahren, acht stehen in der Auswertung. An den beiden Aprilterminen haben wir mit einem Sieb von 1 Millimeter Maschenweite gearbeitet, und die jungen Wattschnecken sind hindurchgegangen: bei der Wiederholung mit 0,5 Millimeter kamen auf derselben Fläche etwa doppelt so viele Tiere heraus. Beide Termine stehen vollständig im Protokoll, gehen aber in keine Zahl dieses Beitrags ein. Das zweite Problem war die Wiederauffindbarkeit. Nach dem Sturm Ende Mai waren die Markierungsstäbe auf Fläche C verschwunden, und GPS allein reicht im Watt nicht, weil der Fehler größer ist als der Abstand zwischen zwei Rahmen. Seitdem messen wir jede Position über zwei feste Landmarken am Deich ein und notieren die Winkel im Protokoll."}]}'),
(14, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Zählen kann jeder. Schwierig ist, ein halbes Jahr später denselben Rahmen wiederzufinden."}]},{"type":"paragraph","content":[{"type":"text","text":"Rückmeldung im Kolloquium des Moduls Ökologie, Juli 2025","marks":[{"type":"italic"}]}]}]}'),
(15, 'DOCUMENT', '{"type":"documentBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-240000000003","fileName":"kartierprotokoll-sose-2025.pdf","size":486000,"caption":"Alle 120 Rahmen einzeln, dazu die beiden verworfenen Apriltermine, die Salzgehaltswerte je Termin und die Einmessung der Rahmenpositionen."}}')
) as v(order_index, type, content);

-- Projekt 25: Kieselalgenkulturen unter gestuftem Licht und Salzgehalt
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
