       now() - interval '165 days', now() - interval '100 days'
from (values
(0, 'TABLE_OF_CONTENTS', '{"type":"tableOfContents","attrs":{"entries":[{"text":"Kieselalgenkulturen unter gestuftem Licht und Salzgehalt","index":0,"level":1},{"text":"Ansatz und Kulturführung","index":1,"level":2},{"text":"Was die Wachstumskurve zeigt","index":2,"level":2},{"text":"Warum die ersten Zellzahlen zu niedrig lagen","index":3,"level":2}]}}'),
(1, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"text":"Kieselalgenkulturen unter gestuftem Licht und Salzgehalt","type":"text"}]}'),
(2, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Kieselalgen sitzen nicht fest. Durch einen Schlitz in der Schale, die Raphe, pressen sie Schleim nach außen und ziehen sich daran über die Unterlage, wenige Mikrometer je Sekunde. Im Freiland lässt sich schlecht trennen, woran diese Wanderung hängt, weil Licht, Salzgehalt und Wasserstand zusammen wechseln. Wir haben die beiden Größen deshalb einzeln eingestellt: ","type":"text"},{"text":"48 Kolben, zwölf Tage, drei Lichtstufen und zwei Salzgehalte","type":"text","marks":[{"type":"bold"}]},{"text":". Gezählt wurde alle zwei Tage die Zelldichte, an denselben Tagen dazu der Anteil der Zellen, die auf dem Objektträger eine Schleimspur hinterlassen.","type":"text"}]}'),
(3, 'IMAGE', '{"type":"imageBlock","attrs":{"alt":"Arbeitsplatz im Labor mit Mikroskop, Objektträgern und Probengläsern","width":75,"fileId":"d0d00022-0000-4000-8000-250000000001","caption":"Der Zählplatz stand die zwölf Tage über unverändert, damit Beleuchtung und Blendeneinstellung zwischen den Terminen gleich blieben"}}'),
(4, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Ansatz und Kulturführung","type":"text"}]}'),
(5, 'LIST', '{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ein Stamm von Navicula perminuta aus der ","type":"text"},{"text":"Sammlung von Algenkulturen Göttingen","type":"text","marks":[{"type":"link","attrs":{"href":"https://sagdb.uni-goettingen.de","rel":"noopener noreferrer","target":"_blank"}}]},{"text":", geführt in f/2-Medium auf künstlichem Seewasser, je 60 Milliliter in einem 100-Milliliter-Erlenmeyerkolben","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Salzgehalt in zwei Stufen, 5 und 18 PSU, aus künstlichem Meersalz und entsalztem Wasser eingestellt und vor jeder Entnahme mit dem Leitfähigkeitsmessgerät kontrolliert; gegen die Verdunstung wurde mit destilliertem Wasser aufgefüllt","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Klimaschrank bei 15 Grad Celsius, 14 Stunden hell und 10 Stunden dunkel, drei Lichtstufen mit 20, 60 und 180 µmol Photonen je Quadratmeter und Sekunde, eingemessen mit einem Quantensensor in Kolbenhöhe; die Kolben wurden täglich durchgetauscht","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Startdichte in jedem Kolben 8.000 Zellen je Milliliter aus derselben Vorkultur, alle zwei Tage ein Milliliter entnommen und in der Zählkammer nach Sedgewick-Rafter im Phasenkontrast bei 400-facher Vergrößerung ausgezählt","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Motilität am selben Tag: 0,5 Milliliter auf einen Objektträger, zehn Minuten unter der jeweiligen Lichtstufe, danach die Zellen abgespült und die zurückgebliebenen Schleimspuren mit Alcianblau angefärbt und ausgezählt","type":"text"}]}]}]}'),
(6, 'IMAGE', '{"type":"imageBlock","attrs":{"alt":"Mikroskop mit eingelegtem Objektträger, daneben Pipette und Deckgläser","width":100,"fileId":"d0d00022-0000-4000-8000-250000000002","caption":"Bei 1000-facher Vergrößerung mit Ölimmersion ist die Raphe als durchgehender Schlitz in der Schale zu sehen; an ihr tritt der Schleim aus, an dem sich die Zelle zieht"}}'),
(7, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Was die Wachstumskurve zeigt","type":"text"}]}'),
(8, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Alle 48 Kulturen wachsen, aber sehr verschieden schnell. Am dichtesten wurde der Ansatz mit 60 µmol und 18 PSU, mit 214.000 Zellen je Milliliter an Tag 12, also das ","type":"text"},{"text":"5,2-fache","type":"text","marks":[{"type":"bold"}]},{"text":" des schwächsten Ansatzes. Der Salzgehalt wirkt in jeder Lichtstufe gleichsinnig: Bei 18 PSU stehen 2,3- bis 2,7-mal so viele Zellen wie bei 5 PSU. Die dritte Lichtstufe kehrt den Trend um. 180 µmol bringt weniger Zellen als 60 µmol, und der Anteil der Zellen mit Schleimspur fällt von 74 auf 38 Prozent: Die Zellen sammeln sich im Bodenfilm des Kolbens statt an der beleuchteten Wand, sie wandern also vom starken Licht weg. Die mittlere Verdopplungszeit steht als Formel unter der Tabelle und reicht von 61 bis 122 Stunden.","type":"text"}]}'),
(9, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Ansatz (Licht in µmol, Salzgehalt in PSU)","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Kolben","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Zellen je Milliliter an Tag 12","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Zellen mit Schleimspur","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"20 / 5","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"8","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"41.000","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"44 Prozent","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"20 / 18","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"8","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"94.000","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"61 Prozent","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"60 / 5","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"8","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"78.000","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"52 Prozent","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"60 / 18","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"8","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"214.000","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"74 Prozent","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"180 / 5","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"8","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"63.000","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"29 Prozent","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"180 / 18","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"8","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"152.000","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"38 Prozent","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Summe","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"48","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"107.000 im Mittel","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"50 Prozent im Mittel","type":"text"}]}]}]}]}'),
(10, 'FORMULA', '{"type":"mathBlock","attrs":{"latex":"t_{d} = \\frac{t \\cdot \\ln 2}{\\ln\\left(N_{t}/N_{0}\\right)}, \\quad N_{0} = 8\\,000\\,\\mathrm{mL}^{-1},\\; t = 288\\,\\mathrm{h}"}}'),
(11, 'DIVIDER', '{"type":"horizontalRule"}'),
(12, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Warum die ersten Zellzahlen zu niedrig lagen","type":"text"}]}'),
(13, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Die ersten vier Zähltermine stehen nicht so in der Tabelle, wie sie zuerst herauskamen. Anfangs lief ein Bildanalyseprogramm über je zwanzig Aufnahmen und zählte, was es als zusammenhängende Fläche fand. In dichten Kulturen kleben die Zellen aber in ihrem eigenen Schleim aneinander: Ein Klumpen aus fünf oder sechs Zellen ist für das Programm eine einzige, und bei 18 PSU, wo am meisten Schleim entsteht, lagen die Werte 23 Prozent unter der Handzählung. Seit Tag 10 wird von Hand gezählt und jeder Kolben vor der Entnahme 30 Sekunden geschwenkt; die vier ersten Termine haben wir aus den gespeicherten Aufnahmen neu ausgezählt. Zwei Kolben der Stufe 20 µmol und 5 PSU waren an Tag 8 bakteriell überwachsen, sie stehen mit ihrem letzten sauberen Wert in der Reihe und sind im Protokoll gekennzeichnet. Was der Versuch nicht hergibt: Wir haben einen einzigen Stamm geführt und die Spuren nur auf Glas gezählt, nicht auf Sediment. Ob die Zellen bei 180 µmol dem Licht ausweichen oder die Wanderung ganz einstellen, entscheidet diese Reihe deshalb nicht.","type":"text"}]}'),
(14, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Zählen Sie nicht das, was Sie sehen wollen. Geben Sie ein Dutzend Präparate weiter, ohne die Lichtstufe daraufzuschreiben, und vergleichen Sie hinterher.","type":"text"}]},{"type":"paragraph","content":[{"text":"Anmerkung aus der Zwischenbesprechung im Modul Zellbiologie","type":"text","marks":[{"type":"italic"}]}]}]}'),
(15, 'DOCUMENT', '{"type":"documentBlock","attrs":{"size":214000,"caption":"Zwölf der 48 Kolben hat eine zweite Person ohne Kenntnis von Lichtstufe und Salzgehalt nachgezählt, mittlere Abweichung 6 Prozent. Diese Zweitzählungen stecken nicht in den Werten der Tabelle.","fileId":"d0d00022-0000-4000-8000-250000000003","fileName":"protokoll-kulturversuch.pdf"}}')
) as v(order_index, type, content);

