       now() - interval '65 days', now() - interval '18 days'
from (values
(0, 'TABLE_OF_CONTENTS', '{"type":"tableOfContents","attrs":{"entries":[{"text":"Vier Zonen, zwei Exkursionstage","index":0,"level":1},{"text":"Ablauf und Zeitfenster","index":1,"level":2},{"text":"Was die 72 Bestimmungen ergaben","index":2,"level":2},{"text":"Woran die erste Fassung scheiterte","index":3,"level":2}]}}'),
(1, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"text":"Vier Zonen, zwei Exkursionstage","type":"text"}]}'),
(2, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Von der Deichkrone aus ist die Salzwiese eine einzige graugrüne Fläche. Wer hineingeht, läuft in zwanzig Metern durch drei Bestände, die sich in Überflutungsdauer, Bodensalz und Artenzahl deutlich unterscheiden. Genau das ist der Anlass für diese Exkursion im Sammelmodul: Die Gruppe legt in vier Zonen Aufnahmeflächen an und versucht, das Gefundene im Feld zu benennen, mit einem Schlüssel, den wir selbst geschrieben haben. Der Feldtest galt am Ende weniger den Pflanzen als dem Schlüssel.","type":"text"}]}'),
(3, 'IMAGE', '{"type":"imageBlock","attrs":{"alt":"Niedriger, dichter Grasbestand einer Salzwiese mit kahlen Schlickstellen dazwischen","width":75,"fileId":"d0d00022-0000-4000-8000-260000000001","caption":"Andel und Rot-Schwingel wachsen hier ineinander. Auf dem Foto sind sie nicht zu trennen, im Schlüssel entscheidet darüber ein Blatthäutchen von unter einem Millimeter."}}'),
(4, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Ablauf und Zeitfenster","type":"text"}]}'),
(5, 'LIST', '{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Treffpunkt am Deichübergang vier Stunden vor Hochwasser, denn nur so lange liegt die Quellerzone verlässlich frei. Am 4. Juni wurden daraus zweieinhalb Stunden, weil der Zug nach Bremerhaven ausfiel.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Belehrung und Prielregel: Niemand geht allein über einen Priel, die acht Gruppen bleiben in Sichtweite zueinander.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Je Zone drei Aufnahmeflächen mit dem Rahmen, 50 mal 50 Zentimeter, dazu der geschätzte Deckungsgrad jeder Art auf dem Bogen.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bestimmung im Feld mit der ersten Fassung des Schlüssels, Eintrag auf dem Protokollbogen, Belegfoto mit Maßstab neben der Pflanze.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Von jeder unsicheren Bestimmung kommt ein Belegexemplar in die Presse, abends Kontrolle in der Feldstation mit Binokular und Vergleichsherbar.","type":"text"}]}]}]}'),
(6, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Was die 72 Bestimmungen ergaben","type":"text"}]}'),
(7, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Zone","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Bestimmungen","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"bestätigt","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"korrigiert","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Quellerzone","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"22","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"20","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Untere Salzwiese","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"20","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"14","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"6","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Obere Salzwiese","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"18","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"13","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"5","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Spülsaum am Deichfuß","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"12","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"10","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Summe","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"72","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"57","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"15","type":"text","marks":[{"type":"bold"}]}]}]}]}]}'),
(8, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Von 72 Bestimmungen hielten 57 der Kontrolle stand, ","type":"text"},{"text":"jede fünfte war falsch","type":"text","marks":[{"type":"bold"}]},{"text":". Die Fehler verteilen sich dabei nicht gleichmäßig: In der unteren Salzwiese lag die Quote bei 30 Prozent, in der oberen bei 28 Prozent, in der Quellerzone dagegen bei 9 Prozent. Die beiden schlechten Zonen sind die, in denen Gräser den Bestand tragen. Gräser trennt der Schlüssel über Blatthäutchen und Blütenstand, und beides ist Anfang Juni entweder winzig oder noch gar nicht da. Die 12 Bestimmungen vom Spülsaum stammen alle vom zweiten Tag; am 4. Juni ging es wegen der späten Anreise sofort nach draußen, und der Deichfuß blieb liegen.","type":"text"}]}'),
(9, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Woran die erste Fassung scheiterte","type":"text"}]}'),
(10, 'LIST', '{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sechsmal ging Andel (Puccinellia maritima) als Rot-Schwingel durch. Der Schlüssel trennt beide über das Blatthäutchen, und das ist keinen Millimeter lang; mit nassen Fingern im Wind zieht dafür niemand einen Halm auseinander.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Fünfmal stand Strand-Wegerich im Protokoll, wo Strand-Aster (Tripolium pannonicum) wuchs. Beide bilden dieselbe flache Rosette aus fleischigen Blättern, und der Schlüssel bot für den Unterschied nur den Blütenstand an. Anfang Juni blühte auf keiner Fläche etwas.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Viermal wurde Strand-Sode (Suaeda maritima) zu Queller erklärt. Der Schlüssel fragt an dieser Stelle nach den Blüten in den Segmenten; die sitzen so tief, dass sie erst im September und erst unter dem Binokular auftauchen.","type":"text"}]}]}]}'),
(11, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Die erste Fassung hatte 19 Schritte, fünf davon waren ohne Binokular oder ohne blühende Pflanze nicht zu beantworten. Am Schreibtisch ist das kein Problem, in der Salzwiese ist es das Ende der Bestimmung. Die zweite Fassung kommt mit 16 Schritten aus, und jeder Schritt lässt sich mit einer zehnfachen Lupe und einem Zollstock entscheiden. Wo ein Merkmal nur an der blühenden Pflanze sichtbar ist, steht das jetzt in der Zeile darüber; wo eine Größe hilft, steht eine Millimeterangabe statt eines Adjektivs.","type":"text"}]}'),
(12, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Was nicht blüht, steht für uns nicht im Schlüssel. Wir waren im Juni da, geschrieben ist er für den September.","type":"text"}]},{"type":"paragraph","content":[{"text":"Eintrag im Protokollbogen der Gruppe 5, zweiter Exkursionstag am 11. Juni 2026","type":"text","marks":[{"type":"italic"}]}]}]}'),
(13, 'DOCUMENT', '{"type":"documentBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-260000000002","fileName":"bestimmungsschluessel-salzwiese.pdf","size":412000,"caption":"Zweite Fassung des Schlüssels mit 16 Schritten, dazu der Protokollbogen als letzte Seite zum Ausdrucken"}}'),
(14, 'DIVIDER', '{"type":"horizontalRule"}'),
(15, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Wer den Schlüssel mitnimmt, sollte zwei Dinge vorher klären. Die Betretungsregeln der Schutzzonen stehen beim ","type":"text"},{"text":"Nationalpark Wattenmeer","type":"text","marks":[{"type":"link","attrs":{"href":"https://www.nationalpark-wattenmeer.de","target":"_blank","rel":"noopener noreferrer"}}]},{"text":", und der Termin richtet sich nach der Blütezeit, nicht nach dem Seminarplan. Anfang September liegt ungünstig im Semester, kostet aber weniger als eine Zone, die am Ende niemand sicher bestimmt.","type":"text"}]}')
) as v(order_index, type, content);

-- Projekt 27: Grabzyklus der Schwertmuschel, nachgebaut als Sonde
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000027'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '470 days', now() - interval '390 days'
from (values
(0, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"text":"Vom Wattboden in den Sedimentzylinder","type":"text"}]}'),
(1, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Die Amerikanische Schwertmuschel steht senkrecht im Wattboden und verschwindet darin schneller, als man nachgraben kann. Sie drückt sich dabei nicht einfach hinein: sie schließt ihre Schalen ruckartig, verflüssigt damit den Sand in ihrer unmittelbaren Umgebung und zieht sich in den weichen Bereich nach. Uns hat interessiert, wie viel Arbeit dieser Takt spart und ob eine Sonde mit ","type":"text"},{"text":"nur einem bewegten Bauteil","type":"text","marks":[{"type":"bold"}]},{"text":" dasselbe schafft.","type":"text"}]}'),
(2, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Was die Muschel tut","type":"text"}]}'),
(3, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Für die Vorstudie haben wir sieben Tiere aus dem Watt bei Wremen in einen Beobachtungszylinder mit Glaswand gesetzt und 26 Grabzyklen mit 240 Bildern pro Sekunde gefilmt. Ein Zyklus dauert im Median 0,86 Sekunden, der Vortrieb je Zyklus liegt bei 4,1 Millimetern. Auffällig war die Reihenfolge: das Aufweiten der Fußspitze kommt erst nach dem Schalenschluss, nicht davor. Genau daran ist später unser erster Steuerplan gescheitert.","type":"text"}]}'),
(4, 'LIST', '{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Der Fuß streckt sich nach unten, die Schale bleibt stehen; noch hält nichts","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Die Schalen schließen ruckartig, Wasser tritt aus, das Sediment rund um die Schale verliert seinen Halt","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Die Fußspitze schwillt an und verankert sich in dem kurz verflüssigten Bereich","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Der Längsmuskel zieht die Schale nach, dann beginnt der nächste Zyklus","type":"text"}]}]}]}'),
(5, 'AUDIO', '{"type":"audioBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-270000000004","caption":"Ein Grabzyklus im Beobachtungszylinder, aufgenommen mit einem Kontaktmikrofon an der Glaswand. Das kurze Klacken ist der Schalenschluss, das Rauschen danach das nachrutschende Sediment."}}'),
(6, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Der Nachbau","type":"text"}]}'),
(7, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Die Sonde ist 32 Millimeter dick und 210 Millimeter lang: zwei gedruckte Schalenhälften aus PETG auf einem Pneumatikzylinder, dazu ein zweiter Zylinder für die Fußspitze, geschaltet über zwei Magnetventile bei 4 bar. Der Takt liegt bei 1,1 Hertz und damit nah an den 0,86 Sekunden, die ein Tier je Zyklus braucht. Die erste Steuerung hatte die Reihenfolge aus dem Video verdreht: sie weitete die Spitze auf und schloss erst danach die Schalen. So kam die Sonde 40 Millimeter tief und stand. Erst mit dem Schalenschluss zuerst lief der Takt durch.","type":"text"}]}'),
(8, 'GALLERY', '{"type":"galleryBlock","attrs":{"items":[{"alt":"Senkrechter Glaszylinder voller Sand auf einem Labortisch, darüber die eingespannte Sonde","fileId":"d0d00022-0000-4000-8000-270000000001"},{"alt":"Zwei gedruckte Schalenhälften aus Kunststoff neben einem Pneumatikzylinder auf einer Werkbank","fileId":"d0d00022-0000-4000-8000-270000000002"},{"alt":"Ventilblock mit zwei Magnetventilen, Schläuchen und der Steuerplatine","fileId":"d0d00022-0000-4000-8000-270000000003"}],"caption":"Der Sedimentzylinder fasst 40 Zentimeter Füllhöhe. Die Schalenhälften in der Mitte sind die zweite Fassung, sichtbar am umlaufenden Falz für den Latexbalg.","columns":3}}'),
(9, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Wird eine Sonde nur geschoben, wächst der Widerstand mit der Tiefe, und die Arbeit steigt quadratisch. Verflüssigt sie das Sediment kurz in ihrer nächsten Umgebung, bleibt die nötige Kraft über weite Strecken fast gleich, und die Arbeit steigt nur linear:","type":"text"}]}'),
(10, 'FORMULA', '{"type":"mathBlock","attrs":{"latex":"E_{\\mathrm{schieben}}(d) = \\int_{0}^{d} k\\,z\\,\\mathrm{d}z = \\tfrac{1}{2}\\,k\\,d^{2}, \\qquad E_{\\mathrm{takten}}(d) \\approx F_{0}\\,d"}}'),
(11, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"48 Versuche im Zylinder","type":"text"}]}'),
(12, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Sediment","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Versuche","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Median Eindringtiefe nach 60 s in mm","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"ohne Eindringen","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Feinsand, d50 0,16 mm","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"18","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"172","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Mischwatt","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"16","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"141","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"5","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Schlick, d50 0,02 mm","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"14","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"96","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"9","type":"text"}]}]}]}]}'),
(13, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Zusammen sind das 48 Versuche, 16 davon endeten ohne messbares Eindringen, neun allein im Schlick. Bis 150 Millimeter Tiefe, so weit kam auch die Vergleichssonde mit festgeklemmten Schalen, brauchte die getaktete Sonde ","type":"text"},{"text":"den 5,2-fach kleineren Arbeitsbetrag","type":"text","marks":[{"type":"highlight","attrs":{"color":"amber"}}]},{"text":". Nicht mitgezählt ist die erste Fassung: bei ihr lief nach elf Läufen Sand durch den Spalt zwischen den Schalenhälften in den Pneumatikzylinder, das Ventil klemmte, und die Kraftkurven waren nicht mehr zu gebrauchen. Erst ein übergezogener Latexbalg hat das behoben. Im Schlick half auch der nichts: die feinen Körner halten aneinander, das kurze Aufweiten verflüssigt dort nichts, und die Sonde steht im Median nach 96 Millimetern.","type":"text"}]}'),
(14, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Im Schlick gräbt sich auch keine Schwertmuschel ein. Ihr habt das Tier nachgebaut, samt seiner Grenzen.","type":"text"}]},{"type":"paragraph","content":[{"text":"Anmerkung aus der Zwischenbesprechung im Modul Biomechanik","type":"text","marks":[{"type":"italic"}]}]}]}'),
(15, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Die beiden Sammeltermine richteten sich nach dem ","type":"text"},{"text":"Gezeitenkalender des BSH","type":"text","marks":[{"type":"link","attrs":{"href":"https://www.bsh.de","rel":"noopener noreferrer","target":"_blank"}}]},{"text":", jeweils 90 Minuten vor Niedrigwasser. Alle sieben Tiere sind nach den Aufnahmen zurück ins Watt gesetzt worden; sechs waren binnen einer Minute wieder verschwunden, das siebte brauchte knapp vier und war damit immer noch schneller als jede unserer Sonden.","type":"text"}]}')
) as v(order_index, type, content);

-- Projekt 28: Gelatine mit Eisen: unter Wasser bricht der Sandstein, nicht die Fuge
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000028'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '140 days', now() - interval '90 days'
from (values
(0, 'TABLE_OF_CONTENTS', '{"type":"tableOfContents","attrs":{"entries":[{"text":"Vier Serien im Wasserbad","index":0,"level":1},{"text":"Der Prüfstand in der Werkstatt","index":1,"level":2},{"text":"Vier Serien, 108 Proben","index":2,"level":2},{"text":"Was beim Bruch zu hören ist","index":3,"level":2}]}}'),
(1, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"text":"Vier Serien im Wasserbad","type":"text"}]}'),
(2, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Miesmuscheln halten sich mit Byssusfäden an nassem Stein fest, und zwar sofort, ohne Trocknungszeit. Genau das kann kein Klebstoff aus dem Baumarkt. Wir wollten wissen, wie weit man mit Werkstattmitteln herankommt, und haben in der offenen Werkstatt am Neustadtswall jeden Donnerstagabend Proben angesetzt und gezogen, alle unter Wasser, alle mit demselben Stempel: ","type":"text"},{"text":"108 Haftproben in elf Wochen","type":"text","marks":[{"type":"bold"}]},{"text":". Die Reihe gehört zu keinem Modulplan, die Auswertung haben wir danach in der Sprechstunde der Werkstoffkunde vorgelegt.","type":"text"}]}'),
(3, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Der Prüfstand in der Werkstatt","type":"text"}]}'),
(4, 'LIST', '{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Substrate: Edelstahl 1.4301, geschliffen mit Körnung 320, und Sandstein aus dem Restestapel der Werkstatt, beide vor dem Kleben 24 Stunden gewässert","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Stempel aus Messing, 20 Millimeter Durchmesser, aufgesetzt im Wasserbad und dort belassen, bis geprüft wird","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Zugrahmen mit Handkurbel und Kraftmessdose bis 500 Newton, Vorschub von Hand nachgeführt auf etwa 5 Newton je Sekunde","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Kontaktmikrofon am Rahmen, Aufnahme mit 48 kHz, damit das Knacken vor dem Bruch dokumentiert ist","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wasserbad mit Aquarienheizer auf 19 Grad, kontrolliert mit zwei Thermometern an gegenüberliegenden Ecken","type":"text"}]}]}]}'),
(5, 'IMAGE', '{"type":"imageBlock","attrs":{"alt":"Zugrahmen aus Vierkantstahl auf einer Werkbank, darunter ein flaches Wasserbecken mit aufgeklebten Messingstempeln","width":75,"fileId":"d0d00022-0000-4000-8000-280000000001","caption":"Der Rahmen stammt aus dem Fundus der Werkstatt, nur die Kraftmessdose war geliehen. Umgebaut wurde er nach der Vorserie: seitdem steht er im Becken."}}'),
(6, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Vier Serien, 108 Proben","type":"text"}]}'),
(7, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Serie und Bindemittel","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Proben","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Haftfestigkeit im Mittel","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Häufigstes Bruchbild","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"A: Zweikomponentenkleber aus dem Baumarkt (Referenz)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"24","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"41 kPa","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Ablösung an der Stahlseite","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"B: Fischgelatine, 20 Prozent, ohne Zusatz","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"28","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"62 kPa","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Bruch in der Klebeschicht","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"C: Fischgelatine mit Eisen(III)-citrat","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"30","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"214 kPa","type":"text","marks":[{"type":"textStyle","attrs":{"color":"green"}}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Ausbruch im Sandstein","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"D: Fischgelatine mit Eisen(III)-citrat und Gerbsäure","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"26","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"158 kPa","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Bruch in der Klebeschicht","type":"text"}]}]}]}]}'),
(8, 'FORMULA', '{"type":"mathBlock","attrs":{"latex":"\\sigma = \\frac{F_{\\max}}{A}, \\quad A = \\pi r^{2} = 314\\,\\mathrm{mm}^{2}"}}'),
(9, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Mehr steckt hinter der Haftfestigkeit nicht: Höchstkraft geteilt durch Stempelfläche. Serie C reißt im Mittel bei 67 Newton, die Referenz bei 13 Newton. Dass Serie C 30 und Serie D nur 26 Proben zählt, liegt an zwei verrutschten Stempeln in D, die wir mit dem Bindemittel von C neu geklebt haben; zusammen bleiben es 108. Vor diesen vier Serien liegt eine Vorserie von 18 Proben, die vollständig unbrauchbar ist. Wir hatten die Proben zum Prüfen aus dem Bad genommen und die drei Meter zum Rahmen getragen, gut 20 Sekunden an Luft. Genau diese 20 Sekunden misst man dann und nicht das Bindemittel: die Werte lagen um das Dreifache über allem, was danach unter Wasser herauskam.","type":"text"}]}'),
(10, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Was beim Bruch zu hören ist","type":"text"}]}'),
(11, 'AUDIO', '{"type":"audioBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-280000000003","caption":"Serie C, Probe 71, Körperschall am Prüfrahmen. Bei Sekunde 4 knackt es zweimal, der Bruch kommt erst bei Sekunde 9."}}'),
(12, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Das Kontaktmikrofon hing anfangs nur mit, weil ich es vom Watt her gewohnt bin, alles mitzuschneiden. Es hat sich gelohnt: ","type":"text"},{"text":"bei 14 von 108 Proben knackt es hörbar, bevor die Kraft abfällt","type":"text","marks":[{"type":"textStyle","attrs":{"color":"amber"}}]},{"text":", und diese 14 liegen im Mittel 30 Prozent unter ihrer Serie. Vermutlich lösen sich einzelne Randbereiche der Klebefläche vorzeitig. Nachgewiesen haben wir das nicht, dafür fehlt uns die Optik im Wasser; im Protokoll ist aber jede Aufnahme mit der Probennummer verknüpft, sodass das jemand weiterverfolgen kann.","type":"text"}]}'),
(13, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Wenn ihr die Proben an Luft tragt, prüft ihr die Trocknungszeit und nicht den Klebstoff. Baut den Rahmen ins Becken oder lasst es bleiben.","type":"text"}]},{"type":"paragraph","content":[{"text":"Anmerkung aus der Sprechstunde im Modul Werkstoffkunde, nach Durchsicht der Vorserie","type":"text","marks":[{"type":"italic"}]}]}]}'),
(14, 'DOCUMENT', '{"type":"documentBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-280000000002","fileName":"haftproben-protokoll.pdf","size":268431,"caption":"Prüfprotokoll aller 108 Proben mit Höchstkraft, Wassertemperatur, Standzeit im Bad und der Nummer der zugehörigen Aufnahme"}}'),
(15, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Die Muscheln für die Vorversuche stammen von der Bank vor Wremen; wir haben nur die Fäden unter dem Mikroskop angesehen und die Tiere am selben Tag zurückgebracht. Der Klebstoff selbst hat mit Muscheln nichts zu tun, er borgt sich das Prinzip: ein weiches Eiweiß, das mit Eisen vernetzt und dabei kein trockenes Substrat braucht. Wer die Reihe fortsetzt, sollte beim Sandstein anfangen, denn dort bricht nicht mehr die Fuge, sondern der Stein.","type":"text"}]}')
) as v(order_index, type, content);

-- Projekt 29: Warum Mädchen ab vierzehn wegbleiben
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000029'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '305 days', now() - interval '240 days'
from (values
(0, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"type":"text","text":"Ab dem 14. Geburtstag bricht es ein"}]}'),
(1, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Der offene Treff am Pastorenweg in Gröpelingen hat an vier Nachmittagen in der Woche geöffnet. In den 14 Wochen dieser Erhebung, von März bis Juni 2025, kamen im Schnitt 21 Jugendliche je Öffnungstag, davon 5 Mädchen über 13. Bei den Jüngeren ist das Verhältnis ausgeglichen. Die Praxisstelle hat mich deshalb nicht mit der Frage losgeschickt, ob etwas fehlt, sondern mit der Frage, was zwischen dem 13. und dem 15. Lebensjahr passiert."}]}'),
(2, 'IMAGE', '{"type":"imageBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-290000000001","alt":"Küchentisch mit Tassen, Schneidebrett und Stühlen in einem Gruppenraum","caption":"An diesem Tisch liefen 17 der 24 Gespräche, die übrigen unterwegs oder im Hof","width":75}}'),
(3, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Wie die Gespräche zustande kamen"}]}'),
(4, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Die erste Fassung des Leitfadens hatte 18 Fragen, gestellt im Büro der Einrichtung, mit dem Aufnahmegerät auf dem Tisch. Fünf Gespräche liefen so, und alle fünf waren unbrauchbar: Die längste Antwort hatte sieben Wörter. "},{"type":"text","text":"Geredet wurde erst, als die Fragen an den Küchentisch wanderten","marks":[{"type":"bold"}]},{"type":"text","text":" und nebenbei gekocht oder abgeräumt wurde. Die fünf Gespräche haben wir später in der neuen Form wiederholt; sie zählen in der Auswertung einmal."}]}'),
(5, 'LIST', '{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Gespräch beim Tun: am Küchentisch, beim Kochen oder auf dem Weg zur Bushaltestelle, nie im Büro"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Leitfaden auf sieben offene Fragen gekürzt, Nachfragen frei, keine Reihenfolge erzwungen"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Aufnahme nur mit schriftlicher Einwilligung, sonst Mitschrift: 3 der 24 Befragten wollten kein Gerät dabei haben"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Namen, Schulen und Straßenzüge schon beim Abtippen ersetzt, die Tonspuren nach dem Transkribieren gelöscht"}]}]}]}'),
(6, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Was die 24 gesagt haben"}]}'),
(7, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Angefragt haben wir 31 Mädchen und junge Frauen zwischen 13 und 17, die im Vorjahr in den Anwesenheitslisten stehen. 24 haben zugesagt und sind gekommen, 7 nicht. Die Gespräche dauerten zwischen 12 und 41 Minuten, im Mittel 19. Codiert haben wir zu zweit und unabhängig voneinander; bei 5 der 24 Gespräche war der Hauptgrund strittig, die sind wir gemeinsam noch einmal durchgegangen. Die Praxisanleitung war bei keinem Gespräch dabei, hat die Kategorien aber jede Woche mitgelesen."}]}'),
(8, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Hauptgrund"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Nennungen"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"davon 14 oder 15 Jahre"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Heimweg im Dunkeln, niemand begleitet"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"9"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"7"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Geschwisterbetreuung und Haushalt"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"6"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"4"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Kein Raum, in dem nicht die Jungen bestimmen"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"5"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"3"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Schule, Nachhilfe, Prüfungen"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"3"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"1"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Verein oder Nebenjob am Nachmittag"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"1"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"1"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Summe","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"24","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"16","marks":[{"type":"bold"}]}]}]}]}]}'),
(9, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Gerechnet hatten wir mit dem Programm, also mit der Antwort, dass Kicker und Konsole nicht mehr interessieren. Genannt wurde etwas anderes: "},{"type":"text","text":"Die häufigste Antwort war der Heimweg","marks":[{"type":"bold"}]},{"type":"text","text":". Der Treff schloss bis Mai um 20 Uhr, die Straßenzüge dazwischen sind ab Oktober dunkel, und wer nicht abgeholt wird, geht 15 Minuten allein. Das steht in keinem Konzept, und mit einem besseren Angebot ist es nicht auszugleichen. 16 der 24 Befragten waren 14 oder 15 Jahre alt, also genau in dem Alter, in dem die Anwesenheitslisten einbrechen."}]}'),
(10, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Ich komme ja gern. Aber meine Mutter sagt, ab sechs bin ich zu Hause, und im November ist es ja schon um fünf dunkel."}]},{"type":"paragraph","content":[{"type":"text","text":"Befragte 09, 15 Jahre, Gespräch auf dem Weg zur Bushaltestelle","marks":[{"type":"italic"}]}]}]}'),
(11, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Was der Treff daraufhin geändert hat"}]}'),
(12, 'LIST', '{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Der Mittwoch endet seit Mai um 18.30 Uhr statt um 20 Uhr, und zwei Ehrenamtliche gehen in zwei Richtungen bis zur Haltestelle mit. An den ersten sechs Mittwochen kamen im Schnitt 9 Mädchen über 13 statt 5. Sechs Termine sind zu wenig für eine Aussage über das Jahr, im Winter zählen wir nach."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Der Gruppenraum gehört mittwochs bis 17 Uhr den Mädchen. Das war die umstrittenste Änderung im Team und hat zwei Sitzungen gekostet, weil sie einem offenen Treff erst einmal widerspricht."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Die Anwesenheit wird seit April nach Alter und Geschlecht notiert, vorher standen dort nur die Namen. Ohne diese Zahlen war die Ausgangsfrage gar nicht zu beantworten, wir mussten sie für das Vorjahr aus alten Listen rekonstruieren."}]}]}]}'),
(13, 'IMAGE', '{"type":"imageBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-290000000003","alt":"Besprechungstisch mit beschrifteten Zetteln in Spalten und Papierstapeln","caption":"Die Codierung an einem Nachmittag: fünf Spalten, eine je Hauptgrund, dazu ein Stapel für die strittigen Fälle","width":100}}'),
(14, 'DOCUMENT', '{"type":"documentBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-290000000002","fileName":"interviewleitfaden-fassung-2.pdf","size":168420,"caption":"Die zweite Fassung mit sieben Fragen, dazu die Einwilligung in einfacher Sprache und der Codierbogen"}}'),
(15, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Was hier steht, gilt für einen Treff in einem Stadtteil und für 24 Gespräche. Wer nie gekommen ist, steht in keiner Anwesenheitsliste und wurde deshalb auch nicht gefragt. Das ist die größte Lücke dieser Erhebung, und mit dem gewählten Zugang über die Listen ist sie nicht zu schließen."}]}')
) as v(order_index, type, content);

-- Projekt 30: 83 Bescheide zum Bildungspaket, 20 Ablehnungen ohne Fallbezug
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000030'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '180 days', now() - interval '115 days'
from (values
(0, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"type":"text","text":"Vom Beratungstisch in die Aktenanalyse"}]}'),
(1, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"In der Quartiersarbeit in Gröpelingen höre ich einen Satz besonders oft: Ich verstehe nicht, was in dem Brief steht. Gemeint ist häufig ein Bescheid zum Bildungs- und Teilhabepaket, mit dem eine Familie Nachhilfe, einen Vereinsbeitrag oder die Klassenfahrt bezahlt bekommt, oder eben nicht. Für dieses Forschungsprojekt habe ich mit der Sozialberatung eines freien Trägers im Stadtteil eine Vereinbarung geschlossen und 83 solcher Bescheide aus einem Schuljahr gelesen, mit einem festen Raster statt mit dem Bauchgefühl aus dem Beratungsgespräch."}]}'),
(2, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Wie das Material zustande kam"}]}'),
(3, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Grundlage sind die Beratungsakten des Schuljahres 2024/25, in denen ein Bescheid zum Bildungspaket lag: 96 Vorgänge. 13 fielen weg, weil die Einwilligung nicht zurückkam oder verweigert wurde; ausgewertet habe ich 83. Kopiert wurde nichts. Kodiert wurde in einem Nebenraum der Beratungsstelle, und aus dem Raum ging nur der ausgefüllte Bogen mit: ohne Namen, ohne Aktenzeichen, ohne Geburtsdatum."}]}'),
(4, 'LIST', '{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Alle Beratungsakten aus dem Schuljahr 2024/25 sichten, in denen ein Bescheid zum Bildungspaket liegt. Das waren 96 Vorgänge."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Einwilligung der Ratsuchenden schriftlich einholen, mit einem Blatt in einfacher Sprache. 13 kamen nicht zurück."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kodieren vor Ort, Merkmal für Merkmal, ohne den Bescheid mitzunehmen oder abzufotografieren."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"20 Bescheide doppelt kodieren lassen und die Bögen Zeile für Zeile abgleichen."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Die Begründungen an § 35 SGB X und an den Voraussetzungen des § 28 SGB II prüfen."}]}]}]}'),
(5, 'GALLERY', '{"type":"galleryBlock","attrs":{"items":[{"fileId":"d0d00022-0000-4000-8000-300000000001","alt":"Tisch mit ausgedruckten Kodierbögen, Textmarkern und einem aufgeklappten Laptop"},{"fileId":"d0d00022-0000-4000-8000-300000000002","alt":"Beratungsraum mit Stuhlkreis und einer Pinnwand voller Aushänge"},{"fileId":"d0d00022-0000-4000-8000-300000000003","alt":"Wartebereich mit Stühlen und einem Regal voller Merkblätter"}],"columns":3,"caption":"Links der Nebenraum, in dem kodiert wurde, in der Mitte der Beratungsraum, rechts der Wartebereich. Die Akten haben den Schrank in der Mitte nie verlassen."}}'),
(6, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Was die 83 Bescheide zeigen"}]}'),
(7, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Leistung nach § 28 SGB II"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Bescheide"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"davon ablehnend"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ablehnung mit tragfähiger Begründung"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Lernförderung (Absatz 5)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"27"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"19"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"6"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ausflüge und Klassenfahrten (Absatz 2)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"18"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"5"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"4"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Teilhabe am sozialen Leben (Absatz 7)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"14"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"6"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"2"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Persönlicher Schulbedarf (Absatz 3)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"12"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"3"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"3"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Mittagsverpflegung (Absatz 6)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"8"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"2"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"1"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Schülerbeförderung (Absatz 4)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"4"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"1"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"0"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Summe","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"83","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"36","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"16","marks":[{"type":"bold"}]}]}]}]}]}'),
(8, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Die vierte Spalte ist der eigentliche Befund. "},{"type":"text","text":"§ 35 SGB X","marks":[{"type":"link","attrs":{"href":"https://www.gesetze-im-internet.de/sgb_10/__35.html","target":"_blank","rel":"noopener noreferrer"}}]},{"type":"text","text":" verlangt, dass die Behörde die wesentlichen Gründe mitteilt, die sie zu ihrer Entscheidung bewogen haben. In 16 der 36 Ablehnungen steht so etwas. Bei den übrigen 20 nicht: 11 stützen sich darauf, die Versetzung sei nicht gefährdet, ein Kriterium, das mit dem Starke-Familien-Gesetz zum 1. August 2019 entfallen ist; die anderen 9 bestehen aus einem Textbaustein ohne einen einzigen Satz zum Fall. Angefochten wurden 14 der 36 Ablehnungen, und "},{"type":"text","text":"in 9 dieser 14 Fälle half die Behörde ganz oder teilweise ab","marks":[{"type":"bold"}]},{"type":"text","text":", sechsmal vollständig, dreimal in Teilen."}]}'),
(9, 'LIST', '{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Textbaustein statt Begründung: 9 Bescheide teilen mit, die Voraussetzungen lägen nicht vor, ohne zu sagen, welche."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Veraltetes Kriterium: 11 Ablehnungen zur Lernförderung verlangen eine gefährdete Versetzung. Seit 2019 genügt, dass die wesentlichen Lernziele erreichbar bleiben."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rechtsbehelfsbelehrung: bei 7 der 83 Bescheide fehlt sie oder ist falsch. Dann läuft nach § 66 Absatz 2 SGG ein Jahr statt eines Monats, und genau das war in zwei Fällen der einzige Grund, dass ein Widerspruch überhaupt noch ging."}]}]}]}'),
(10, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Woran das erste Raster scheiterte"}]}'),
(11, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Das erste Kodierraster hatte 9 Merkmale, drei davon als freies Textfeld. Bei der Doppelkodierung von 20 Bescheiden kamen wir auf ein Cohens Kappa von 0,52; strittig war vor allem, wann eine Begründung als fallbezogen gilt. Wir haben das Raster daraufhin auf 14 Merkmale mit festen Antwortvorgaben und je zwei Ankerbeispielen umgebaut und die bis dahin kodierten 31 Bescheide noch einmal von vorn kodiert. In der zweiten Runde lag Kappa bei 0,81. Die zwei Wochen, die das gekostet hat, standen im Zeitplan nicht drin."}]}'),
(12, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Ich habe den Brief dreimal gelesen und wusste danach immer noch nicht, was ich einreichen soll."}]},{"type":"paragraph","content":[{"type":"text","text":"Mutter von zwei Schulkindern, Beratungsgespräch im Februar 2025, mitgeschrieben mit ihrem Einverständnis","marks":[{"type":"italic"}]}]}]}'),
(13, 'DIVIDER', '{"type":"horizontalRule"}'),
(14, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Der überarbeitete Leitfaden liegt hier, damit andere Beratungsstellen das Raster nicht noch einmal bauen müssen. In der Beratungsstelle hängt seit März eine Kurzfassung an der Wand: erst die Rechtsbehelfsbelehrung prüfen, dann die Begründung, dann über den Inhalt reden. Von den sechs Widersprüchen, die seitdem eingelegt wurden, ist bisher keiner wegen Fristversäumnis zurückgewiesen worden."}]}'),
(15, 'DOCUMENT', '{"type":"documentBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-300000000004","fileName":"kodierleitfaden-bescheide.pdf","size":214000,"caption":"Kodierleitfaden mit den 14 Merkmalen, den Ankerbeispielen und dem Protokoll der beiden Reliabilitätsprüfungen"}}')
) as v(order_index, type, content);

-- Projekt 31: Erste Generation im Studium: 24 Tandems, 144 Treffen
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000031'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '80 days', now() - interval '25 days'
from (values
(0, 'TABLE_OF_CONTENTS', '{"type":"tableOfContents","attrs":{"entries":[{"text":"Ein Tandem für das erste Semester","index":0,"level":1},{"text":"Wie die Tandems zustande kamen","index":1,"level":2},{"text":"Was in den Verlaufsbögen steht","index":2,"level":2},{"text":"Was nicht funktioniert hat","index":3,"level":2}]}}'),
(1, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"type":"text","text":"Ein Tandem für das erste Semester"}]}'),
(2, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Wer als Erste oder Erster in der Familie studiert, hat zu Hause niemanden, den er zwischendurch etwas fragen kann. Das war der Anlass: Seit dem Wintersemester 2025/26 bringen wir Studienanfängerinnen und Studienanfänger ohne akademisches Elternhaus mit Studierenden aus höheren Semestern zusammen, je für ein Semester. "},{"type":"text","text":"24 Tandems in zwei Semestern, 144 protokollierte Treffen","marks":[{"type":"bold"}]},{"type":"text","text":". Ausgewertet haben wir keine Fälle, sondern Verläufe: Was ein Tandem gebracht hat, steht nicht in der Zahl der Treffen, sondern darin, wie es geendet ist."}]}'),
(3, 'IMAGE', '{"type":"imageBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-310000000000","alt":"Mehrere Personen sitzen um einen Tisch in einem Seminarraum und sprechen miteinander","caption":"Der Auftaktabend im Oktober 2025. An diesem Abend kamen 38 Anmeldungen aus dem ersten Semester zusammen, aber nur 29 Angebote aus höheren Semestern.","width":75}}'),
(4, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Wie die Tandems zustande kamen"}]}'),
(5, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Angekündigt haben wir den Auftakt über die Studiengangslisten, die Aushänge in den Lernräumen und zwei Erstsemesterveranstaltungen. Zusammengebracht haben wir aus 38 Anmeldungen und 29 Angeboten 24 Tandems. Zugeordnet wurde nach Studiengang, und das war der erste Fehler: 14 Anmeldungen aus Studiengängen ohne passendes Angebot blieben übrig, fünf Angebote ebenso, obwohl die Fragen am Anfang selten fachlich sind. In der Studienberatung wird dazu die Zahl genannt, dass von 100 Kindern ohne akademisches Elternhaus 27 ein Studium beginnen und aus Akademikerfamilien 79."}]}'),
(6, 'LIST', '{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ein Tandem ist auf ein Semester verabredet und endet mit einem Abschlussgespräch. Wer weitermachen will, verabredet das neu."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Wir ersetzen kein Fachtutorium. Wer in Mathematik hängt, geht ins Tutorium; unsere Aufgabe ist es, den Weg dorthin zu kennen."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nach jedem Treffen füllt das Tandem einen Verlaufsbogen aus: Datum, Dauer, worum es ging, was offen blieb. Zwei Zeilen, mehr nicht."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Die Bögen tragen eine Tandemnummer und keinen Namen. Die Zuordnung kennt nur die Person, die die Tandems bildet."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Wer aufhören will, sagt es einmal. Wir fragen einmal nach und danach nicht mehr; ein Abbruch wird nicht als Versagen protokolliert."}]}]}]}'),
(7, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Was in den Verlaufsbögen steht"}]}'),
(8, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Verlauf"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Tandems"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"protokollierte Treffen"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Durchgehend, mindestens acht Treffen"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"9"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"96"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Unregelmäßig, auf Zuruf"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"5"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"21"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Vorzeitig beendet, Frage geklärt"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"4"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"18"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Nach höchstens zwei Treffen abgebrochen"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"6"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"9"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Summe","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"24","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"144","marks":[{"type":"bold"}]}]}]}]}]}'),
(9, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Die letzte Zeile ist die unangenehme. Sechs Tandems endeten nach höchstens zwei Treffen, und in vier dieser sechs kam das Ende von der Seite der Mentorinnen und Mentoren. In allen vier hatten wir vorher nicht gefragt, wie viel Zeit im eigenen Semester überhaupt übrig ist. Die neun durchgehenden Tandems stehen für zwei Drittel aller Treffen; sie sind nicht die mit den größten Schwierigkeiten, sondern die, in denen früh ein fester Wochentag stand. In den 18 Abschlussgesprächen, die zustande kamen, wurde am häufigsten nicht ein fachliches Thema genannt, sondern die Prüfungsanmeldung: 11 von 18."}]}'),
(10, 'IMAGE', '{"type":"imageBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-310000000001","alt":"Auf einem Tisch liegen handschriftlich ausgefüllte Bögen in Stapeln, daneben ein Stift","caption":"Ein Bogen je Treffen, sortiert nach Tandemnummer. Namen stehen darauf nicht; die Zuordnungsliste liegt im verschlossenen Schrank des Fachschaftsraums.","width":100}}'),
(11, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Was nicht funktioniert hat"}]}'),
(12, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Der gemeinsame Termin im Semesterplan war ein Fehler. Wir hatten allen Tandems denselben Mittwochnachmittag vorgeschlagen, weil sich so ein Raum buchen ließ; in einem Stundenplan mit Laborterminen passt das selten. Seit Februar verabredet jedes Tandem den nächsten Termin am Ende des vorigen, und seitdem fallen deutlich weniger Treffen aus. Der zweite Fehler war die Zuordnung nach Studiengang: 14 Anmeldungen blieben ohne Gegenüber, weil in ihrem Studiengang niemand aus einem höheren Semester geantwortet hatte. Ab dem kommenden Durchgang ordnen wir nach der Frage zu, mit der jemand kommt, und nicht nach der Prüfungsordnung."}]}'),
(13, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Ich habe drei Wochen gebraucht, um zu fragen, was ein Modul überhaupt ist. Zu Hause konnte ich niemanden fragen, und im Seminar wollte ich nicht die sein, die das nicht weiß."}]},{"type":"paragraph","content":[{"type":"text","text":"Studentin im zweiten Semester, mit ihrem Einverständnis im Abschlussgespräch am 3. Juli 2026 notiert","marks":[{"type":"italic"}]}]}]}'),
(14, 'DOCUMENT', '{"type":"documentBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-310000000002","fileName":"leitfaden-erstgespraech.pdf","size":214000,"caption":"Der Leitfaden für das erste Tandemtreffen, sechs Seiten: die Fragen für den Anfang, die Grenze zum Fachtutorium und der Verlaufsbogen als Vorlage."}}'),
(15, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Der Leitfaden ist keine Handreichung aus der Hochschuldidaktik, sondern das, was wir uns in zwei Semestern gegenseitig erklärt haben. Wer so etwas in einem anderen Studiengang aufmachen will, kann ihn übernehmen; die Liste der Anlaufstellen muss dann getauscht werden. Im Oktober läuft der dritte Durchgang an, zum ersten Mal mit der Zentralen Studienberatung als fester Ansprechstelle und mit Anschluss an "},{"type":"text","text":"ArbeiterKind.de","marks":[{"type":"link","attrs":{"href":"https://www.arbeiterkind.de","target":"_blank","rel":"noopener noreferrer"}}]},{"type":"text","text":". Weitergezählt wird auch, sonst ist es beim nächsten Bericht wieder ein Eindruck statt einer Zahl."}]}')
) as v(order_index, type, content);

-- Projekt 32: 89 von 248 standen an der Tischtennisplatte, ohne zu spielen
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000032'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '450 days', now() - interval '370 days'
from (values
(0, 'TABLE_OF_CONTENTS', '{"type":"tableOfContents","attrs":{"entries":[{"text":"Drei Platten, sechs Wochen, 24 Stunden","index":0,"level":1},{"text":"Wie beobachtet wurde","index":1,"level":2},{"text":"Wer spielt, wer steht daneben","index":2,"level":2},{"text":"Was im ersten Bogen fehlte","index":3,"level":2}]}}'),
(1, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"type":"text","text":"Drei Platten, sechs Wochen, 24 Stunden"}]}'),
(2, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Im Grünzug am Sodenmattsee in Huchting stehen drei Tischtennisplatten aus Beton, keine hundert Meter voneinander entfernt. Wer im Quartier arbeitet, hört ständig, die Platten seien „gut angenommen“. Nachgezählt hatte das niemand. Für dieses Semesterprojekt haben wir an 16 Terminen ausgezählt, wer die Flächen tatsächlich benutzt, wie lange und wozu. Herausgekommen sind "},{"type":"text","text":"248 Personen","marks":[{"type":"bold"}]},{"type":"text","text":" und eine Verteilung zwischen Spielen und Danebenstehen, über die im Beirat länger gestritten wurde als über die Zahlen selbst."}]}'),
(3, 'VIDEO', '{"type":"videoBlock","attrs":{"provider":"youtube","videoId":"aqz-KE-bpKQ","width":50,"caption":"Zeitraffer eines Zeitfensters an Platte 1, ein Bild alle fünf Sekunden. Leer ist die Fläche selten, gespielt wird auf ihr trotzdem nur in Teilen der Zeit."}}'),
(4, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Wie beobachtet wurde"}]}'),
(5, 'LIST', '{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Feste Zeitfenster: werktags 15:00 bis 16:30 Uhr, samstags 11:00 bis 12:30 Uhr, damit die Termine vergleichbar bleiben"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Jede Platte einzeln, immer von derselben Position an der Wegkreuzung aus, ohne Ansprache der Anwesenden"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Notiert werden Ankunft, Weggang und ob jemand spielt oder nur da ist, dazu Temperatur und Wetterlage zu Beginn und am Ende des Zeitfensters"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Zwei Personen zählen parallel; weichen die Bögen um mehr als zwei Personen ab, fällt der Zeitraum aus der Auswertung"}]}]}]}'),
(6, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Von 18 Terminen sind 16 in die Auswertung gegangen, zusammen 24 Stunden. Die ersten beiden haben wir verworfen, weil es die Spalte "},{"type":"text","text":"Aufenthalt ohne Spiel","marks":[{"type":"italic"}]},{"type":"text","text":" damals noch nicht gab und die Bögen dadurch nicht zu den späteren passen. Der Abgleich zwischen den beiden Zählenden hat an drei Terminen je einen Zeitraum gekostet, meist zur vollen Stunde, wenn die Schule aus war."}]}'),
(7, 'DOCUMENT', '{"type":"documentBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-320000000002","fileName":"beobachtungsbogen-gruenzug.pdf","size":186420,"caption":"Beobachtungsbogen in der zweiten Fassung, ausgefüllt für Platte 2 am 14. November. Wer die Zählung nachbauen will, sollte mit dieser Fassung anfangen."}}'),
(8, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Wer spielt, wer steht daneben"}]}'),
(9, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Platte"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"mit Schläger"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"ohne Spiel"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"gesamt"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"1, am Spielplatz"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"48"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"38"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"86"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"2, am Weg zur Bushaltestelle"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"58"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"29"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"87"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"3, am Schulzaun"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"53"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"22"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"75"}]}]}]},{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Summe"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"159"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"89"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"248"}]}]}]}]}'),
(10, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"89 der 248 Personen hatten in der beobachteten Zeit nie einen Schläger in der Hand, gut ein Drittel. Sie saßen auf der Platte, lehnten am Rand oder warteten darauf, dass jemand aufhört. Am deutlichsten ist das an Platte 1 neben dem Spielplatz mit 38 von 86, am schwächsten an Platte 3 am Schulzaun mit 22 von 75. Die Verweildauer trennt die beiden Gruppen weniger scharf, als wir erwartet hatten: Wer spielte, blieb im Median 22 Minuten, wer nicht spielte, 14 Minuten, und 19 der 89 hielten sich länger als vierzig Minuten an der Platte auf. Zwischen den Zeitfenstern ist der Abstand klein, werktags nachmittags 179 Personen an 11 Terminen gegen 69 an 5 Samstagvormittagen, also 16 gegen 14 je Termin. Größer ist der Unterschied beim Wetter: "},{"type":"text","text":"an den 12 trockenen Terminen kamen 201 Personen zusammen, an den 4 nassen oder kalten 47","marks":[{"type":"highlight","attrs":{"color":"amber"}}]},{"type":"text","text":". Für die Frage, wie lange die Platten wirklich bespielt werden, zählt die Witterung damit mehr als die Uhrzeit. Genau die Gruppe ohne Schläger war in unserer ersten Zählweise unsichtbar."}]}'),
(11, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"type":"text","text":"Was im ersten Bogen fehlte"}]}'),
(12, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Der erste Bogen führte für jede Person zwei Spalten, Ankunft und Weggang, und aufgenommen wurde nur, wer einen Schläger in der Hand hatte. Wer daneben stand, auf der Platte saß oder zwei Meter weiter auf der Bank wartete, kam nicht vor. Aufgefallen ist uns das an einem Samstag, als sieben Jugendliche 40 Minuten am Ort blieben und im Bogen als Null erschienen. Seit dem dritten Termin gibt es die dritte Spalte. Den zweiten Schwachpunkt benennen wir lieber selbst: Trocken, nass oder kalt steht so im Bogen, wie wir es vor Ort eingeschätzt haben, gemessen haben wir allein die Temperatur. Für den 9. Dezember notierten beide Zählenden Nieselregen, in den Daten der nächstgelegenen Station steht für diesen Nachmittag keiner. Wir führen die Spalte trotzdem, weil ohne sie die vier schwachen Termine als Zufall dastünden, und würden sie beim nächsten Mal an eine Station binden."}]}'),
(13, 'GALLERY', '{"type":"galleryBlock","attrs":{"items":[{"fileId":"d0d00022-0000-4000-8000-320000000001","alt":"Betontischtennisplatte im Park, zwei Jugendliche spielen, drei weitere stehen daneben"},{"fileId":"d0d00022-0000-4000-8000-320000000003","alt":"Parkbank neben einer Betontischtennisplatte, auf der Bank sitzen mehrere Personen"}],"columns":2,"caption":"Links Platte 2 an einem Donnerstag um 15:20 Uhr, rechts die Bank zwei Meter daneben. Auf beiden Bildern hätte der erste Bogen nur die zwei mit Schläger gezählt."}}'),
(14, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Wir kommen sonst nicht ran. Wenn die Großen spielen, spielen die Großen, und wir gucken."}]},{"type":"paragraph","content":[{"type":"text","text":"Zwei Zwölfjährige an Platte 3, notiert am 23. November nach dem Ende des Zeitfensters","marks":[{"type":"italic"}]}]}]}'),
(15, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Im Februar standen die Zahlen im Beirat Huchting auf der Tagesordnung, beschlossen ist bis heute nichts. Vorgeschlagen haben wir zwei Dinge: eine Schlägerausleihe an der Platte am Spielplatz, die seit April über das Bürgerhaus läuft und bisher 63 Ausleihen zählt, und einen Wetterschutz über Platte 2, weil an den nassen und kalten Terminen je Termin ein knappes Drittel weniger Leute da war. Ob sich dadurch etwas an der Verteilung ändert, zeigt frühestens eine zweite Zählung im kommenden Sommer, mit demselben Bogen und denselben Zeitfenstern. Die ausgefüllten Bögen liegen beim "},{"type":"text","text":"Ortsamt Huchting","marks":[{"type":"link","attrs":{"href":"https://www.ortsamthuchting.bremen.de","target":"_blank","rel":"noopener noreferrer"}}]},{"type":"text","text":" und können dort eingesehen werden."}]}')
) as v(order_index, type, content);

