(0, 'TABLE_OF_CONTENTS', '{"type":"tableOfContents","attrs":{"entries":[{"text":"Hofkino in Gröpelingen: 502 Gäste an vier Abenden","index":0,"level":1},{"text":"Was am ersten Abend schiefging","index":1,"level":2},{"text":"Wer gekommen ist","index":2,"level":2},{"text":"Die Rechnung","index":3,"level":2}]}}'),
(1, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"text":"Hofkino in Gröpelingen: 502 Gäste an vier Abenden","type":"text"}]}'),
(2, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Ein Kino im Hinterhof braucht keine große Leinwand, aber es braucht eine Anfangszeit, die zur Jahreszeit passt. Fünf Abende waren für den Innenhof an der Seewenjestraße in Gröpelingen geplant, vier haben stattgefunden; der Termin am 19. Juli fiel wegen Dauerregen aus. Die Technik kam gegen Miete aus einem Verleih, den Hof stellte die Hausverwaltung; drei der acht Helfenden kamen aus dem Repair-Café. Hinterher haben wir alles nachgerechnet: Gäste, Ausgaben, Einnahmen.","type":"text"}]}'),
(3, 'IMAGE', '{"type":"imageBlock","attrs":{"alt":"Aufgespannte Leinwand vor einer Backsteinwand, davor leere Stuhlreihen in der Abenddämmerung","width":100,"fileId":"d0d00022-0000-4000-8000-330000000000","caption":"Aufbau vor dem dritten Abend. Die Leinwand hängt an der Brandwand, weil der Backstein zu dunkel war, um direkt darauf zu projizieren."}}'),
(4, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Was am ersten Abend schiefging","type":"text"}]}'),
(5, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Der Ablaufplan stammte aus einer Vorlage für Herbstveranstaltungen: Einlass 20:00 Uhr, Beginn 20:30 Uhr. Am 14. Juni stand alles pünktlich, nur war es noch taghell. Das Bild wurde ","type":"text"},{"text":"erst gegen 22:15 Uhr","type":"text","marks":[{"type":"bold"}]},{"text":" brauchbar. Bis dahin waren die meisten Familien mit kleinen Kindern gegangen: Von 78 gezählten Gästen saßen zum Filmstart noch 31 im Hof. Die Sonnenuntergangszeit stand in keiner unserer Checklisten, obwohl sie die wichtigste Zahl des ganzen Projekts war.","type":"text"}]}'),
(6, 'LIST', '{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Beginn ab dem zweiten Abend erst um 22:15 Uhr, davor ab 20:30 Uhr Kurzfilme für Kinder im abgedunkelten Nachbarschaftstreff","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Zwei Zählende statt einer, weil der Hof zwei Zugänge hat und die erste Strichliste nur den von der Straße erfasste","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Untertitel bei allen Filmen, am 28. Juni zusätzlich auf Türkisch","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ton über zwei kleine Lautsprecher an den Stuhlreihen statt einer lauten Box hinten, Schluss spätestens 23:45 Uhr, so stand es in der Zusage an die Hausverwaltung","type":"text"}]}]}]}'),
(7, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Wer gekommen ist","type":"text"}]}'),
(8, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Abend","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Datum","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Programm","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Gäste","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"1","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"14. Juni","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Familienfilm, Beginn noch bei Tageslicht","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"78","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"28. Juni","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Familienfilm mit türkischen Untertiteln","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"141","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"3","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"conten