(13, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Auf 502 Gäste gerechnet kostete ein Besuch 2,86 Euro an Ausgaben, gedeckt waren davon 2,72 Euro. Die Lücke von knapp 15 Cent je Gast ergibt den Fehlbetrag von 75 Euro, den der Förderverein des Nachbarschaftstreffs aus der Kasse genommen hat. Teuer war nicht die Technik, sondern die Vorführrechte: 640 Euro für vier Filme, knapp 45 Prozent aller Ausgaben. Wer das nachbaut, klärt die Rechte vor der Filmauswahl und nicht danach. Der Zuschuss kam aus dem Quartiersfonds von ","type":"text"},{"text":"Wohnen in Nachbarschaften","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer","href":"https://www.wohnen-in-nachbarschaften.de/","target":"_blank"}}]},{"text":", beantragt im März, bewilligt im Mai.","type":"text"}]}'),
(14, 'DOCUMENT', '{"type":"documentBlock","attrs":{"size":148320,"caption":"Abrechnung, wie sie beim Quartiersfonds eingereicht wurde, mit Belegliste und der Erklärung zum Fehlbetrag","fileId":"d0d00022-0000-4000-8000-330000000002","fileName":"hofkino-abrechnung.pdf"}}'),
(15, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Dass der Fehlbetrag in der Tabelle steht und nicht in einer Fußnote, ist die halbe Leistung. Die 640 Euro für die Rechte gehören aber in die Planung vor der Filmauswahl, sonst plant ihr das Programm gegen das Budget.","type":"text"}]},{"type":"paragraph","content":[{"text":"Rückmeldung aus dem Modul Eventmanagement, Zwischenpräsentation am 5. August","type":"text","marks":[{"type":"italic"}]}]}]}')
) as v(order_index, type, content);

-- Projekt 34: Die Frage nach dem eigenen Becher an vier Bäckereitheken
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000034'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '295 days', now() - interval '235 days'
from (values
(0, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"text":"Die Frage nach dem eigenen Becher an vier Bäckereitheken","type":"text"}]}'),
(1, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"An vier Theken einer Bremer Bäckereikette haben wir zwei Wochen lang eine einzige Änderung ausprobiert: Beim Aufnehmen der Bestellung fragt die Bedienung, ob ein eigener Becher dabei ist. Gemessen wurde an 2.869 Heißgetränkebons aus dem Kassenexport, nicht am Eindruck vom Tresen. Womit wir vergleichen, mussten wir allerdings erst selbst bestimmen, denn die 14,2 Prozent Mehrwegquote aus dem Nachhaltigkeitsflyer der Kette halten der Prüfung nicht stand.","type":"text"}]}'),
(2, 'IMAGE', '{"type":"imageBlock","attrs":{"alt":"Kaffeetheke mit Siebträgermaschine, davor mehrere wartende Personen","width":100,"fileId":"d0d00022-0000-4000-8000-340000000000","caption":"Filiale Überseestadt, Dienstag kurz vor neun. In dieser halben Stunde laufen etwa ein Fünftel der Tagesbons durch."}}'),
(3, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Die Bezugsgröße für den Vergleich","type":"text"}]}'),
(4, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Der Monatsbericht bildet die Quote aus allen Bons mit dem Artikel 4711 (Mehrweg), geteilt durch alle Heißgetränkebons. Artikel 4711 wird aber für zwei verschiedene Vorgänge gebucht: für den Rabatt, wenn jemand einen eigenen Becher mitbringt, und für den Verkauf, wenn jemand einen leeren Mehrwegbecher kauft. Der Becherverkauf steht damit im Zähler, obwohl er genau das Gegenteil misst. In den zwölf Monaten vor dem Test zählt der Bericht 4.892 solche Buchungen auf 34.450 Heißgetränkebons. 2.687 davon sind Verkäufe. Es bleiben ","type":"text"},{"text":"2.205 mitgebrachte Becher und damit 6,4 Prozent","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}'),
(5, 'CODE', '{"type":"codeBlock","attrs":{"language":"sql"},"content":[{"text":"-- Zähler des Monatsberichts: jede Buchung auf Artikel 4711\nselect count(distinct bon_id) as bons_bericht\nfrom bonzeile\nwhere artikel_nr = 4711;\n\n-- korrigiert: nur die Rabattzeile, nicht der Becherverkauf\nselect count(distinct bon_id) as bons_mitgebracht\nfrom bonzeile\nwhere artikel_nr = 4711\n  and menge < 0;  -- Rabatt wird negativ gebucht, der Verkauf positiv","type":"text"}]}'),
(6, 'DOCUMENT', '{"type":"documentBlock","attrs":{"size":214800,"fileId":"d0d00022-0000-4000-8000-340000000003","caption":"Prüfprotokoll zum Kassenexport: die zwölf Monatssummen, die korrigierte Abfrage und die Abweichung je Monat. Der kleinste Fehler liegt im Januar bei 5,9 Punkten, der größte im August bei 9,4.","fileName":"kassenexport-pruefprotokoll.pdf"}}'),
(7, 'DIVIDER', '{"type":"horizontalRule"}'),
(8, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Der Aufbau im Feld","type":"text"}]}'),
(9, 'LIST', '{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Variante A ist der Ist-Zustand: ein Schild an der Theke, 20 Cent Rabatt mit eigenem Becher. Es hängt dort seit 2023.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Variante B ist eine Frage. Beim Aufnehmen der Bestellung fragt die Bedienung: „Haben Sie einen eigenen Becher dabei?“ Das Schild bleibt hängen, es kommt also nichts weg, sondern eines dazu.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Vier Filialen (Überseestadt, Neustadtswall, Vegesack, Findorff), zwei Wochen, jede Filiale fährt jede Variante eine Woche. Getauscht wird zum Wochenwechsel, damit Standort und Kundschaft nicht mit der Variante zusammenfallen.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Gezählt wird aus dem Kassenexport, nicht von Hand: alle Heißgetränkebons zwischen 6:30 und 18:00 Uhr, Rabattzeilen über die negative Menge erkannt.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Parallel läuft eine Strichliste zur Umsetzungstreue: Bei jeder zwanzigsten Bestellung notiert eine Beobachterin, ob wirklich gefragt wurde.","type":"text"}]}]}]}'),
(10, 'GALLERY', '{"type":"galleryBlock","attrs":{"items":[{"alt":"Blick über eine Cafétheke in den Gastraum, neben der Kasse steht ein kleiner Aufsteller","fileId":"d0d00022-0000-4000-8000-340000000001"},{"alt":"Verkaufstheke einer Bäckerei, die Kasse steht am vorderen Ende der schrägen Auslage, dahinter Bleche mit Brötchen","fileId":"d0d00022-0000-4000-8000-340000000002"}],"caption":"Links Überseestadt, rechts Findorff. In Findorff steht die Kasse vor der Auslage und die Bedienung sieht die Leute kommen; dort wurde am zuverlässigsten gefragt, und dort liegt die Quote schon ohne die Frage am höchsten.","columns":2}}'),
(11, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Die erste Fassung war ein Vergleich zwischen zwei Filialen, Überseestadt gegen Vegesack, eine Woche lang. Nach drei Tagen war klar, dass daraus nichts wird: In der Überseestadt kaufen Büroleute jeden Morgen dasselbe, in Vegesack ist es Laufkundschaft vom Bahnhof, und die Tagesquoten schwankten schon ohne jeden Eingriff zwischen 3 und 10 Prozent, also weit stärker als der Unterschied, den wir messen wollten. Wir haben umgestellt, sodass jede Filiale beide Varianten fährt und ihr eigener Vergleich ist. Der zweite Fehler steckte in der Umsetzung: An den ersten drei Tagen von Variante B ergab die Strichliste eine Fragequote von ","type":"text"},{"text":"61 Prozent","type":"text","marks":[{"type":"bold"}]},{"text":". Die Frühschicht hatte die Absprache nicht mitbekommen. Diese drei Tage sind aus der Auswertung heraus, die Testwoche wurde hinten angehängt; in den verbleibenden Tagen lag die Fragequote bei 93 Prozent.","type":"text"}]}'),
(12, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Was herauskam","type":"text"}]}'),
(13, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Filiale","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Bons Variante A","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"davon eigener Becher","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Bons Variante B","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"davon eigener Becher","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Überseestadt","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"462","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"31 (6,7 %)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"448","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"62 (13,8 %)","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Neustadtswall","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"388","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"22 (5,7 %)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"401","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"51 (12,7 %)","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Vegesack","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"311","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"18 (5,8 %)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"296","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"34 (11,5 %)","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Findorff","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"274","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"21 (7,7 %)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"289","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"39 (13,5 %)","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Summe","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"1.435","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"92 (6,4 %)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"1.434","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"186 (13,0 %)","type":"text"}]}]}]}]}'),
(14, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Variante A liegt bei 6,4 Prozent und trifft damit genau den Wert der zwölf Monate davor. Das Schild bewegt nichts mehr, es ist Teil der Wand geworden. Mit der Frage kommen 13,0 Prozent heraus, also 94 Bons mehr. An dieser Stelle hört die Rechnung in den meisten Präsentationen auf. Sie geht aber weiter: Jeder zusätzliche Mehrwegbon kostet 20 Cent Rabatt, macht 18,80 Euro. Gespart wird der Einwegbecher mit Deckel, den der Betrieb für 11 Cent einkauft, macht 10,34 Euro. Über zwei Wochen und vier Filialen bleibt ","type":"text"},{"text":"ein Minus von 8,46 Euro","type":"text","marks":[{"type":"bold"}]},{"text":". Gerechnet wird dabei die Differenz und nicht der Bestand: Die 92 Becher, die auch ohne Frage mitgebracht worden wären, kosten den Rabatt so oder so. Das Vorzeichen dreht sich erst, wenn ein Einwegbecher den Betrieb mehr als 20 Cent kostet, etwa durch eine kommunale Verpackungssteuer. Wer die Maßnahme trotzdem will, sollte sie deshalb nicht mit dem Deckungsbeitrag begründen.","type":"text"}]}'),
(15, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Fragen kostet nichts, aber jemand muss es der Frühschicht sagen. Nach der zweiten Woche haben wir es wieder gelassen, das Schild hängt ja.","type":"text"}]},{"type":"paragraph","content":[{"text":"Filialleitung Vegesack im Abschlussgespräch am 3. Juli 2025","type":"text","marks":[{"type":"italic"}]}]}]}')
) as v(order_index, type, content);

-- Projekt 35: Nachkalkulation von 96 Aufträgen einer Tischlerei
insert into block (id, project_id, type, order_index, content, schema_version, created_at, updated_at)
select gen_random_uuid(), 'd0d00021-0000-4000-8000-000000000035'::uuid, v.type, v.order_index, v.content::jsonb, 3,
       now() - interval '440 days', now() - interval '360 days'
from (values
(0, 'TABLE_OF_CONTENTS', '{"type":"tableOfContents","attrs":{"entries":[{"text":"Was ein Auftrag kosten sollte","index":0,"level":1},{"text":"Wie ich gerechnet habe","index":1,"level":2},{"text":"Was die Auswertung zeigt","index":2,"level":2},{"text":"Woran die erste Fassung gescheitert ist","index":3,"level":2}]}}'),
(1, 'HEADING', '{"type":"heading","attrs":{"level":1,"textAlign":null},"content":[{"text":"Was ein Auftrag kosten sollte","type":"text"}]}'),
(2, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"In der Vorkalkulation steht ein Betrag, der Kunde bekommt ihn als Angebot, und danach sieht selten jemand nach, ob er gestimmt hat. Für diese Arbeit habe ich den internen Datenbestand einer Tischlerei in Bremen-Woltmershausen ausgewertet: ","type":"text"},{"text":"96 Aufträge","type":"text","marks":[{"type":"bold"}]},{"text":", abgeschlossen zwischen Januar 2021 und Dezember 2023, jeder mit Vorkalkulation, Zeiterfassung und Schlussrechnung. Bei 37 Aufträgen liegen die Ist-Kosten im Rahmen von fünf Prozent um den kalkulierten Betrag. Der Rest ist der interessante Teil.","type":"text"}]}'),
(3, 'IMAGE', '{"type":"imageBlock","attrs":{"alt":"Auftragsmappen mit Angebotsausdrucken und ein Laptop mit Tabellenblatt auf einem Büroschreibtisch","width":75,"fileId":"d0d00022-0000-4000-8000-350000000001","caption":"Je Auftrag ein Tabellenblatt. Auf den Mappen steht die Belegnummer, aus der jeder Ist-Wert stammt, sonst ist eine Abweichung später nicht mehr zu belegen."}}'),
(4, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Wie ich gerechnet habe","type":"text"}]}'),
(5, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Die Ist-Kosten bilde ich aus drei Quellen des Betriebs: den erfassten Stunden aus der Zeiterfassung, den Materialentnahmen aus der Lagerbuchung und den Fremdleistungen aus den Eingangsrechnungen. Die Vorkalkulation kommt unverändert aus dem Angebotsprogramm, so wie sie am Tag der Angebotsabgabe gespeichert wurde. Im Rahmen heißt, dass die Ist-Kosten um höchstens fünf Prozent vom kalkulierten Betrag abweichen. Nachträge, die der Kunde schriftlich beauftragt hat, rechne ich der Vorkalkulation zu, sonst misst man die Änderungswünsche und nicht die Kalkulation.","type":"text"}]}'),
(6, 'LIST', '{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Auftrag aus der Betriebssoftware ziehen und Angebotssumme, Vorkalkulation und Schlussrechnung nebeneinanderlegen","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Die erfassten Stunden aus der Zeiterfassung übernehmen, getrennt nach Werkstatt und Montage, in vollen Minuten und ohne Zwischenrundung","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Materialentnahmen aus der Lagerbuchung und Fremdleistungen aus den Eingangsrechnungen dem Auftrag zuordnen","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ist-Kosten mit dem betrieblichen Stundensatz von 68 Euro bilden und der Vorkalkulation gegenüberstellen","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bei einer Abweichung über fünf Prozent den Auftragsordner durchsehen, ob ein schriftlicher Nachtrag vorliegt, und den Fund im Blatt vermerken","type":"text"}]}]}]}'),
(7, 'FORMULA', '{"type":"mathBlock","attrs":{"latex":"\\mathrm{Abw} = \\frac{K_{\\text{ist}} - K_{\\text{plan}}}{K_{\\text{plan}}} \\cdot 100\\,\\%, \\qquad \\left| \\mathrm{Abw} \\right| \\leq 5 \\Rightarrow \\text{im Rahmen}"}}'),
(8, 'DOCUMENT', '{"type":"documentBlock","attrs":{"fileId":"d0d00022-0000-4000-8000-350000000003","fileName":"kalkulationsschema-tischlerei.pdf","size":486320,"caption":"Das Kalkulationsschema des Betriebs mit den Zuschlagssätzen, dazu die Liste der Aufträge, die ausgeschlossen wurden, und der Grund je Fall."}}'),
(9, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Was die Auswertung zeigt","type":"text"}]}'),
(10, 'TABLE', '{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Auftragsart","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Aufträge","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"unter Vorkalkulation","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"im Rahmen (5 Prozent)","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"über Vorkalkulation","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Innenausbau","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"31","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"6","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"11","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"14","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Möbel als Einzelanfertigung","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"24","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"3","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"7","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"14","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Türen und Fenster","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"18","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"5","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"8","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"5","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Reparatur und Service","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"15","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"4","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"9","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Ladenbau","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"8","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"1","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"2","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"5","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"Summe","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"96","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"19","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"37","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"text":"40","type":"text","marks":[{"type":"bold"}]}]}]}]}]}'),
(11, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Reparatur und Service ist der verlässlichste Bereich: 9 von 15 Aufträgen liegen im Rahmen, und die vier Aufträge unter der Vorkalkulation sind Fälle, in denen die angesetzte zweite Anfahrt gar nicht nötig war. Der Ladenbau ist der Ausreißer, ","type":"text"},{"text":"5 von 8 Aufträgen liegen über der Vorkalkulation, im Mittel um 19 Prozent","type":"text","marks":[{"type":"highlight","attrs":{"color":"amber"}}]},{"text":", und der Grund steht jedes Mal in der Zeiterfassung: kalkuliert sind zwei Monteure für einen Tag, gebraucht wurden zwei Monteure für anderthalb. Das Material trägt daran wenig Schuld, es weicht über alle 96 Aufträge um durchschnittlich 3 Prozent ab. Beim Stundensatz musste ich dem Betrieb widersprechen: er rechnet mit 68 Euro, in denen die Verwaltung nicht steckt, während in die Bewertung unfertiger Leistungen nach ","type":"text"},{"text":"§ 255 Abs. 2 HGB","type":"text","marks":[{"type":"link","attrs":{"href":"https://www.gesetze-im-internet.de/hgb/__255.html","target":"_blank","rel":"noopener noreferrer"}}]},{"text":" angemessene Teile der Verwaltungsgemeinkosten eingehen dürfen. Mit dem Satz aus der Bilanzbewertung, 74 Euro, kippen weitere sieben Aufträge über die Schwelle.","type":"text"}]}'),
(12, 'GALLERY', '{"type":"galleryBlock","attrs":{"items":[{"alt":"Werkstatt mit Plattenzuschnitt, an der Wand eine Tafel mit Auftragskarten","fileId":"d0d00022-0000-4000-8000-350000000002"},{"alt":"Vier Personen an einem Besprechungstisch, vor ihnen Ausdrucke mit markierten Zahlen","fileId":"d0d00022-0000-4000-8000-350000000004"}],"caption":"Links die Werkstatt mit der Auftragstafel, an der die Stunden geschrieben werden. Rechts die Besprechung mit der Betriebsleitung; die Schwelle von fünf Prozent habe ich danach festgelegt.","columns":2}}'),
(13, 'HEADING', '{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Woran die erste Fassung gescheitert ist","type":"text"}]}'),
(14, 'TEXT', '{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Der erste Auszug hatte 118 Aufträge. 22 musste ich streichen, weil die Zeiterfassung darin lückenhaft ist: bis Mai 2021 haben zwei Monteure ihre Stunden auf Zetteln notiert, die nicht mehr auffindbar sind. Übrig blieben die 96 Aufträge der Tabelle. Der zweite Fehler war die Schwelle. Ich habe zunächst jede Differenz gezählt, auch die von zwei Euro, und stand bei 91 abweichenden Aufträgen. Erst mit den fünf Prozent bleiben 59 übrig, 19 unter und 40 über der Vorkalkulation, und erst die sind ein Befund.","type":"text"}]}'),
(15, 'QUOTE', '{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Die Arbeit belegt vor allem eines: Die Kalkulation scheitert nicht am Materialpreis, sondern an den Stunden, die unterwegs niemand aufschreibt.","type":"text"}]},{"type":"paragraph","content":[{"text":"Aus dem Zweitgutachten, Modul Buchführung und Bilanzierung","type":"text","marks":[{"type":"italic"}]}]}]}')
) as v(order_index, type, content);

