-- Top-10: die Liste wird von drei auf zehn Plaetze aufgefuellt. Nominiert
-- wird eine Stufe und kein Platz (NominationTier seit Contract v68); den
-- Platz vergibt erst die Administration beim Aufnehmen. Nur
-- veroeffentlichte Projekte: ein Eintrag an einem unveroeffentlichten
-- Beitrag belegte einen Platz, den niemand sieht.
insert into top10_nomination (
	id, project_id, nominated_by, proposed_tier, proposed_position,
	status, decided_by, decided_at, created_at
)
select v.id::uuid, v.project_id::uuid, n.id, v.tier, v.position::integer,
       v.status, d.id,
       case when v.decided_days is not null
            then now() - (v.decided_days || ' days')::interval end,
       now() - (v.days || ' days')::interval
from (values
	('d0d00027-0000-4000-8000-000000000100', 'd0d00021-0000-4000-8000-000000000011', 'claudia.vogt@demo.invalid', 'TOP_5', null, 'ACCEPTED', 'dev-admin@dev.invalid', '138', 146),
	('d0d00027-0000-4000-8000-000000000101', 'd0d00021-0000-4000-8000-000000000012', 'dev-redakteur@dev.invalid', 'TOP_5', null, 'ACCEPTED', 'dev-admin@dev.invalid', '258', 266),
	('d0d00027-0000-4000-8000-000000000102', 'd0d00021-0000-4000-8000-000000000014', 'dev-redakteur@dev.invalid', 'TOP_10', null, 'ACCEPTED', 'dev-admin@dev.invalid', '378', 386),
	('d0d00027-0000-4000-8000-000000000103', 'd0d00021-0000-4000-8000-000000000015', 'claudia.vogt@demo.invalid', 'TOP_10', null, 'ACCEPTED', 'dev-admin@dev.invalid', '128', 136),
	('d0d00027-0000-4000-8000-000000000104', 'd0d00021-0000-4000-8000-000000000016', 'dev-redakteur@dev.invalid', 'TOP_10', null, 'ACCEPTED', 'dev-admin@dev.invalid', '248', 256),
	('d0d00027-0000-4000-8000-000000000105', 'd0d00021-0000-4000-8000-000000000017', 'claudia.vogt@demo.invalid', 'TOP_10', null, 'ACCEPTED', 'dev-admin@dev.invalid', '58', 66),
	('d0d00027-0000-4000-8000-000000000106', 'd0d00021-0000-4000-8000-000000000019', 'claudia.vogt@demo.invalid', 'TOP_10', null, 'ACCEPTED', 'dev-admin@dev.invalid', '268', 276),
	('d0d00027-0000-4000-8000-000000000200', 'd0d00021-0000-4000-8000-000000000020', 'claudia.vogt@demo.invalid', 'TOP_10', null, 'PENDING', null, null, 109),
	('d0d00027-0000-4000-8000-000000000201', 'd0d00021-0000-4000-8000-000000000022', 'claudia.vogt@demo.invalid', 'TOP_10', null, 'REJECTED', 'dev-admin@dev.invalid', '417', 424),
	('d0d00027-0000-4000-8000-000000000202', 'd0d00021-0000-4000-8000-000000000023', 'dev-redakteur@dev.invalid', 'TOP_10', null, 'WITHDRAWN', null, null, 204),
