	('d0d00027-0000-4000-8000-000000000204', 'd0d00021-0000-4000-8000-000000000025', 'dev-redakteur@dev.invalid', 'TOP_10', null, 'REJECTED', 'dev-admin@dev.invalid', '97', 104)
) as v(id, project_id, nominator_email, tier, position, status,
       decider_email, decided_days, days)
join app_user n on n.email = v.nominator_email
left join app_user d on d.email = v.decider_email;

-- Die Plaetze werden NICHT fest vergeben, sondern die freien gesucht.
--
-- Grund: top10_entry ist nur ueber project_id eindeutig, nicht ueber
-- position. Wer hier 4 bis 10 fest einsetzt, erzeugt eine Dublette,
-- sobald jemand ueber die Administrationsseite selbst einen Beitrag
-- aufgenommen hat. Genau das ist am 31.08.2026 passiert, nachzulesen in
-- top10_audit_entry: drei Beitraege von Hand auf 4, 5 und 6 gesetzt,
-- waehrend dieses Skript entstand. Ein Demoskript darf so eine Eingabe
-- weder ueberschreiben noch daran scheitern.
--
-- Passen weniger Beitraege in die Liste als vorgesehen, entsteht eine
-- kuerzere Liste. Die Gegenprobe am Ende meldet, wie viele es wurden.
with frei as (
	select g.pos, row_number() over (order by g.pos) as rn
	from generate_series(1, 10) as g(pos)
	where not exists (select 1 from top10_entry e where e.position = g.pos)
), anwaerter as (
	select v.id, v.project_id, v.days, row_number() over (order by v.rang) as rn
	from (values
	('d0d00026-0000-4000-8000-000000000004', 'd0d00021-0000-4000-8000-000000000011', 0, 138),
	('d0d00026-0000-4000-8000-000000000005', 'd0d00021-0000-4000-8000-000000000012', 1, 258),
	('d0d00026-0000-4000-8000-000000000006', 'd0d00021-0000-4000-8000-000000000014', 2, 378),
	('d0d00026-0000-4000-8000-000000000007', 'd0d00021-0000-4000-8000-000000000015', 3, 128),
	('d0d00026-0000-4000-8000-000000000008', 'd0d00021-0000-4000-8000-000000000016', 4, 248),
	('d0d00026-0000-4000-8000-000000000009', 'd0d00021-0000-4000-8000-000000000017', 5, 58),
	('d0d00026-0000-4000-8000-000000000010', 'd0d00021-0000-4000-8000-000000000019', 6, 268)
	) as v(id, project_id, rang, days)
)
insert into top10_entry (id, project_id, position, added_at)
select a.id::uuid, a.project_id::uuid, f.pos,
       now() - (a.days || ' days')::interval
from anwaerter a join frei f on f.rn = a.rn;

-- Pruefspur der Top-10. Sie haengt nur lose am Projekt
-- (on delete set null) und ueberlebt dessen Loeschung bewusst.
--
-- Die Platznummer wird aus top10_entry gelesen und nicht noch einmal
-- ausgerechnet: sonst behauptete die Spur einen Platz, den der Eintrag
-- gar nicht bekommen hat.
insert into top10_audit_entry (
	id, timestamp, admin_id, project_id, action, previous_position, new_position
)
select overlay(e.id::text placing 'a' from 8 for 1)::uuid,
       e.added_at, a.id, e.project_id, 'ADDED', null, e.position
from top10_entry e
cross join (select id from app_user where email = 'dev-admin@dev.invalid') as a
where e.id::text like 'd0d00026-%';

commit;
ENDE_SQL_DREISSIG

sql -c "
select 'Projekte'    as bestand, count(*) from project     where id::text like 'd0d00021-%'
union all select 'Bloecke',      count(*) from block       where project_id::text like 'd0d00021-%'
union all select 'Dateizeilen',  count(*) from stored_file where id::text like 'd0d00022-%'
union all select 'Kommentare',   count(*) from comment     where id::text like 'd0d00024-%'
union all select 'Reaktionen',   count(*) from reaction    where id::text like 'd0d00025-%'
union all select 'Top-10',       count(*) from top10_entry where id::text like 'd0d00026-%';"
echo

# -------------------------------------------------------------------
# 2) Die Bytes zu den Dateizeilen.
#
#    PostgreSQL kann kein HTTP: die Zeilen entstehen oben im SQL, die
#    Bytes koennen nur von aussen kommen. Ohne sie antwortet
#    GET /api/files/{id} mit 500 und Titelbild, Galerie, Audio und
