gesamt=$(printf '%s\n' "$MANIFEST" | grep -c '|' || true)

STAGE="$(mktemp -d)"
trap 'rm -rf "$STAGE"' EXIT

quelle_datei() {   # $1 art  -> URL fuer alles ausser Bildern
	case "$1" in
		audio) echo "$OGG" ;;
		video) echo "$MP4" ;;
		# Drei Quellen im Wechsel, damit nicht dreissigmal dieselbe
		# Datei im Speicher liegt und alle Dokumente gleich gross sind.
		pdf)
			case $(( pdfzaehler % 3 )) in
				0) echo "$PDF_A" ;;
				1) echo "$PDF_B" ;;
				*) echo "$PDF_C" ;;
			esac ;;
	esac
}

# --fail laesst curl bei 4xx/5xx mit Exitcode abbrechen, statt die
# Fehlerseite als Datei abzulegen. Ohne das landete ein HTML-Text im
# Objektspeicher und das Portal lieferte ihn als "image/jpeg" aus. Der
# User-Agent ist fuer Wikimedia noetig, das anonyme Abrufe ohne Kennung
# abweist.
hole() {   # $1 Ziel, $2 URL
	curl -sS -L --fail --max-time 90 -A "$UA" -o "$1" "$2" 2>/dev/null
}

# Wie oft die graue Ersatzflaeche greifen musste. Wird am Ende gemeldet:
# ein halb bebilderter Bestand darf nicht wie ein vollstaendiger aussehen.
ersatzbilder=0

# Wikimedia drosselt auch die statische Auslieferung: bei mehreren
# Abrufen in kurzer Folge kommt 429. Deshalb hier ohne --fail, damit der
# Statuscode lesbar ist, und ein zweiter Versuch nach kurzer Pause.
hole_cdn() {   # $1 Ziel, $2 URL
	local code
	code=$(curl -sS -L --max-time 90 -A "$UA" -o "$1" -w '%{http_code}' "$2" 2>/dev/null || echo 000)
	[ "$code" = "200" ] && return 0
	if [ "$code" = "429" ]; then
		sleep 6
		code=$(curl -sS -L --max-time 90 -A "$UA" -o "$1" -w '%{http_code}' "$2" 2>/dev/null || echo 000)
		[ "$code" = "200" ] && return 0
	fi
	# Ohne --fail hat curl die Fehlerseite in die Datei geschrieben. Sie
	# muss weg, sonst laege HTML im Objektspeicher, falls eine spaetere
	# Ebene ebenfalls scheitert und die Signaturpruefung sie uebersaehe.
	rm -f "$1"
	return 1
}

# Ein Bild besorgen, ueber mehrere Ebenen.
#
# Die Reihenfolge verteilt bewusst die Last auf zwei Dienste, statt einen
# zu ueberfahren:
#
#   1. loremflickr, thematisch nach Stichwort. Kennt etwa zwei Drittel der
#      hier benutzten Stichworte; die uebrigen beantwortet es mit 500.
#   2. Die feste Adresse auf upload.wikimedia.org, die p30/bilder.py vorab
#      aufgeloest hat. Sie faengt genau das Drittel auf, das loremflickr
#      nicht kennt, und wird deshalb selten genug abgerufen, um nicht in
#      die Drosselung zu laufen.
#   3. loremflickr mit einem allgemeinen Stichwort.
#   4. picsum.photos, falls es wieder laeuft (am 31.08.2026 lag es ueber
#      Stunden auf 503 und 522).
#   5. Eine graue Flaeche. Sie wird gezaehlt und am Ende gemeldet, damit
#      niemand einen halb bebilderten Bestand fuer vollstaendig haelt.
lade_bild() {   # $1 ziel, $2 stichwort, $3 lock, $4 breite, $5 hoehe, $6 seed, $7 url
	local ziel="$1" stich="$2" lock="$3" breite="$4" hoehe="$5" seed="$6" url="$7"

	if hole "$ziel" "https://loremflickr.com/$breite/$hoehe/$stich?lock=$lock"; then return 0; fi
	if [ -n "$url" ] && hole_cdn "$ziel" "$url"; then return 0; fi
	if hole "$ziel" "https://loremflickr.com/$breite/$hoehe/university,campus?lock=$lock"; then return 0; fi
	if hole "$ziel" "https://picsum.photos/seed/$seed/$breite/$hoehe.jpg"; then return 0; fi
	if hole "$ziel" "https://placehold.co/${breite}x${hoehe}/jpeg"; then
		ersatzbilder=$((ersatzbilder + 1))
		return 0
	fi
	return 1
}

count=0
pdfzaehler=0
while IFS='|' read -r fid pid art seed stich lock breite hoehe url; do
	[ -z "${fid:-}" ] && continue
	ziel="$STAGE/projects/$pid/$fid"
	mkdir -p "$(dirname "$ziel")"
	if [ "$art" = "bild" ]; then
		if ! lade_bild "$ziel" "$stich" "$lock" "$breite" "$hoehe" "$seed" "$url"; then
			abbruch "kein Bild fuer '$stich' zu bekommen ($fid).
         Alle fuenf Ebenen haben versagt. Besteht eine Internetverbindung?"
		fi
	else
		url=$(quelle_datei "$art")
		pdfzaehler=$((pdfzaehler + 1))
		if ! hole "$ziel" "$url"; then
			abbruch "$url liess sich nicht laden ($fid)."
		fi
	fi
	count=$((count + 1))
	printf '\r  %3d von %s geladen' "$count" "$gesamt"
done <<< "$MANIFEST"
echo

# Kein stilles Durchwinken: wurde die graue Flaeche gebraucht, steht das
# hier, und ab einem Fuenftel bricht der Lauf ab. Ein Bestand, in dem
# jedes vierte Bild grau ist, sieht in der Kachelansicht aus wie ein
# Fehler und ist als Demobestand wertlos.
if [ "$ersatzbilder" -gt 0 ]; then
	echo "  HINWEIS: $ersatzbilder von $count Bildern kamen von keiner Fotoquelle"
	echo "           und sind graue Ersatzflaechen."
	if [ "$ersatzbilder" -gt $(( gesamt / 5 )) ]; then
		abbruch "$ersatzbilder Ersatzflaechen sind zu viele.
         Die Fotodienste sind gerade nicht erreichbar. Spaeter noch
         einmal laufen lassen, das Skript ist wiederholbar."
	fi
fi


# Pruefen, bevor kopiert wird. Der Grund steht in AllowedFileType: das
# Portal prueft beim Upload die Signatur am Dateianfang, beim Ausliefern
# aber nicht mehr. Was hier an der Anwendung vorbei in den Speicher
# gelegt wird, laeuft ungeprueft durch. Eine Fehlerseite mit Status 200,
# die curl nicht abfaengt, faellt hier auf und nicht erst im Browser.
while IFS='|' read -r fid pid art seed stich lock breite hoehe url; do
	[ -z "${fid:-}" ] && continue
	kopf=$(head -c 12 "$STAGE/projects/$pid/$fid" | od -An -tx1 | tr -d ' \n')
	case "$art" in
		bild)  erwartet=ffd8ff ;;        # JPEG
		pdf)   erwartet=255044462d ;;    # %PDF-
		audio) erwartet=4f676753 ;;      # OggS
		video) erwartet="" ;;            # MP4: ftyp steht in Byte 4 bis 7
	esac
	if [ -n "$erwartet" ] && [ "${kopf#"$erwartet"}" = "$kopf" ]; then
		abbruch "$fid traegt nicht die erwartete Signatur (art $art)."
	fi
	if [ -z "$erwartet" ] && [ "${kopf:8:8}" != "66747970" ]; then
		abbruch "$fid ist kein MP4."
	fi
done <<< "$MANIFEST"
echo "  Signaturen geprueft"

# Uebertragen als tar-Strom und nicht mit "docker cp": unter Git Bash
# schreibt MSYS aus "$STAGE/." das Verzeichnis selbst, der Inhalt landete
# dann eine Ebene zu tief und jeder Abruf antwortete mit 500, ohne dass
# an den Zeilen etwas falsch waere.
im_container "mkdir -p '$ROOT'"
tar -C "$STAGE" -cf - . | docker exec -i "$BACKEND" sh -lc "tar -C '$ROOT' -xf -"
echo "  $count Dateien uebertragen"

# Die tatsaechlichen Groessen nachtragen. stored_file.size ist keine
# Zierde: FileController setzt daraus den Content-Length der Antwort.
# Steht dort eine andere Zahl als die Datei hat, bricht der Abruf ab,
# ohne dass irgendwo ein Fehler sichtbar wird. Derselbe Wert steht ein
# zweites Mal im Inhalt der DOCUMENT-Bloecke (attrs.size, Contract 2.5)
# und wird mitgezogen.
werte=""
while IFS='|' read -r fid pid art seed stich lock breite hoehe url; do
	[ -z "${fid:-}" ] && continue
	bytes=$(wc -c < "$STAGE/projects/$pid/$fid" | tr -d ' ')
	werte="$werte,('$fid'::uuid, $bytes::bigint)"
done <<< "$MANIFEST"
werte="${werte#,}"

sql <<SQL
begin;

update stored_file f
set size = v.bytes
from (values $werte) as v(id, bytes)
where f.id = v.id;

update block b
set content = jsonb_set(b.content, '{attrs,size}', to_jsonb(f.size))
from stored_file f
where b.type = 'DOCUMENT'
  and b.content -> 'attrs' ->> 'fileId' = f.id::text
  and f.id::text like 'd0d00022-%';

commit;
SQL
echo "  Dateigroessen nachgetragen"
echo

# -------------------------------------------------------------------
# 3) Gegenprobe.
# -------------------------------------------------------------------
echo "== 3/3  Gegenprobe =="

sql -c "
select p.status::text as status, count(*) as neu
from project p where p.id::text like 'd0d00021-%'
group by p.status order by 1;"

sql -c "
select f.abbreviation as fakultaet, count(*) as beitraege
from project p join faculty f on f.id = p.faculty_id
group by f.abbreviation order by 1;"

anzahl=$(sql -tAc "select count(*) from project where id::text like 'd0d00021-%';" | tr -d '[:space:]')
[ "$anzahl" = "30" ] || abbruch "Es sind $anzahl statt 30 Projekte entstanden.
         Wahrscheinlich fand ein join ein Kuerzel nicht."
echo "  30 Projekte angelegt"

autor_mitglied=$(sql -tAc "
select count(*) from project_member m join project p on p.id = m.project_id
where m.user_id = p.author_id;" | tr -d '[:space:]')
[ "$autor_mitglied" = "0" ] || abbruch "$autor_mitglied mal steht die Autor:in in project_member (Contract 3.13.1)."
echo "  Autor:in nirgends Projektmitglied"

kommentar=$(sql -tAc "
select count(*) from comment where (type = 'CHANGE_REQUEST') <> (status is not null);" | tr -d '[:space:]')
[ "$kommentar" = "0" ] || abbruch "$kommentar Kommentare verletzen die Statusregel aus Comment.java."
echo "  comment.status nur am CHANGE_REQUEST"

datum=$(sql -tAc "
select count(*) from project where (status = 'PUBLISHED') <> (published_at is not null);" | tr -d '[:space:]')
[ "$datum" = "0" ] || abbruch "$datum Projekte haben published_at ohne PUBLISHED oder umgekehrt."
echo "  published_at genau bei PUBLISHED"

top10=$(sql -tAc "
select count(*) from top10_entry e join project p on p.id = e.project_id
where p.status <> 'PUBLISHED';" | tr -d '[:space:]')
[ "$top10" = "0" ] || abbruch "$top10 Top-10-Plaetze zeigen auf unveroeffentlichte Beitraege."
# Geprueft wird, dass kein Platz doppelt vergeben ist und keiner ausserhalb
# von 1 bis 10 liegt. NICHT geprueft wird, ob es genau zehn sind: die Liste
# kann kuerzer bleiben, wenn jemand ueber die Administrationsseite selbst
# Beitraege aufgenommen hat und weniger Plaetze frei waren. Das ist kein
# Fehler, sondern der Vorrang der Handeingabe.
doppelt=$(sql -tAc "
select count(*) from (select position from top10_entry
                      group by position having count(*) > 1) x;" | tr -d '[:space:]')
[ "$doppelt" = "0" ] || abbruch "$doppelt Platznummern sind doppelt vergeben."
ausserhalb=$(sql -tAc "select count(*) from top10_entry where position not between 1 and 10;" | tr -d '[:space:]')
[ "$ausserhalb" = "0" ] || abbruch "$ausserhalb Top-10-Eintraege liegen ausserhalb von Platz 1 bis 10."
belegt=$(sql -tAc "select count(*) from top10_entry;" | tr -d '[:space:]')
eigene=$(sql -tAc "select count(*) from top10_entry where id::text like 'd0d00026-%';" | tr -d '[:space:]')
echo "  Top-10: $belegt Plaetze belegt, davon $eigene aus diesem Lauf, keine Dublette"
if [ "$eigene" -lt 7 ]; then
	echo "           HINWEIS: weniger als sieben, es waren nicht mehr Plaetze frei."
fi

tote=$(sql -tAc "
select count(*) from (
  select jsonb_array_elements(b.content->'attrs'->'items')->>'fileId' as fid
  from block b where b.type = 'GALLERY' and b.project_id::text like 'd0d00021-%'
  union all
  select b.content->'attrs'->>'fileId'
  from block b where b.type in ('IMAGE','AUDIO','DOCUMENT','VIDEO')
    and b.content->'attrs' ? 'fileId' and b.project_id::text like 'd0d00021-%'
) x where not exists (select 1 from stored_file f where f.id::text = x.fid);" | tr -d '[:space:]')
[ "$tote" = "0" ] || abbruch "$tote Bloecke zeigen auf eine Datei, die es nicht gibt."
echo "  Keine toten Dateiverweise"

typen=$(sql -tAc "select count(distinct type) from block where project_id::text like 'd0d00021-%';" | tr -d '[:space:]')
echo "  $typen von 15 Blocktypen im neuen Satz vertreten"

# Der Abruf ueber die Anwendung ist die einzige Pruefung, die Zeile und
# Bytes gemeinsam trifft: eine falsche Groesse oder ein falscher Pfad
# faellt hier auf und nicht erst im Browser.
erstes=$(sql -tAc "
select f.id from stored_file f join project p on p.id = f.project_id
where f.id::text like 'd0d00022-%' and p.status = 'PUBLISHED'
order by f.id limit 1;" | tr -d '[:space:]')
antwort=$(im_container "curl -sS -o /dev/null -w '%{http_code}:%{size_download}' \
	http://localhost:8080/api/files/$erstes" || true)
case "$antwort" in
	200:*) echo "  Titelbildabruf ueber die API: ${antwort%%:*} (${antwort##*:} Bytes)" ;;
	*)     echo "  HINWEIS: Der Titelbildabruf antwortete mit '$antwort'."
	       echo "           Laeuft das Backend schon? Die Daten stehen unabhaengig davon." ;;
esac

echo
echo "Fertig. Insgesamt stehen jetzt $(sql -tAc "select count(*) from project;" | tr -d '[:space:]') Projekte in der Entwicklungsdatenbank,"
echo "davon $(sql -tAc "select count(*) from project where status = 'PUBLISHED';" | tr -d '[:space:]') oeffentlich sichtbar."
